Object.assign(window.STATIC_TIMELINE, {"subtitles":[{"id":"S001","sequence":1,"startMs":1500,"endMs":12703,"startSeconds":1.5,"endSeconds":12.703,"text":"台灣九年級生的高難度人生｜第4集台灣十大「九年級生進社會後最有感的十種生活成本」01｜開場｜薪水才進來，怎麼又不見了？","displayText":"台灣九年級生的高難度人生｜第4集台灣十大「九年級生進社會後最有感的十種生活成本」01｜開場｜薪水才進來，怎麼又不見了？","startTimecode":"00:00:01,500","endTimecode":"00:00:12,703"},{"id":"S002","sequence":2,"startMs":12703,"endMs":17260,"startSeconds":12.703,"endSeconds":17.26,"text":"上一集，我們談的是AI正在改變九年級生怎麼工作。","displayText":"上一集，我們談的是AI正在改變九年級生怎麼工作。","startTimecode":"00:00:12,703","endTimecode":"00:00:17,260"},{"id":"S003","sequence":3,"startMs":17440,"endMs":21688,"startSeconds":17.44,"endSeconds":21.688,"text":"但這一集，我們想接著問一個更直接的問題。","displayText":"但這一集，我們想接著問一個更直接的問題。","startTimecode":"00:00:17,440","endTimecode":"00:00:21,688"},{"id":"S004","sequence":4,"startMs":21688,"endMs":26785,"startSeconds":21.688,"endSeconds":26.785,"text":"好，就算工作找到了，薪水也真的進帳了，接下來呢？","displayText":"好，就算工作找到了，薪水也真的進帳了，接下來呢？","startTimecode":"00:00:21,688","endTimecode":"00:00:26,785"},{"id":"S005","sequence":5,"startMs":26785,"endMs":32520,"startSeconds":26.785,"endSeconds":32.52,"text":"想像一個23歲的年輕人，第一次看到公司把薪水匯進戶頭。","displayText":"想像一個23歲的年輕人，第一次看到公司把薪水匯進戶頭。","startTimecode":"00:00:26,785","endTimecode":"00:00:32,520"},{"id":"S006","sequence":6,"startMs":32700,"endMs":34748,"startSeconds":32.7,"endSeconds":34.748,"text":"那一刻其實很有成就感。","displayText":"那一刻其實很有成就感。","startTimecode":"00:00:32,700","endTimecode":"00:00:34,748"},{"id":"S007","sequence":7,"startMs":34748,"endMs":38845,"startSeconds":34.748,"endSeconds":38.845,"text":"以前吃飯、搭車、買東西，很多時候還要靠家裡。","displayText":"以前吃飯、搭車、買東西，很多時候還要靠家裡。","startTimecode":"00:00:34,748","endTimecode":"00:00:38,845"},{"id":"S008","sequence":8,"startMs":38845,"endMs":43315,"startSeconds":38.845,"endSeconds":43.315,"text":"現在終於可以告訴自己，我開始靠自己的收入生活了。","displayText":"現在終於可以告訴自己，我開始靠自己的收入生活了。","startTimecode":"00:00:38,845","endTimecode":"00:00:43,315"},{"id":"S009","sequence":9,"startMs":43315,"endMs":49460,"startSeconds":43.315,"endSeconds":49.46,"text":"可是手機畫面上的那個數字，往往還沒有看習慣，下一個畫面就開始扣錢。","displayText":"可是手機畫面上的那個數字，往往還沒有看習慣，下一個畫面就開始扣錢。","startTimecode":"00:00:43,315","endTimecode":"00:00:49,460"},{"id":"S010","sequence":10,"startMs":49640,"endMs":52083,"startSeconds":49.64,"endSeconds":52.083,"text":"如果在外租屋，房租先來。","displayText":"如果在外租屋，房租先來。","startTimecode":"00:00:49,640","endTimecode":"00:00:52,083"},{"id":"S011","sequence":11,"startMs":52083,"endMs":53305,"startSeconds":52.083,"endSeconds":53.305,"text":"接著是三餐。","displayText":"接著是三餐。","startTimecode":"00:00:52,083","endTimecode":"00:00:53,305"},{"id":"S012","sequence":12,"startMs":53305,"endMs":55341,"startSeconds":53.305,"endSeconds":55.341,"text":"每天上下班要交通費。","displayText":"每天上下班要交通費。","startTimecode":"00:00:53,305","endTimecode":"00:00:55,341"},{"id":"S013","sequence":13,"startMs":55341,"endMs":57377,"startSeconds":55.341,"endSeconds":57.377,"text":"手機、網路不能沒有。","displayText":"手機、網路不能沒有。","startTimecode":"00:00:55,341","endTimecode":"00:00:57,377"},{"id":"S014","sequence":14,"startMs":57377,"endMs":61041,"startSeconds":57.377,"endSeconds":61.041,"text":"夏天回到租屋處，冷氣不可能永遠不開。","displayText":"夏天回到租屋處，冷氣不可能永遠不開。","startTimecode":"00:00:57,377","endTimecode":"00:01:01,041"},{"id":"S015","sequence":15,"startMs":61041,"endMs":67760,"startSeconds":61.041,"endSeconds":67.76,"text":"洗衣精、衛生紙、牙膏、垃圾袋，單看都不貴，可是沒有一樣能永遠不買。","displayText":"洗衣精、衛生紙、牙膏、垃圾袋，單看都不貴，可是沒有一樣能永遠不買。","startTimecode":"00:01:01,041","endTimecode":"00:01:07,760"},{"id":"S016","sequence":16,"startMs":67940,"endMs":70644,"startSeconds":67.94,"endSeconds":70.644,"text":"偶爾同事約聚餐，朋友約看電影。","displayText":"偶爾同事約聚餐，朋友約看電影。","startTimecode":"00:01:07,940","endTimecode":"00:01:10,644"},{"id":"S017","sequence":17,"startMs":70644,"endMs":74611,"startSeconds":70.644,"endSeconds":74.611,"text":"工作需要新的軟體、證照或課程，可能又是一筆。","displayText":"工作需要新的軟體、證照或課程，可能又是一筆。","startTimecode":"00:01:10,644","endTimecode":"00:01:14,611"},{"id":"S018","sequence":18,"startMs":74611,"endMs":80380,"startSeconds":74.611,"endSeconds":80.38,"text":"一個月還沒有走完，原本看起來完整的一份薪水，已經被切成很多小塊。","displayText":"一個月還沒有走完，原本看起來完整的一份薪水，已經被切成很多小塊。","startTimecode":"00:01:14,611","endTimecode":"00:01:20,380"},{"id":"S019","sequence":19,"startMs":80560,"endMs":86287,"startSeconds":80.56,"endSeconds":86.287,"text":"所以，剛進社會之後，真正讓人有感的，也許不只是「薪水多少」。","displayText":"所以，剛進社會之後，真正讓人有感的，也許不只是「薪水多少」。","startTimecode":"00:01:20,560","endTimecode":"00:01:26,287"},{"id":"S020","sequence":20,"startMs":86287,"endMs":87815,"startSeconds":86.287,"endSeconds":87.815,"text":"而是另一個問題。","displayText":"而是另一個問題。","startTimecode":"00:01:26,287","endTimecode":"00:01:27,815"},{"id":"S021","sequence":21,"startMs":87815,"endMs":91060,"startSeconds":87.815,"endSeconds":91.06,"text":"這些錢進來以後，到底還能留下多少？","displayText":"這些錢進來以後，到底還能留下多少？","startTimecode":"00:01:27,815","endTimecode":"00:01:31,060"},{"id":"S022","sequence":22,"startMs":91060,"endMs":97360,"startSeconds":91.06,"endSeconds":97.36,"text":"2026年，2001到2010年出生的九年級生，大約16到25歲。","displayText":"2026年，2001到2010年出生的九年級生，大約16到25歲。","startTimecode":"00:01:31,060","endTimecode":"00:01:37,360"},{"id":"S023","sequence":23,"startMs":97540,"endMs":101434,"startSeconds":97.54,"endSeconds":101.434,"text":"這十年出生的人，不是每一個都已經工作。","displayText":"這十年出生的人，不是每一個都已經工作。","startTimecode":"00:01:37,540","endTimecode":"00:01:41,434"},{"id":"S024","sequence":24,"startMs":101434,"endMs":107172,"startSeconds":101.434,"endSeconds":107.172,"text":"有些還在高中，有些正在大學，有些才剛開始第一份全職工作。","displayText":"有些還在高中，有些正在大學，有些才剛開始第一份全職工作。","startTimecode":"00:01:41,434","endTimecode":"00:01:47,172"},{"id":"S025","sequence":25,"startMs":107172,"endMs":112500,"startSeconds":107.172,"endSeconds":112.5,"text":"因此這一集不會假裝所有九年級生都有相同的收入與支出。","displayText":"因此這一集不會假裝所有九年級生都有相同的收入與支出。","startTimecode":"00:01:47,172","endTimecode":"00:01:52,500"},{"id":"S026","sequence":26,"startMs":112680,"endMs":120753,"startSeconds":112.68,"endSeconds":120.753,"text":"我們主要把鏡頭放在20到25歲，正在大學後期、剛畢業、開始工作，或第一次嘗試經濟獨立的這群人。","displayText":"我們主要把鏡頭放在20到25歲，正在大學後期、剛畢業、開始工作，或第一次嘗試經濟獨立的這群人。","startTimecode":"00:01:52,680","endTimecode":"00:02:00,753"},{"id":"S027","sequence":27,"startMs":120753,"endMs":124360,"startSeconds":120.753,"endSeconds":124.36,"text":"我們也不準備告訴你，哪一樣東西「最會漲」。","displayText":"我們也不準備告訴你，哪一樣東西「最會漲」。","startTimecode":"00:02:00,753","endTimecode":"00:02:04,360"},{"id":"S028","sequence":28,"startMs":124540,"endMs":133210,"startSeconds":124.54,"endSeconds":133.21,"text":"我們真正想知道的是，一個收入還在起步的人，哪些支出最難避開、最常發生，也最容易壓縮他可以自由運用的錢。","displayText":"我們真正想知道的是，一個收入還在起步的人，哪些支出最難避開、最常發生，也最容易壓縮他可以自由運用的錢。","startTimecode":"00:02:04,540","endTimecode":"00:02:13,210"},{"id":"S029","sequence":29,"startMs":133210,"endMs":134740,"startSeconds":133.21,"endSeconds":134.74,"text":"這就是今天的題目。","displayText":"這就是今天的題目。","startTimecode":"00:02:13,210","endTimecode":"00:02:14,740"},{"id":"S030","sequence":30,"startMs":134920,"endMs":139867,"startSeconds":134.92,"endSeconds":139.867,"text":"台灣十大，九年級生進社會後最有感的十種生活成本。","displayText":"台灣十大，九年級生進社會後最有感的十種生活成本。","startTimecode":"00:02:14,920","endTimecode":"00:02:19,867"},{"id":"S031","sequence":31,"startMs":139867,"endMs":149760,"startSeconds":139.867,"endSeconds":149.76,"text":"02｜十大怎麼排｜我們不是找最貴，而是找最有感先說清楚，接下來的十大，不是政府公布的官方排行榜。","displayText":"02｜十大怎麼排｜我們不是找最貴，而是找最有感先說清楚，接下來的十大，不是政府公布的官方排行榜。","startTimecode":"00:02:19,867","endTimecode":"00:02:29,760"},{"id":"S032","sequence":32,"startMs":149940,"endMs":155238,"startSeconds":149.94,"endSeconds":155.238,"text":"我們建立一個節目用的分析框架，叫做「青年生活成本壓力指數」。","displayText":"我們建立一個節目用的分析框架，叫做「青年生活成本壓力指數」。","startTimecode":"00:02:29,940","endTimecode":"00:02:35,238"},{"id":"S033","sequence":33,"startMs":155238,"endMs":161420,"startSeconds":155.238,"endSeconds":161.42,"text":"它不是正式統計指數，而是把官方資料翻譯成年輕人比較容易理解的生活問題。","displayText":"它不是正式統計指數，而是把官方資料翻譯成年輕人比較容易理解的生活問題。","startTimecode":"00:02:35,238","endTimecode":"00:02:41,420"},{"id":"S034","sequence":34,"startMs":161600,"endMs":162851,"startSeconds":161.6,"endSeconds":162.851,"text":"我們看五件事。","displayText":"我們看五件事。","startTimecode":"00:02:41,600","endTimecode":"00:02:42,851"},{"id":"S035","sequence":35,"startMs":162851,"endMs":164281,"startSeconds":162.851,"endSeconds":164.281,"text":"第一，支出占比。","displayText":"第一，支出占比。","startTimecode":"00:02:42,851","endTimecode":"00:02:44,281"},{"id":"S036","sequence":36,"startMs":164281,"endMs":168034,"startSeconds":164.281,"endSeconds":168.034,"text":"這筆錢在家庭或生活支出裡，占的位置大不大。","displayText":"這筆錢在家庭或生活支出裡，占的位置大不大。","startTimecode":"00:02:44,281","endTimecode":"00:02:48,034"},{"id":"S037","sequence":37,"startMs":168034,"endMs":169463,"startSeconds":168.034,"endSeconds":169.463,"text":"第二，物價變動。","displayText":"第二，物價變動。","startTimecode":"00:02:48,034","endTimecode":"00:02:49,463"},{"id":"S038","sequence":38,"startMs":169463,"endMs":172680,"startSeconds":169.463,"endSeconds":172.68,"text":"同樣的東西，近年價格是不是持續改變。","displayText":"同樣的東西，近年價格是不是持續改變。","startTimecode":"00:02:49,463","endTimecode":"00:02:52,680"},{"id":"S039","sequence":39,"startMs":172860,"endMs":174393,"startSeconds":172.86,"endSeconds":174.393,"text":"第三，支出頻率。","displayText":"第三，支出頻率。","startTimecode":"00:02:52,860","endTimecode":"00:02:54,393"},{"id":"S040","sequence":40,"startMs":174393,"endMs":178226,"startSeconds":174.393,"endSeconds":178.226,"text":"一年買一次，跟每天都要付，感受完全不同。","displayText":"一年買一次，跟每天都要付，感受完全不同。","startTimecode":"00:02:54,393","endTimecode":"00:02:58,226"},{"id":"S041","sequence":41,"startMs":178226,"endMs":179951,"startSeconds":178.226,"endSeconds":179.951,"text":"第四，不可避免性。","displayText":"第四，不可避免性。","startTimecode":"00:02:58,226","endTimecode":"00:02:59,951"},{"id":"S042","sequence":42,"startMs":179951,"endMs":183975,"startSeconds":179.951,"endSeconds":183.975,"text":"有些消費可以延後，有些卻幾乎每天都會碰到。","displayText":"有些消費可以延後，有些卻幾乎每天都會碰到。","startTimecode":"00:02:59,951","endTimecode":"00:03:03,975"},{"id":"S043","sequence":43,"startMs":183975,"endMs":185700,"startSeconds":183.975,"endSeconds":185.7,"text":"第五，青年衝擊度。","displayText":"第五，青年衝擊度。","startTimecode":"00:03:03,975","endTimecode":"00:03:05,700"},{"id":"S044","sequence":44,"startMs":185880,"endMs":191587,"startSeconds":185.88,"endSeconds":191.587,"text":"同樣一筆3000元，對高收入者和剛領第一份薪水的人，壓力不一樣。","displayText":"同樣一筆3000元，對高收入者和剛領第一份薪水的人，壓力不一樣。","startTimecode":"00:03:05,880","endTimecode":"00:03:11,587"},{"id":"S045","sequence":45,"startMs":191587,"endMs":194083,"startSeconds":191.587,"endSeconds":194.083,"text":"資料以行政院主計總處為核心。","displayText":"資料以行政院主計總處為核心。","startTimecode":"00:03:11,587","endTimecode":"00:03:14,083"},{"id":"S046","sequence":46,"startMs":194083,"endMs":198720,"startSeconds":194.083,"endSeconds":198.72,"text":"家庭收支調查告訴我們，台灣家庭的錢大致花到哪些地方。","displayText":"家庭收支調查告訴我們，台灣家庭的錢大致花到哪些地方。","startTimecode":"00:03:14,083","endTimecode":"00:03:18,720"},{"id":"S047","sequence":47,"startMs":198900,"endMs":203519,"startSeconds":198.9,"endSeconds":203.519,"text":"消費者物價指數，也就是CPI，讓我們觀察價格怎麼變。","displayText":"消費者物價指數，也就是CPI，讓我們觀察價格怎麼變。","startTimecode":"00:03:18,900","endTimecode":"00:03:23,519"},{"id":"S048","sequence":48,"startMs":203519,"endMs":208848,"startSeconds":203.519,"endSeconds":208.848,"text":"薪資統計則幫助我們理解，這些生活成本是在什麼收入背景下發生。","displayText":"薪資統計則幫助我們理解，這些生活成本是在什麼收入背景下發生。","startTimecode":"00:03:23,519","endTimecode":"00:03:28,848"},{"id":"S049","sequence":49,"startMs":208848,"endMs":210980,"startSeconds":208.848,"endSeconds":210.98,"text":"這裡有一個很重要的限制。","displayText":"這裡有一個很重要的限制。","startTimecode":"00:03:28,848","endTimecode":"00:03:30,980"},{"id":"S050","sequence":50,"startMs":211160,"endMs":217715,"startSeconds":211.16,"endSeconds":217.715,"text":"主計總處的家庭收支調查，很多資料的統計單位是「家庭」，不是「九年級生個人」。","displayText":"主計總處的家庭收支調查，很多資料的統計單位是「家庭」，不是「九年級生個人」。","startTimecode":"00:03:31,160","endTimecode":"00:03:37,715"},{"id":"S051","sequence":51,"startMs":217715,"endMs":222200,"startSeconds":217.715,"endSeconds":222.2,"text":"所以如果官方資料寫的是平均每戶，我們就會說平均每戶；","displayText":"所以如果官方資料寫的是平均每戶，我們就會說平均每戶；","startTimecode":"00:03:37,715","endTimecode":"00:03:42,200"},{"id":"S052","sequence":52,"startMs":222380,"endMs":226823,"startSeconds":222.38,"endSeconds":226.823,"text":"如果是全體受僱員工，我們就說全體受僱員工。","displayText":"如果是全體受僱員工，我們就說全體受僱員工。","startTimecode":"00:03:42,380","endTimecode":"00:03:46,823"},{"id":"S053","sequence":53,"startMs":226823,"endMs":231477,"startSeconds":226.823,"endSeconds":231.477,"text":"我們不會把家庭平均，偷換成「九年級生平均」。","displayText":"我們不會把家庭平均，偷換成「九年級生平均」。","startTimecode":"00:03:46,823","endTimecode":"00:03:51,477"},{"id":"S054","sequence":54,"startMs":231477,"endMs":241420,"startSeconds":231.477,"endSeconds":241.42,"text":"2025年，主計總處公布的家庭收支資料顯示，每戶可支配所得平均數是121萬元，中位數是101.","displayText":"2025年，主計總處公布的家庭收支資料顯示，每戶可支配所得平均數是121萬元，中位數是101.","startTimecode":"00:03:51,477","endTimecode":"00:04:01,420"},{"id":"S055","sequence":55,"startMs":241600,"endMs":242472,"startSeconds":241.6,"endSeconds":242.472,"text":"8萬元；","displayText":"8萬元；","startTimecode":"00:04:01,600","endTimecode":"00:04:02,472"},{"id":"S056","sequence":56,"startMs":242472,"endMs":247048,"startSeconds":242.472,"endSeconds":247.048,"text":"每人可支配所得平均數45萬元，中位數36.","displayText":"每人可支配所得平均數45萬元，中位數36.","startTimecode":"00:04:02,472","endTimecode":"00:04:07,048"},{"id":"S057","sequence":57,"startMs":247048,"endMs":247920,"startSeconds":247.048,"endSeconds":247.92,"text":"7萬元。","displayText":"7萬元。","startTimecode":"00:04:07,048","endTimecode":"00:04:07,920"},{"id":"S058","sequence":58,"startMs":247920,"endMs":252932,"startSeconds":247.92,"endSeconds":252.932,"text":"這些數字是家庭所得背景，不是20歲青年的薪水。","displayText":"這些數字是家庭所得背景，不是20歲青年的薪水。","startTimecode":"00:04:07,920","endTimecode":"00:04:12,932"},{"id":"S059","sequence":59,"startMs":252932,"endMs":262520,"startSeconds":252.932,"endSeconds":262.52,"text":"另一方面，2025年全體受僱員工每月經常性薪資平均數為47884元，中位數38406元；","displayText":"另一方面，2025年全體受僱員工每月經常性薪資平均數為47884元，中位數38406元；","startTimecode":"00:04:12,932","endTimecode":"00:04:22,520"},{"id":"S060","sequence":60,"startMs":262700,"endMs":265632,"startSeconds":262.7,"endSeconds":265.632,"text":"本國籍全時受僱員工的數字又不同。","displayText":"本國籍全時受僱員工的數字又不同。","startTimecode":"00:04:22,700","endTimecode":"00:04:25,632"},{"id":"S061","sequence":61,"startMs":265632,"endMs":271312,"startSeconds":265.632,"endSeconds":271.312,"text":"所以，平均薪資不是每個年輕人的起薪，中位數也不是每個人的實領。","displayText":"所以，平均薪資不是每個年輕人的起薪，中位數也不是每個人的實領。","startTimecode":"00:04:25,632","endTimecode":"00:04:31,312"},{"id":"S062","sequence":62,"startMs":271312,"endMs":273511,"startSeconds":271.312,"endSeconds":273.511,"text":"這正是本集最重要的原則。","displayText":"這正是本集最重要的原則。","startTimecode":"00:04:31,312","endTimecode":"00:04:33,511"},{"id":"S063","sequence":63,"startMs":273511,"endMs":276260,"startSeconds":273.511,"endSeconds":276.26,"text":"不把不同口徑的數字硬湊在一起。","displayText":"不把不同口徑的數字硬湊在一起。","startTimecode":"00:04:33,511","endTimecode":"00:04:36,260"},{"id":"S064","sequence":64,"startMs":276440,"endMs":278613,"startSeconds":276.44,"endSeconds":278.613,"text":"我們只用它們回答一件事。","displayText":"我們只用它們回答一件事。","startTimecode":"00:04:36,440","endTimecode":"00:04:38,613"},{"id":"S065","sequence":65,"startMs":278613,"endMs":283863,"startSeconds":278.613,"endSeconds":283.863,"text":"當收入還在起步，哪些生活成本最容易讓人覺得，錢真的不經花？","displayText":"當收入還在起步，哪些生活成本最容易讓人覺得，錢真的不經花？","startTimecode":"00:04:38,613","endTimecode":"00:04:43,863"},{"id":"S066","sequence":66,"startMs":283863,"endMs":285312,"startSeconds":283.863,"endSeconds":285.312,"text":"從第10名開始。","displayText":"從第10名開始。","startTimecode":"00:04:43,863","endTimecode":"00:04:45,312"},{"id":"S067","sequence":67,"startMs":285312,"endMs":290200,"startSeconds":285.312,"endSeconds":290.2,"text":"03｜第10名｜不是天天買，卻不能永遠不買｜衣著與鞋類","displayText":"03｜第10名｜不是天天買，卻不能永遠不買｜衣著與鞋類","startTimecode":"00:04:45,312","endTimecode":"00:04:50,200"},{"id":"S068","sequence":68,"startMs":290380,"endMs":292350,"startSeconds":290.38,"endSeconds":292.35,"text":"第10名，衣著與鞋類。","displayText":"第10名，衣著與鞋類。","startTimecode":"00:04:50,380","endTimecode":"00:04:52,350"},{"id":"S069","sequence":69,"startMs":292350,"endMs":296289,"startSeconds":292.35,"endSeconds":296.289,"text":"很多人第一個反應可能是，衣服不是可以少買嗎？","displayText":"很多人第一個反應可能是，衣服不是可以少買嗎？","startTimecode":"00:04:52,350","endTimecode":"00:04:56,289"},{"id":"S070","sequence":70,"startMs":296289,"endMs":296826,"startSeconds":296.289,"endSeconds":296.826,"text":"沒錯。","displayText":"沒錯。","startTimecode":"00:04:56,289","endTimecode":"00:04:56,826"},{"id":"S071","sequence":71,"startMs":296826,"endMs":300586,"startSeconds":296.826,"endSeconds":300.586,"text":"這也是它排在第10名，而不是前幾名的原因。","displayText":"這也是它排在第10名，而不是前幾名的原因。","startTimecode":"00:04:56,826","endTimecode":"00:05:00,586"},{"id":"S072","sequence":72,"startMs":300586,"endMs":305420,"startSeconds":300.586,"endSeconds":305.42,"text":"衣著最大的特色，是它不像房租、三餐那樣每天逼著你付錢。","displayText":"衣著最大的特色，是它不像房租、三餐那樣每天逼著你付錢。","startTimecode":"00:05:00,586","endTimecode":"00:05:05,420"},{"id":"S073","sequence":73,"startMs":305600,"endMs":309204,"startSeconds":305.6,"endSeconds":309.204,"text":"一件衣服可以穿很久，一雙鞋也可以撐一段時間。","displayText":"一件衣服可以穿很久，一雙鞋也可以撐一段時間。","startTimecode":"00:05:05,600","endTimecode":"00:05:09,204"},{"id":"S074","sequence":74,"startMs":309204,"endMs":312480,"startSeconds":309.204,"endSeconds":312.48,"text":"如果收入吃緊，最簡單的方法就是延後購買。","displayText":"如果收入吃緊，最簡單的方法就是延後購買。","startTimecode":"00:05:09,204","endTimecode":"00:05:12,480"},{"id":"S075","sequence":75,"startMs":312480,"endMs":315920,"startSeconds":312.48,"endSeconds":315.92,"text":"但進入社會之後，衣服又不只是「想不想買」。","displayText":"但進入社會之後，衣服又不只是「想不想買」。","startTimecode":"00:05:12,480","endTimecode":"00:05:15,920"},{"id":"S076","sequence":76,"startMs":316100,"endMs":319227,"startSeconds":316.1,"endSeconds":319.227,"text":"第一次面試，需要一套看起來合適的服裝。","displayText":"第一次面試，需要一套看起來合適的服裝。","startTimecode":"00:05:16,100","endTimecode":"00:05:19,227"},{"id":"S077","sequence":77,"startMs":319227,"endMs":324330,"startSeconds":319.227,"endSeconds":324.33,"text":"開始上班之後，學生時代的T恤、短褲，不一定適合每一種工作環境。","displayText":"開始上班之後，學生時代的T恤、短褲，不一定適合每一種工作環境。","startTimecode":"00:05:19,227","endTimecode":"00:05:24,330"},{"id":"S078","sequence":78,"startMs":324330,"endMs":326140,"startSeconds":324.33,"endSeconds":326.14,"text":"鞋子磨壞了，還是得換。","displayText":"鞋子磨壞了，還是得換。","startTimecode":"00:05:24,330","endTimecode":"00:05:26,140"},{"id":"S079","sequence":79,"startMs":326320,"endMs":330048,"startSeconds":326.32,"endSeconds":330.048,"text":"冬天需要外套，正式場合需要比較得體的穿著。","displayText":"冬天需要外套，正式場合需要比較得體的穿著。","startTimecode":"00:05:26,320","endTimecode":"00:05:30,048"},{"id":"S080","sequence":80,"startMs":330048,"endMs":339280,"startSeconds":330.048,"endSeconds":339.28,"text":"假設一位剛進公司的23歲青年，第一個月沒有大買特買，只是添一件襯衫、一條工作用長褲，再換掉穿了很久的鞋。","displayText":"假設一位剛進公司的23歲青年，第一個月沒有大買特買，只是添一件襯衫、一條工作用長褲，再換掉穿了很久的鞋。","startTimecode":"00:05:30,048","endTimecode":"00:05:39,280"},{"id":"S081","sequence":81,"startMs":339460,"endMs":342230,"startSeconds":339.46,"endSeconds":342.23,"text":"單月支出可能突然比平常高很多。","displayText":"單月支出可能突然比平常高很多。","startTimecode":"00:05:39,460","endTimecode":"00:05:42,230"},{"id":"S082","sequence":82,"startMs":342230,"endMs":344815,"startSeconds":342.23,"endSeconds":344.815,"text":"可是下個月，他完全可以不買。","displayText":"可是下個月，他完全可以不買。","startTimecode":"00:05:42,230","endTimecode":"00:05:44,815"},{"id":"S083","sequence":83,"startMs":344815,"endMs":349801,"startSeconds":344.815,"endSeconds":349.801,"text":"所以衣著成本的壓力，通常是「偶發型」，不是「持續型」。","displayText":"所以衣著成本的壓力，通常是「偶發型」，不是「持續型」。","startTimecode":"00:05:44,815","endTimecode":"00:05:49,801"},{"id":"S084","sequence":84,"startMs":349801,"endMs":352940,"startSeconds":349.801,"endSeconds":352.94,"text":"從生活成本壓力來看，它有一個好處。","displayText":"從生活成本壓力來看，它有一個好處。","startTimecode":"00:05:49,801","endTimecode":"00:05:52,940"},{"id":"S085","sequence":85,"startMs":353120,"endMs":354018,"startSeconds":353.12,"endSeconds":354.018,"text":"可以延後。","displayText":"可以延後。","startTimecode":"00:05:53,120","endTimecode":"00:05:54,018"},{"id":"S086","sequence":86,"startMs":354018,"endMs":354917,"startSeconds":354.018,"endSeconds":354.917,"text":"可以比較。","displayText":"可以比較。","startTimecode":"00:05:54,018","endTimecode":"00:05:54,917"},{"id":"S087","sequence":87,"startMs":354917,"endMs":355995,"startSeconds":354.917,"endSeconds":355.995,"text":"可以等折扣。","displayText":"可以等折扣。","startTimecode":"00:05:54,917","endTimecode":"00:05:55,995"},{"id":"S088","sequence":88,"startMs":355995,"endMs":358511,"startSeconds":355.995,"endSeconds":358.511,"text":"也可以用原來的衣服撐久一點。","displayText":"也可以用原來的衣服撐久一點。","startTimecode":"00:05:55,995","endTimecode":"00:05:58,511"},{"id":"S089","sequence":89,"startMs":358511,"endMs":365160,"startSeconds":358.511,"endSeconds":365.16,"text":"對收入起步的年輕人來說，這種可以控制時間點的支出，雖然有感，卻還留有選擇。","displayText":"對收入起步的年輕人來說，這種可以控制時間點的支出，雖然有感，卻還留有選擇。","startTimecode":"00:05:58,511","endTimecode":"00:06:05,160"},{"id":"S090","sequence":90,"startMs":365340,"endMs":368226,"startSeconds":365.34,"endSeconds":368.226,"text":"而下一項，選擇就開始變少了。","displayText":"而下一項，選擇就開始變少了。","startTimecode":"00:06:05,340","endTimecode":"00:06:08,226"},{"id":"S091","sequence":91,"startMs":368226,"endMs":375852,"startSeconds":368.226,"endSeconds":375.852,"text":"04｜第9名｜看起來不大，卻每個月準時出現｜手機與通訊第9名，手機與通訊。","displayText":"04｜第9名｜看起來不大，卻每個月準時出現｜手機與通訊第9名，手機與通訊。","startTimecode":"00:06:08,226","endTimecode":"00:06:15,852"},{"id":"S092","sequence":92,"startMs":375852,"endMs":380180,"startSeconds":375.852,"endSeconds":380.18,"text":"手機月租、網路費，看起來不像房租那麼驚人。","displayText":"手機月租、網路費，看起來不像房租那麼驚人。","startTimecode":"00:06:15,852","endTimecode":"00:06:20,180"},{"id":"S093","sequence":93,"startMs":380360,"endMs":381920,"startSeconds":380.36,"endSeconds":381.92,"text":"但它有一個特色。","displayText":"但它有一個特色。","startTimecode":"00:06:20,360","endTimecode":"00:06:21,920"},{"id":"S094","sequence":94,"startMs":381920,"endMs":383091,"startSeconds":381.92,"endSeconds":383.091,"text":"每個月都來。","displayText":"每個月都來。","startTimecode":"00:06:21,920","endTimecode":"00:06:23,091"},{"id":"S095","sequence":95,"startMs":383091,"endMs":386407,"startSeconds":383.091,"endSeconds":386.407,"text":"而且現在的手機早就不只是娛樂工具。","displayText":"而且現在的手機早就不只是娛樂工具。","startTimecode":"00:06:23,091","endTimecode":"00:06:26,407"},{"id":"S096","sequence":96,"startMs":386407,"endMs":396160,"startSeconds":386.407,"endSeconds":396.16,"text":"公司群組、電子郵件、視訊會議、銀行驗證、地圖導航、求職通知、雲端文件，甚至政府服務，都可能在手機裡。","displayText":"公司群組、電子郵件、視訊會議、銀行驗證、地圖導航、求職通知、雲端文件，甚至政府服務，都可能在手機裡。","startTimecode":"00:06:26,407","endTimecode":"00:06:36,160"},{"id":"S097","sequence":97,"startMs":396340,"endMs":401541,"startSeconds":396.34,"endSeconds":401.541,"text":"對剛進社會的九年級生來說，通訊已經很接近工作與生活的基礎設施。","displayText":"對剛進社會的九年級生來說，通訊已經很接近工作與生活的基礎設施。","startTimecode":"00:06:36,340","endTimecode":"00:06:41,541"},{"id":"S098","sequence":98,"startMs":401541,"endMs":403889,"startSeconds":401.541,"endSeconds":403.889,"text":"你當然可以選比較便宜的方案。","displayText":"你當然可以選比較便宜的方案。","startTimecode":"00:06:41,541","endTimecode":"00:06:43,889"},{"id":"S099","sequence":99,"startMs":403889,"endMs":405399,"startSeconds":403.889,"endSeconds":405.399,"text":"可以不追最新手機。","displayText":"可以不追最新手機。","startTimecode":"00:06:43,889","endTimecode":"00:06:45,399"},{"id":"S100","sequence":100,"startMs":405399,"endMs":407580,"startSeconds":405.399,"endSeconds":407.58,"text":"可以把一支手機用四、五年。","displayText":"可以把一支手機用四、五年。","startTimecode":"00:06:45,399","endTimecode":"00:06:47,580"},{"id":"S101","sequence":101,"startMs":407760,"endMs":412301,"startSeconds":407.76,"endSeconds":412.301,"text":"但你很難說，我這個月想省錢，所以完全不用網路。","displayText":"但你很難說，我這個月想省錢，所以完全不用網路。","startTimecode":"00:06:47,760","endTimecode":"00:06:52,301"},{"id":"S102","sequence":102,"startMs":412301,"endMs":414867,"startSeconds":412.301,"endSeconds":414.867,"text":"這就是它和衣服最大的差別。","displayText":"這就是它和衣服最大的差別。","startTimecode":"00:06:52,301","endTimecode":"00:06:54,867"},{"id":"S103","sequence":103,"startMs":414867,"endMs":420000,"startSeconds":414.867,"endSeconds":420.0,"text":"衣服可以延後買，通訊通常只能降低規格，很難完全取消。","displayText":"衣服可以延後買，通訊通常只能降低規格，很難完全取消。","startTimecode":"00:06:54,867","endTimecode":"00:07:00,000"},{"id":"S104","sequence":104,"startMs":420180,"endMs":426873,"startSeconds":420.18,"endSeconds":426.873,"text":"假設一個年輕人每月固定有電信費，再加上家中或租屋處網路，單筆不一定讓人心痛。","displayText":"假設一個年輕人每月固定有電信費，再加上家中或租屋處網路，單筆不一定讓人心痛。","startTimecode":"00:07:00,180","endTimecode":"00:07:06,873"},{"id":"S105","sequence":105,"startMs":426873,"endMs":429515,"startSeconds":426.873,"endSeconds":429.515,"text":"可是它的特色不是「一次很貴」。","displayText":"可是它的特色不是「一次很貴」。","startTimecode":"00:07:06,873","endTimecode":"00:07:09,515"},{"id":"S106","sequence":106,"startMs":429515,"endMs":431100,"startSeconds":429.515,"endSeconds":431.1,"text":"而是「一直存在」。","displayText":"而是「一直存在」。","startTimecode":"00:07:09,515","endTimecode":"00:07:11,100"},{"id":"S107","sequence":107,"startMs":431280,"endMs":435827,"startSeconds":431.28,"endSeconds":435.827,"text":"生活成本最容易被低估的，往往就是這種固定扣款。","displayText":"生活成本最容易被低估的，往往就是這種固定扣款。","startTimecode":"00:07:11,280","endTimecode":"00:07:15,827"},{"id":"S108","sequence":108,"startMs":435827,"endMs":444920,"startSeconds":435.827,"endSeconds":444.92,"text":"每一筆都不致命，可是當房租、交通、飲食也同時存在時，它就成為那張每個月一定會出現的帳單之一。","displayText":"每一筆都不致命，可是當房租、交通、飲食也同時存在時，它就成為那張每個月一定會出現的帳單之一。","startTimecode":"00:07:15,827","endTimecode":"00:07:24,920"},{"id":"S109","sequence":109,"startMs":445100,"endMs":449110,"startSeconds":445.1,"endSeconds":449.11,"text":"不過至少，通訊方案還能比較、降級、換約。","displayText":"不過至少，通訊方案還能比較、降級、換約。","startTimecode":"00:07:25,100","endTimecode":"00:07:29,110"},{"id":"S110","sequence":110,"startMs":449110,"endMs":450714,"startSeconds":449.11,"endSeconds":450.714,"text":"下一項就更麻煩。","displayText":"下一項就更麻煩。","startTimecode":"00:07:29,110","endTimecode":"00:07:30,714"},{"id":"S111","sequence":111,"startMs":450714,"endMs":455726,"startSeconds":450.714,"endSeconds":455.726,"text":"因為當身體真的需要時，你不能跟它說，下個月再處理。","displayText":"因為當身體真的需要時，你不能跟它說，下個月再處理。","startTimecode":"00:07:30,714","endTimecode":"00:07:35,726"},{"id":"S112","sequence":112,"startMs":455726,"endMs":461140,"startSeconds":455.726,"endSeconds":461.14,"text":"05｜第8名｜平常感覺不到，一來就不能不付｜醫療與保健","displayText":"05｜第8名｜平常感覺不到，一來就不能不付｜醫療與保健","startTimecode":"00:07:35,726","endTimecode":"00:07:41,140"},{"id":"S113","sequence":113,"startMs":461320,"endMs":463183,"startSeconds":461.32,"endSeconds":463.183,"text":"第8名，醫療與保健。","displayText":"第8名，醫療與保健。","startTimecode":"00:07:41,320","endTimecode":"00:07:43,183"},{"id":"S114","sequence":114,"startMs":463183,"endMs":470075,"startSeconds":463.183,"endSeconds":470.075,"text":"台灣有全民健保，這讓許多醫療支出的壓力，和沒有全民醫療保障的地方很不一樣。","displayText":"台灣有全民健保，這讓許多醫療支出的壓力，和沒有全民醫療保障的地方很不一樣。","startTimecode":"00:07:43,183","endTimecode":"00:07:50,075"},{"id":"S115","sequence":115,"startMs":470075,"endMs":473800,"startSeconds":470.075,"endSeconds":473.8,"text":"但有健保，不等於生活裡完全沒有醫療成本。","displayText":"但有健保，不等於生活裡完全沒有醫療成本。","startTimecode":"00:07:50,075","endTimecode":"00:07:53,800"},{"id":"S116","sequence":116,"startMs":473980,"endMs":482801,"startSeconds":473.98,"endSeconds":482.801,"text":"掛號、部分負擔、牙科自費、眼鏡、藥品、復健，以及某些健保沒有完全涵蓋的項目，都可能突然出現。","displayText":"掛號、部分負擔、牙科自費、眼鏡、藥品、復健，以及某些健保沒有完全涵蓋的項目，都可能突然出現。","startTimecode":"00:07:53,980","endTimecode":"00:08:02,801"},{"id":"S117","sequence":117,"startMs":482801,"endMs":487020,"startSeconds":482.801,"endSeconds":487.02,"text":"醫療成本最特別的地方，是它不一定每個月發生。","displayText":"醫療成本最特別的地方，是它不一定每個月發生。","startTimecode":"00:08:02,801","endTimecode":"00:08:07,020"},{"id":"S118","sequence":118,"startMs":487200,"endMs":489312,"startSeconds":487.2,"endSeconds":489.312,"text":"所以平常很容易被忽略。","displayText":"所以平常很容易被忽略。","startTimecode":"00:08:07,200","endTimecode":"00:08:09,312"},{"id":"S119","sequence":119,"startMs":489312,"endMs":493728,"startSeconds":489.312,"endSeconds":493.728,"text":"一個22歲的人可能連續幾個月沒有任何醫療支出。","displayText":"一個22歲的人可能連續幾個月沒有任何醫療支出。","startTimecode":"00:08:09,312","endTimecode":"00:08:13,728"},{"id":"S120","sequence":120,"startMs":493728,"endMs":499680,"startSeconds":493.728,"endSeconds":499.68,"text":"可是某一天牙齒突然痛、眼鏡壞了、運動受傷，支出就可能集中出現。","displayText":"可是某一天牙齒突然痛、眼鏡壞了、運動受傷，支出就可能集中出現。","startTimecode":"00:08:13,728","endTimecode":"00:08:19,680"},{"id":"S121","sequence":121,"startMs":499860,"endMs":503381,"startSeconds":499.86,"endSeconds":503.381,"text":"對有穩定儲蓄的人來說，這叫臨時開銷。","displayText":"對有穩定儲蓄的人來說，這叫臨時開銷。","startTimecode":"00:08:19,860","endTimecode":"00:08:23,381"},{"id":"S122","sequence":122,"startMs":503381,"endMs":509445,"startSeconds":503.381,"endSeconds":509.445,"text":"對帳戶本來就只剩幾千元的人來說，它可能直接改變這個月其他安排。","displayText":"對帳戶本來就只剩幾千元的人來說，它可能直接改變這個月其他安排。","startTimecode":"00:08:23,381","endTimecode":"00:08:29,445"},{"id":"S123","sequence":123,"startMs":509445,"endMs":515900,"startSeconds":509.445,"endSeconds":515.9,"text":"假設一位剛工作的青年，本來計畫月底和朋友出去玩，結果突然需要看牙。","displayText":"假設一位剛工作的青年，本來計畫月底和朋友出去玩，結果突然需要看牙。","startTimecode":"00:08:29,445","endTimecode":"00:08:35,900"},{"id":"S124","sequence":124,"startMs":516080,"endMs":518704,"startSeconds":516.08,"endSeconds":518.704,"text":"真正被取消的，可能不是醫療。","displayText":"真正被取消的，可能不是醫療。","startTimecode":"00:08:36,080","endTimecode":"00:08:38,704"},{"id":"S125","sequence":125,"startMs":518704,"endMs":519641,"startSeconds":518.704,"endSeconds":519.641,"text":"而是旅行。","displayText":"而是旅行。","startTimecode":"00:08:38,704","endTimecode":"00:08:39,641"},{"id":"S126","sequence":126,"startMs":519641,"endMs":523390,"startSeconds":519.641,"endSeconds":523.39,"text":"因為醫療比較難不付，休閒比較容易被犧牲。","displayText":"因為醫療比較難不付，休閒比較容易被犧牲。","startTimecode":"00:08:39,641","endTimecode":"00:08:43,390"},{"id":"S127","sequence":127,"startMs":523390,"endMs":526014,"startSeconds":523.39,"endSeconds":526.014,"text":"這就是生活成本的另一個現實。","displayText":"這就是生活成本的另一個現實。","startTimecode":"00:08:43,390","endTimecode":"00:08:46,014"},{"id":"S128","sequence":128,"startMs":526014,"endMs":532200,"startSeconds":526.014,"endSeconds":532.2,"text":"有些成本不是最大筆，卻因為不可預測，而讓收入低的人更需要預留緩衝。","displayText":"有些成本不是最大筆，卻因為不可預測，而讓收入低的人更需要預留緩衝。","startTimecode":"00:08:46,014","endTimecode":"00:08:52,200"},{"id":"S129","sequence":129,"startMs":532380,"endMs":534732,"startSeconds":532.38,"endSeconds":534.732,"text":"所以我們把醫療放在第8名。","displayText":"所以我們把醫療放在第8名。","startTimecode":"00:08:52,380","endTimecode":"00:08:54,732"},{"id":"S130","sequence":130,"startMs":534732,"endMs":536179,"startSeconds":534.732,"endSeconds":536.179,"text":"它不一定天天來。","displayText":"它不一定天天來。","startTimecode":"00:08:54,732","endTimecode":"00:08:56,179"},{"id":"S131","sequence":131,"startMs":536179,"endMs":540160,"startSeconds":536.179,"endSeconds":540.16,"text":"可是來的時候，你通常沒有太多討價還價的空間。","displayText":"可是來的時候，你通常沒有太多討價還價的空間。","startTimecode":"00:08:56,179","endTimecode":"00:09:00,160"},{"id":"S132","sequence":132,"startMs":540160,"endMs":544140,"startSeconds":540.16,"endSeconds":544.14,"text":"而接下來這一項，很多九年級生甚至是主動付錢。","displayText":"而接下來這一項，很多九年級生甚至是主動付錢。","startTimecode":"00:09:00,160","endTimecode":"00:09:04,140"},{"id":"S133","sequence":133,"startMs":544320,"endMs":548895,"startSeconds":544.32,"endSeconds":548.895,"text":"因為他們害怕的不是今天生活不了，而是明天跟不上。","displayText":"因為他們害怕的不是今天生活不了，而是明天跟不上。","startTimecode":"00:09:04,320","endTimecode":"00:09:08,895"},{"id":"S134","sequence":134,"startMs":548895,"endMs":556520,"startSeconds":548.895,"endSeconds":556.52,"text":"06｜第7名｜畢業以後，學習反而開始收費｜教育與技能進修第7名，教育與技能進修。","displayText":"06｜第7名｜畢業以後，學習反而開始收費｜教育與技能進修第7名，教育與技能進修。","startTimecode":"00:09:08,895","endTimecode":"00:09:16,520"},{"id":"S135","sequence":135,"startMs":556700,"endMs":560637,"startSeconds":556.7,"endSeconds":560.637,"text":"如果九年級生剛從學校畢業，最容易產生一種錯覺。","displayText":"如果九年級生剛從學校畢業，最容易產生一種錯覺。","startTimecode":"00:09:16,700","endTimecode":"00:09:20,637"},{"id":"S136","sequence":136,"startMs":560637,"endMs":563376,"startSeconds":560.637,"endSeconds":563.376,"text":"學費繳完了，教育成本應該結束了。","displayText":"學費繳完了，教育成本應該結束了。","startTimecode":"00:09:20,637","endTimecode":"00:09:23,376"},{"id":"S137","sequence":137,"startMs":563376,"endMs":568340,"startSeconds":563.376,"endSeconds":568.34,"text":"但真正進入職場後，很多人才發現，學習只是換了一種收費方式。","displayText":"但真正進入職場後，很多人才發現，學習只是換了一種收費方式。","startTimecode":"00:09:23,376","endTimecode":"00:09:28,340"},{"id":"S138","sequence":138,"startMs":568520,"endMs":582120,"startSeconds":568.52,"endSeconds":582.12,"text":"英文檢定、專業證照、線上課程、軟體訂閱、AI工具、設計工具、程式課程、研究所補習，甚至只是為了讓履歷多一項技能，都可能要錢。","displayText":"英文檢定、專業證照、線上課程、軟體訂閱、AI工具、設計工具、程式課程、研究所補習，甚至只是為了讓履歷多一項技能，都可能要錢。","startTimecode":"00:09:28,520","endTimecode":"00:09:42,120"},{"id":"S139","sequence":139,"startMs":582300,"endMs":584888,"startSeconds":582.3,"endSeconds":584.888,"text":"上一集我們談AI改變職場規則。","displayText":"上一集我們談AI改變職場規則。","startTimecode":"00:09:42,300","endTimecode":"00:09:44,888"},{"id":"S140","sequence":140,"startMs":584888,"endMs":590925,"startSeconds":584.888,"endSeconds":590.925,"text":"這一集再看一次，就會發現AI不只改變工作，也可能增加一種新的生活成本。","displayText":"這一集再看一次，就會發現AI不只改變工作，也可能增加一種新的生活成本。","startTimecode":"00:09:44,888","endTimecode":"00:09:50,925"},{"id":"S141","sequence":141,"startMs":590925,"endMs":593340,"startSeconds":590.925,"endSeconds":593.34,"text":"「保持自己不要落後」的成本。","displayText":"「保持自己不要落後」的成本。","startTimecode":"00:09:50,925","endTimecode":"00:09:53,340"},{"id":"S142","sequence":142,"startMs":593520,"endMs":599222,"startSeconds":593.52,"endSeconds":599.222,"text":"假設一位24歲的上班族發現，公司開始要求使用AI工具。","displayText":"假設一位24歲的上班族發現，公司開始要求使用AI工具。","startTimecode":"00:09:53,520","endTimecode":"00:09:59,222"},{"id":"S143","sequence":143,"startMs":599222,"endMs":601967,"startSeconds":599.222,"endSeconds":601.967,"text":"免費版本能用，但功能有限。","displayText":"免費版本能用，但功能有限。","startTimecode":"00:09:59,222","endTimecode":"00:10:01,967"},{"id":"S144","sequence":144,"startMs":601967,"endMs":607880,"startSeconds":601.967,"endSeconds":607.88,"text":"他想學得更快，可能開始訂閱工具、買課程，或花週末去上課。","displayText":"他想學得更快，可能開始訂閱工具、買課程，或花週末去上課。","startTimecode":"00:10:01,967","endTimecode":"00:10:07,880"},{"id":"S145","sequence":145,"startMs":608060,"endMs":609920,"startSeconds":608.06,"endSeconds":609.92,"text":"這些支出和房租不一樣。","displayText":"這些支出和房租不一樣。","startTimecode":"00:10:08,060","endTimecode":"00:10:09,920"},{"id":"S146","sequence":146,"startMs":609920,"endMs":611610,"startSeconds":609.92,"endSeconds":611.61,"text":"沒有人拿帳單逼你繳。","displayText":"沒有人拿帳單逼你繳。","startTimecode":"00:10:09,920","endTimecode":"00:10:11,610"},{"id":"S147","sequence":147,"startMs":611610,"endMs":617865,"startSeconds":611.61,"endSeconds":617.865,"text":"可是如果你認為不學就可能失去下一個機會，它就會從「想要」慢慢變成「需要」。","displayText":"可是如果你認為不學就可能失去下一個機會，它就會從「想要」慢慢變成「需要」。","startTimecode":"00:10:11,610","endTimecode":"00:10:17,865"},{"id":"S148","sequence":148,"startMs":617865,"endMs":622260,"startSeconds":617.865,"endSeconds":622.26,"text":"教育支出的青年衝擊，也因此不能只看家庭教育支出占比。","displayText":"教育支出的青年衝擊，也因此不能只看家庭教育支出占比。","startTimecode":"00:10:17,865","endTimecode":"00:10:22,260"},{"id":"S149","sequence":149,"startMs":622440,"endMs":629259,"startSeconds":622.44,"endSeconds":629.259,"text":"因為一個已經離開學校的年輕人，進修可能散落在各種平台、軟體與證照裡。","displayText":"因為一個已經離開學校的年輕人，進修可能散落在各種平台、軟體與證照裡。","startTimecode":"00:10:22,440","endTimecode":"00:10:29,259"},{"id":"S150","sequence":150,"startMs":629259,"endMs":632869,"startSeconds":629.259,"endSeconds":632.869,"text":"第7名的真正壓力不是每個人都花很多。","displayText":"第7名的真正壓力不是每個人都花很多。","startTimecode":"00:10:29,259","endTimecode":"00:10:32,869"},{"id":"S151","sequence":151,"startMs":632869,"endMs":636680,"startSeconds":632.869,"endSeconds":636.68,"text":"而是職涯變動越快，越多人會開始問自己：","displayText":"而是職涯變動越快，越多人會開始問自己：","startTimecode":"00:10:32,869","endTimecode":"00:10:36,680"},{"id":"S152","sequence":152,"startMs":636860,"endMs":640726,"startSeconds":636.86,"endSeconds":640.726,"text":"我是不是還得花錢，才能繼續有資格工作？","displayText":"我是不是還得花錢，才能繼續有資格工作？","startTimecode":"00:10:36,860","endTimecode":"00:10:40,726"},{"id":"S153","sequence":153,"startMs":640726,"endMs":643372,"startSeconds":640.726,"endSeconds":643.372,"text":"不過進修至少還能選擇時間。","displayText":"不過進修至少還能選擇時間。","startTimecode":"00:10:40,726","endTimecode":"00:10:43,372"},{"id":"S154","sequence":154,"startMs":643372,"endMs":644796,"startSeconds":643.372,"endSeconds":644.796,"text":"下一項更有趣。","displayText":"下一項更有趣。","startTimecode":"00:10:43,372","endTimecode":"00:10:44,796"},{"id":"S155","sequence":155,"startMs":644796,"endMs":648663,"startSeconds":644.796,"endSeconds":648.663,"text":"它明明不是生存必需品，卻很難完全拿掉。","displayText":"它明明不是生存必需品，卻很難完全拿掉。","startTimecode":"00:10:44,796","endTimecode":"00:10:48,663"},{"id":"S156","sequence":156,"startMs":648663,"endMs":653140,"startSeconds":648.663,"endSeconds":653.14,"text":"因為人不是只需要活著，也需要和別人一起生活。","displayText":"因為人不是只需要活著，也需要和別人一起生活。","startTimecode":"00:10:48,663","endTimecode":"00:10:53,140"},{"id":"S157","sequence":157,"startMs":653320,"endMs":661224,"startSeconds":653.32,"endSeconds":661.224,"text":"07｜第6名｜最容易被刪掉，也最捨不得全部刪掉｜社交與休閒第6名，社交與休閒。","displayText":"07｜第6名｜最容易被刪掉，也最捨不得全部刪掉｜社交與休閒第6名，社交與休閒。","startTimecode":"00:10:53,320","endTimecode":"00:11:01,224"},{"id":"S158","sequence":158,"startMs":661224,"endMs":668520,"startSeconds":661.224,"endSeconds":668.52,"text":"如果只看生存，電影可以不看，咖啡可以不喝，旅行可以不去，聚餐也可以拒絕。","displayText":"如果只看生存，電影可以不看，咖啡可以不喝，旅行可以不去，聚餐也可以拒絕。","startTimecode":"00:11:01,224","endTimecode":"00:11:08,520"},{"id":"S159","sequence":159,"startMs":668700,"endMs":672228,"startSeconds":668.7,"endSeconds":672.228,"text":"所以當收入不夠時，休閒往往最先被砍。","displayText":"所以當收入不夠時，休閒往往最先被砍。","startTimecode":"00:11:08,700","endTimecode":"00:11:12,228"},{"id":"S160","sequence":160,"startMs":672228,"endMs":677716,"startSeconds":672.228,"endSeconds":677.716,"text":"但問題是，人不是一張只需要維持最低成本的Excel表格。","displayText":"但問題是，人不是一張只需要維持最低成本的Excel表格。","startTimecode":"00:11:12,228","endTimecode":"00:11:17,716"},{"id":"S161","sequence":161,"startMs":677716,"endMs":680460,"startSeconds":677.716,"endSeconds":680.46,"text":"剛進職場的年輕人，需要朋友。","displayText":"剛進職場的年輕人，需要朋友。","startTimecode":"00:11:17,716","endTimecode":"00:11:20,460"},{"id":"S162","sequence":162,"startMs":680640,"endMs":682511,"startSeconds":680.64,"endSeconds":682.511,"text":"需要和同事建立關係。","displayText":"需要和同事建立關係。","startTimecode":"00:11:20,640","endTimecode":"00:11:22,511"},{"id":"S163","sequence":163,"startMs":682511,"endMs":683446,"startSeconds":682.511,"endSeconds":683.446,"text":"需要約會。","displayText":"需要約會。","startTimecode":"00:11:22,511","endTimecode":"00:11:23,446"},{"id":"S164","sequence":164,"startMs":683446,"endMs":685130,"startSeconds":683.446,"endSeconds":685.13,"text":"需要偶爾離開工作。","displayText":"需要偶爾離開工作。","startTimecode":"00:11:23,446","endTimecode":"00:11:25,130"},{"id":"S165","sequence":165,"startMs":685130,"endMs":688123,"startSeconds":685.13,"endSeconds":688.123,"text":"需要一個不只是睡覺和上班的人生。","displayText":"需要一個不只是睡覺和上班的人生。","startTimecode":"00:11:25,130","endTimecode":"00:11:28,123"},{"id":"S166","sequence":166,"startMs":688123,"endMs":692800,"startSeconds":688.123,"endSeconds":692.8,"text":"假設一位23歲青年為了省錢，連續幾週拒絕朋友聚餐。","displayText":"假設一位23歲青年為了省錢，連續幾週拒絕朋友聚餐。","startTimecode":"00:11:28,123","endTimecode":"00:11:32,800"},{"id":"S167","sequence":167,"startMs":692980,"endMs":695061,"startSeconds":692.98,"endSeconds":695.061,"text":"帳戶確實多留下一點錢。","displayText":"帳戶確實多留下一點錢。","startTimecode":"00:11:32,980","endTimecode":"00:11:35,061"},{"id":"S168","sequence":168,"startMs":695061,"endMs":703572,"startSeconds":695.061,"endSeconds":703.572,"text":"可是當所有人的生活都在繼續，他也可能開始覺得，自己不是在省一頓飯，而是在慢慢退出某些關係。","displayText":"可是當所有人的生活都在繼續，他也可能開始覺得，自己不是在省一頓飯，而是在慢慢退出某些關係。","startTimecode":"00:11:35,061","endTimecode":"00:11:43,572"},{"id":"S169","sequence":169,"startMs":703572,"endMs":706220,"startSeconds":703.572,"endSeconds":706.22,"text":"這也是為什麼休閒成本很特殊。","displayText":"這也是為什麼休閒成本很特殊。","startTimecode":"00:11:43,572","endTimecode":"00:11:46,220"},{"id":"S170","sequence":170,"startMs":706400,"endMs":710654,"startSeconds":706.4,"endSeconds":710.654,"text":"它的不可避免性不高，但心理與社會層面的價值很高。","displayText":"它的不可避免性不高，但心理與社會層面的價值很高。","startTimecode":"00:11:46,400","endTimecode":"00:11:50,654"},{"id":"S171","sequence":171,"startMs":710654,"endMs":715084,"startSeconds":710.654,"endSeconds":715.084,"text":"所以收入吃緊時，最容易出現的不是「完全沒有休閒」。","displayText":"所以收入吃緊時，最容易出現的不是「完全沒有休閒」。","startTimecode":"00:11:50,654","endTimecode":"00:11:55,084"},{"id":"S172","sequence":172,"startMs":715084,"endMs":717920,"startSeconds":715.084,"endSeconds":717.92,"text":"而是每一次休閒之前，都先算一次。","displayText":"而是每一次休閒之前，都先算一次。","startTimecode":"00:11:55,084","endTimecode":"00:11:57,920"},{"id":"S173","sequence":173,"startMs":718100,"endMs":719736,"startSeconds":718.1,"endSeconds":719.736,"text":"這杯咖啡值不值得？","displayText":"這杯咖啡值不值得？","startTimecode":"00:11:58,100","endTimecode":"00:11:59,736"},{"id":"S174","sequence":174,"startMs":719736,"endMs":721372,"startSeconds":719.736,"endSeconds":721.372,"text":"這場電影要不要去？","displayText":"這場電影要不要去？","startTimecode":"00:11:59,736","endTimecode":"00:12:01,372"},{"id":"S175","sequence":175,"startMs":721372,"endMs":724098,"startSeconds":721.372,"endSeconds":724.098,"text":"這次聚餐是不是又要1000元？","displayText":"這次聚餐是不是又要1000元？","startTimecode":"00:12:01,372","endTimecode":"00:12:04,098"},{"id":"S176","sequence":176,"startMs":724098,"endMs":726280,"startSeconds":724.098,"endSeconds":726.28,"text":"這趟旅行是不是乾脆算了？","displayText":"這趟旅行是不是乾脆算了？","startTimecode":"00:12:04,098","endTimecode":"00:12:06,280"},{"id":"S177","sequence":177,"startMs":726280,"endMs":732460,"startSeconds":726.28,"endSeconds":732.46,"text":"當生活裡所有非必要支出都必須先經過計算，真正被壓縮的其實就是自由感。","displayText":"當生活裡所有非必要支出都必須先經過計算，真正被壓縮的其實就是自由感。","startTimecode":"00:12:06,280","endTimecode":"00:12:12,460"},{"id":"S178","sequence":178,"startMs":732640,"endMs":735390,"startSeconds":732.64,"endSeconds":735.39,"text":"所以第6名不是因為休閒最貴。","displayText":"所以第6名不是因為休閒最貴。","startTimecode":"00:12:12,640","endTimecode":"00:12:15,390"},{"id":"S179","sequence":179,"startMs":735390,"endMs":741085,"startSeconds":735.39,"endSeconds":741.085,"text":"而是因為它最容易成為其他必要成本上升之後，被犧牲的那一塊。","displayText":"而是因為它最容易成為其他必要成本上升之後，被犧牲的那一塊。","startTimecode":"00:12:15,390","endTimecode":"00:12:21,085"},{"id":"S180","sequence":180,"startMs":741085,"endMs":742853,"startSeconds":741.085,"endSeconds":742.853,"text":"接下來進入前5名。","displayText":"接下來進入前5名。","startTimecode":"00:12:21,085","endTimecode":"00:12:22,853"},{"id":"S181","sequence":181,"startMs":742853,"endMs":750120,"startSeconds":742.853,"endSeconds":750.12,"text":"從這裡開始，越來越多支出不是「想不想花」，而是生活本身會一直把帳單送過來。","displayText":"從這裡開始，越來越多支出不是「想不想花」，而是生活本身會一直把帳單送過來。","startTimecode":"00:12:22,853","endTimecode":"00:12:30,120"},{"id":"S182","sequence":182,"startMs":750300,"endMs":757780,"startSeconds":750.3,"endSeconds":757.78,"text":"08｜第5名｜每一樣都不貴，加起來卻一直補貨｜日用品與家務支出第5名，日用品與家務支出。","displayText":"08｜第5名｜每一樣都不貴，加起來卻一直補貨｜日用品與家務支出第5名，日用品與家務支出。","startTimecode":"00:12:30,300","endTimecode":"00:12:37,780"},{"id":"S183","sequence":183,"startMs":757780,"endMs":761860,"startSeconds":757.78,"endSeconds":761.86,"text":"衛生紙、洗髮精、洗衣精、牙膏、垃圾袋、清潔用品。","displayText":"衛生紙、洗髮精、洗衣精、牙膏、垃圾袋、清潔用品。","startTimecode":"00:12:37,780","endTimecode":"00:12:41,860"},{"id":"S184","sequence":184,"startMs":762040,"endMs":771786,"startSeconds":762.04,"endSeconds":771.786,"text":"第一次離開家自己住的人，很容易在搬進租屋處的第一週才發現：原來家裡那些「本來就有」的東西，全部都要有人買。","displayText":"第一次離開家自己住的人，很容易在搬進租屋處的第一週才發現：原來家裡那些「本來就有」的東西，全部都要有人買。","startTimecode":"00:12:42,040","endTimecode":"00:12:51,786"},{"id":"S185","sequence":185,"startMs":771786,"endMs":776200,"startSeconds":771.786,"endSeconds":776.2,"text":"學生住家裡時，很少有人計算一卷衛生紙到底多少錢。","displayText":"學生住家裡時，很少有人計算一卷衛生紙到底多少錢。","startTimecode":"00:12:51,786","endTimecode":"00:12:56,200"},{"id":"S186","sequence":186,"startMs":776380,"endMs":779960,"startSeconds":776.38,"endSeconds":779.96,"text":"因為它用完了，下一包常常已經在櫃子裡。","displayText":"因為它用完了，下一包常常已經在櫃子裡。","startTimecode":"00:12:56,380","endTimecode":"00:12:59,960"},{"id":"S187","sequence":187,"startMs":779960,"endMs":786742,"startSeconds":779.96,"endSeconds":786.742,"text":"但開始獨立生活後，每一樣原本透明的家庭成本，都會慢慢變成自己的購物清單。","displayText":"但開始獨立生活後，每一樣原本透明的家庭成本，都會慢慢變成自己的購物清單。","startTimecode":"00:12:59,960","endTimecode":"00:13:06,742"},{"id":"S188","sequence":188,"startMs":786742,"endMs":789380,"startSeconds":786.742,"endSeconds":789.38,"text":"日用品的特點是單價通常不高。","displayText":"日用品的特點是單價通常不高。","startTimecode":"00:13:06,742","endTimecode":"00:13:09,380"},{"id":"S189","sequence":189,"startMs":789560,"endMs":791898,"startSeconds":789.56,"endSeconds":791.898,"text":"也正因如此，很容易低估。","displayText":"也正因如此，很容易低估。","startTimecode":"00:13:09,560","endTimecode":"00:13:11,898"},{"id":"S190","sequence":190,"startMs":791898,"endMs":795991,"startSeconds":791.898,"endSeconds":795.991,"text":"今天100元，明天200元，下週又補一樣。","displayText":"今天100元，明天200元，下週又補一樣。","startTimecode":"00:13:11,898","endTimecode":"00:13:15,991"},{"id":"S191","sequence":191,"startMs":795991,"endMs":800278,"startSeconds":795.991,"endSeconds":800.278,"text":"你不會因為買了一瓶洗衣精而覺得生活成本爆炸。","displayText":"你不會因為買了一瓶洗衣精而覺得生活成本爆炸。","startTimecode":"00:13:15,991","endTimecode":"00:13:20,278"},{"id":"S192","sequence":192,"startMs":800278,"endMs":804760,"startSeconds":800.278,"endSeconds":804.76,"text":"可是月底回頭看，會發現生活不是只有幾張大帳單。","displayText":"可是月底回頭看，會發現生活不是只有幾張大帳單。","startTimecode":"00:13:20,278","endTimecode":"00:13:24,760"},{"id":"S193","sequence":193,"startMs":804940,"endMs":806266,"startSeconds":804.94,"endSeconds":806.266,"text":"還有很多小洞。","displayText":"還有很多小洞。","startTimecode":"00:13:24,940","endTimecode":"00:13:26,266"},{"id":"S194","sequence":194,"startMs":806266,"endMs":809106,"startSeconds":806.266,"endSeconds":809.106,"text":"而且這些東西大多不能永久取消。","displayText":"而且這些東西大多不能永久取消。","startTimecode":"00:13:26,266","endTimecode":"00:13:29,106"},{"id":"S195","sequence":195,"startMs":809106,"endMs":814219,"startSeconds":809.106,"endSeconds":814.219,"text":"你可以選便宜品牌，可以趁特價囤貨，可以減少不必要用品。","displayText":"你可以選便宜品牌，可以趁特價囤貨，可以減少不必要用品。","startTimecode":"00:13:29,106","endTimecode":"00:13:34,219"},{"id":"S196","sequence":196,"startMs":814219,"endMs":817060,"startSeconds":814.219,"endSeconds":817.06,"text":"但基本清潔與日常消耗仍然存在。","displayText":"但基本清潔與日常消耗仍然存在。","startTimecode":"00:13:34,219","endTimecode":"00:13:37,060"},{"id":"S197","sequence":197,"startMs":817240,"endMs":819014,"startSeconds":817.24,"endSeconds":819.014,"text":"這就是第5名的理由。","displayText":"這就是第5名的理由。","startTimecode":"00:13:37,240","endTimecode":"00:13:39,014"},{"id":"S198","sequence":198,"startMs":819014,"endMs":823270,"startSeconds":819.014,"endSeconds":823.27,"text":"它不是最痛的一刀，而是一連串很小、很規律的切口。","displayText":"它不是最痛的一刀，而是一連串很小、很規律的切口。","startTimecode":"00:13:39,014","endTimecode":"00:13:43,270"},{"id":"S199","sequence":199,"startMs":823270,"endMs":830720,"startSeconds":823.27,"endSeconds":830.72,"text":"而如果你開始自己住，除了買這些東西，還會第一次真正看到另一張以前可能不太注意的帳單。","displayText":"而如果你開始自己住，除了買這些東西，還會第一次真正看到另一張以前可能不太注意的帳單。","startTimecode":"00:13:43,270","endTimecode":"00:13:50,720"},{"id":"S200","sequence":200,"startMs":830900,"endMs":832230,"startSeconds":830.9,"endSeconds":832.23,"text":"水、電、瓦斯。","displayText":"水、電、瓦斯。","startTimecode":"00:13:50,900","endTimecode":"00:13:52,230"},{"id":"S201","sequence":201,"startMs":832230,"endMs":840020,"startSeconds":832.23,"endSeconds":840.02,"text":"09｜第4名｜冷氣一開，就開始計算｜水電瓦斯與居住能源第4名，水電瓦斯與居住能源。","displayText":"09｜第4名｜冷氣一開，就開始計算｜水電瓦斯與居住能源第4名，水電瓦斯與居住能源。","startTimecode":"00:13:52,230","endTimecode":"00:14:00,020"},{"id":"S202","sequence":202,"startMs":840020,"endMs":844580,"startSeconds":840.02,"endSeconds":844.58,"text":"對住在家裡的年輕人來說，水電費可能只是一句提醒。","displayText":"對住在家裡的年輕人來說，水電費可能只是一句提醒。","startTimecode":"00:14:00,020","endTimecode":"00:14:04,580"},{"id":"S203","sequence":203,"startMs":844760,"endMs":846333,"startSeconds":844.76,"endSeconds":846.333,"text":"冷氣不要開太久。","displayText":"冷氣不要開太久。","startTimecode":"00:14:04,760","endTimecode":"00:14:06,333"},{"id":"S204","sequence":204,"startMs":846333,"endMs":847316,"startSeconds":846.333,"endSeconds":847.316,"text":"燈記得關。","displayText":"燈記得關。","startTimecode":"00:14:06,333","endTimecode":"00:14:07,316"},{"id":"S205","sequence":205,"startMs":847316,"endMs":852035,"startSeconds":847.316,"endSeconds":852.035,"text":"可是當帳單第一次直接寄到自己手上，感受就不一樣。","displayText":"可是當帳單第一次直接寄到自己手上，感受就不一樣。","startTimecode":"00:14:07,316","endTimecode":"00:14:12,035"},{"id":"S206","sequence":206,"startMs":852035,"endMs":856361,"startSeconds":852.035,"endSeconds":856.361,"text":"台灣夏季炎熱，冷氣對很多人已經不是純粹享受。","displayText":"台灣夏季炎熱，冷氣對很多人已經不是純粹享受。","startTimecode":"00:14:12,035","endTimecode":"00:14:16,361"},{"id":"S207","sequence":207,"startMs":856361,"endMs":861080,"startSeconds":856.361,"endSeconds":861.08,"text":"租屋空間如果西曬、通風差，能源支出更難完全避免。","displayText":"租屋空間如果西曬、通風差，能源支出更難完全避免。","startTimecode":"00:14:16,361","endTimecode":"00:14:21,080"},{"id":"S208","sequence":208,"startMs":861260,"endMs":862804,"startSeconds":861.26,"endSeconds":862.804,"text":"洗澡需要熱水。","displayText":"洗澡需要熱水。","startTimecode":"00:14:21,260","endTimecode":"00:14:22,804"},{"id":"S209","sequence":209,"startMs":862804,"endMs":864568,"startSeconds":862.804,"endSeconds":864.568,"text":"冰箱要一直運轉。","displayText":"冰箱要一直運轉。","startTimecode":"00:14:22,804","endTimecode":"00:14:24,568"},{"id":"S210","sequence":210,"startMs":864568,"endMs":868979,"startSeconds":864.568,"endSeconds":868.979,"text":"電腦、螢幕、路由器、手機，每天都在用電。","displayText":"電腦、螢幕、路由器、手機，每天都在用電。","startTimecode":"00:14:24,568","endTimecode":"00:14:28,979"},{"id":"S211","sequence":211,"startMs":868979,"endMs":873832,"startSeconds":868.979,"endSeconds":873.832,"text":"如果工作還有居家辦公，住處同時變成工作場所。","displayText":"如果工作還有居家辦公，住處同時變成工作場所。","startTimecode":"00:14:28,979","endTimecode":"00:14:33,832"},{"id":"S212","sequence":212,"startMs":873832,"endMs":877140,"startSeconds":873.832,"endSeconds":877.14,"text":"這些成本會和生活時間一起增加。","displayText":"這些成本會和生活時間一起增加。","startTimecode":"00:14:33,832","endTimecode":"00:14:37,140"},{"id":"S213","sequence":213,"startMs":877320,"endMs":880111,"startSeconds":877.32,"endSeconds":880.111,"text":"水電瓦斯的壓力不一定比房租高。","displayText":"水電瓦斯的壓力不一定比房租高。","startTimecode":"00:14:37,320","endTimecode":"00:14:40,111"},{"id":"S214","sequence":214,"startMs":880111,"endMs":881600,"startSeconds":880.111,"endSeconds":881.6,"text":"但它有一個特性。","displayText":"但它有一個特性。","startTimecode":"00:14:40,111","endTimecode":"00:14:41,600"},{"id":"S215","sequence":215,"startMs":881600,"endMs":883833,"startSeconds":881.6,"endSeconds":883.833,"text":"你住進去之後才真正知道。","displayText":"你住進去之後才真正知道。","startTimecode":"00:14:41,600","endTimecode":"00:14:43,833"},{"id":"S216","sequence":216,"startMs":883833,"endMs":890160,"startSeconds":883.833,"endSeconds":890.16,"text":"同樣是一間套房，隔熱、設備效率、採光與通風不同，最後帳單可能就不同。","displayText":"同樣是一間套房，隔熱、設備效率、採光與通風不同，最後帳單可能就不同。","startTimecode":"00:14:43,833","endTimecode":"00:14:50,160"},{"id":"S217","sequence":217,"startMs":890340,"endMs":892684,"startSeconds":890.34,"endSeconds":892.684,"text":"所以居住成本不能只看租金。","displayText":"所以居住成本不能只看租金。","startTimecode":"00:14:50,340","endTimecode":"00:14:52,684"},{"id":"S218","sequence":218,"startMs":892684,"endMs":897192,"startSeconds":892.684,"endSeconds":897.192,"text":"租下一個空間之後，還有維持那個空間可以生活的成本。","displayText":"租下一個空間之後，還有維持那個空間可以生活的成本。","startTimecode":"00:14:52,684","endTimecode":"00:14:57,192"},{"id":"S219","sequence":219,"startMs":897192,"endMs":901700,"startSeconds":897.192,"endSeconds":901.7,"text":"假設一位青年夏天為了省電，回家後一直撐著不開冷氣。","displayText":"假設一位青年夏天為了省電，回家後一直撐著不開冷氣。","startTimecode":"00:14:57,192","endTimecode":"00:15:01,700"},{"id":"S220","sequence":220,"startMs":901880,"endMs":905867,"startSeconds":901.88,"endSeconds":905.867,"text":"最後他省下的可能是幾百元，換來的是睡不好。","displayText":"最後他省下的可能是幾百元，換來的是睡不好。","startTimecode":"00:15:01,880","endTimecode":"00:15:05,867"},{"id":"S221","sequence":221,"startMs":905867,"endMs":907576,"startSeconds":905.867,"endSeconds":907.576,"text":"第二天照樣要上班。","displayText":"第二天照樣要上班。","startTimecode":"00:15:05,867","endTimecode":"00:15:07,576"},{"id":"S222","sequence":222,"startMs":907576,"endMs":911184,"startSeconds":907.576,"endSeconds":911.184,"text":"這就是生活成本開始影響生活品質的地方。","displayText":"這就是生活成本開始影響生活品質的地方。","startTimecode":"00:15:07,576","endTimecode":"00:15:11,184"},{"id":"S223","sequence":223,"startMs":911184,"endMs":916880,"startSeconds":911.184,"endSeconds":916.88,"text":"進入前3名之前，還有一項每天把我們從住處送到工作地點的成本。","displayText":"進入前3名之前，還有一項每天把我們從住處送到工作地點的成本。","startTimecode":"00:15:11,184","endTimecode":"00:15:16,880"},{"id":"S224","sequence":224,"startMs":917060,"endMs":924708,"startSeconds":917.06,"endSeconds":924.708,"text":"10｜第3名｜工作還沒開始，先付一筆到公司的錢｜交通與通勤第3名，交通與通勤。","displayText":"10｜第3名｜工作還沒開始，先付一筆到公司的錢｜交通與通勤第3名，交通與通勤。","startTimecode":"00:15:17,060","endTimecode":"00:15:24,708"},{"id":"S225","sequence":225,"startMs":924708,"endMs":928238,"startSeconds":924.708,"endSeconds":928.238,"text":"找到一份工作，第一個問題是薪水多少。","displayText":"找到一份工作，第一個問題是薪水多少。","startTimecode":"00:15:24,708","endTimecode":"00:15:28,238"},{"id":"S226","sequence":226,"startMs":928238,"endMs":931180,"startSeconds":928.238,"endSeconds":931.18,"text":"第二個問題常常是，公司在哪裡？","displayText":"第二個問題常常是，公司在哪裡？","startTimecode":"00:15:28,238","endTimecode":"00:15:31,180"},{"id":"S227","sequence":227,"startMs":931360,"endMs":933539,"startSeconds":931.36,"endSeconds":933.539,"text":"因為距離會變成成本。","displayText":"因為距離會變成成本。","startTimecode":"00:15:31,360","endTimecode":"00:15:33,539"},{"id":"S228","sequence":228,"startMs":933539,"endMs":939640,"startSeconds":933.539,"endSeconds":939.64,"text":"捷運、公車、台鐵、機車油錢、停車費、保養，甚至偶爾叫車。","displayText":"捷運、公車、台鐵、機車油錢、停車費、保養，甚至偶爾叫車。","startTimecode":"00:15:33,539","endTimecode":"00:15:39,640"},{"id":"S229","sequence":229,"startMs":939640,"endMs":942255,"startSeconds":939.64,"endSeconds":942.255,"text":"交通費不是每個人都一樣。","displayText":"交通費不是每個人都一樣。","startTimecode":"00:15:39,640","endTimecode":"00:15:42,255"},{"id":"S230","sequence":230,"startMs":942255,"endMs":947920,"startSeconds":942.255,"endSeconds":947.92,"text":"住在都市、住在郊區，搭大眾運輸或騎機車，差異都很大。","displayText":"住在都市、住在郊區，搭大眾運輸或騎機車，差異都很大。","startTimecode":"00:15:42,255","endTimecode":"00:15:47,920"},{"id":"S231","sequence":231,"startMs":948100,"endMs":951544,"startSeconds":948.1,"endSeconds":951.544,"text":"但對剛進社會的人來說，交通有兩種成本。","displayText":"但對剛進社會的人來說，交通有兩種成本。","startTimecode":"00:15:48,100","endTimecode":"00:15:51,544"},{"id":"S232","sequence":232,"startMs":951544,"endMs":952451,"startSeconds":951.544,"endSeconds":952.451,"text":"一種是錢。","displayText":"一種是錢。","startTimecode":"00:15:51,544","endTimecode":"00:15:52,451"},{"id":"S233","sequence":233,"startMs":952451,"endMs":953720,"startSeconds":952.451,"endSeconds":953.72,"text":"另一種是時間。","displayText":"另一種是時間。","startTimecode":"00:15:52,451","endTimecode":"00:15:53,720"},{"id":"S234","sequence":234,"startMs":953720,"endMs":955170,"startSeconds":953.72,"endSeconds":955.17,"text":"假設有兩份工作。","displayText":"假設有兩份工作。","startTimecode":"00:15:53,720","endTimecode":"00:15:55,170"},{"id":"S235","sequence":235,"startMs":955170,"endMs":959340,"startSeconds":955.17,"endSeconds":959.34,"text":"一份薪水多2000元，但每天來回多花一個小時。","displayText":"一份薪水多2000元，但每天來回多花一個小時。","startTimecode":"00:15:55,170","endTimecode":"00:15:59,340"},{"id":"S236","sequence":236,"startMs":959520,"endMs":965378,"startSeconds":959.52,"endSeconds":965.378,"text":"如果還要轉車、付更多交通費，那2000元到底算不算真的多？","displayText":"如果還要轉車、付更多交通費，那2000元到底算不算真的多？","startTimecode":"00:15:59,520","endTimecode":"00:16:05,378"},{"id":"S237","sequence":237,"startMs":965378,"endMs":970024,"startSeconds":965.378,"endSeconds":970.024,"text":"這就是青年生活成本很容易被薪資數字遮住的地方。","displayText":"這就是青年生活成本很容易被薪資數字遮住的地方。","startTimecode":"00:16:05,378","endTimecode":"00:16:10,024"},{"id":"S238","sequence":238,"startMs":970024,"endMs":971640,"startSeconds":970.024,"endSeconds":971.64,"text":"薪水寫在職缺上。","displayText":"薪水寫在職缺上。","startTimecode":"00:16:10,024","endTimecode":"00:16:11,640"},{"id":"S239","sequence":239,"startMs":971820,"endMs":975599,"startSeconds":971.82,"endSeconds":975.599,"text":"通勤成本卻要開始工作以後才慢慢感受到。","displayText":"通勤成本卻要開始工作以後才慢慢感受到。","startTimecode":"00:16:11,820","endTimecode":"00:16:15,599"},{"id":"S240","sequence":240,"startMs":975599,"endMs":978384,"startSeconds":975.599,"endSeconds":978.384,"text":"而且交通通常和居住綁在一起。","displayText":"而且交通通常和居住綁在一起。","startTimecode":"00:16:15,599","endTimecode":"00:16:18,384"},{"id":"S241","sequence":241,"startMs":978384,"endMs":981367,"startSeconds":978.384,"endSeconds":981.367,"text":"住得離工作近，房租可能比較高。","displayText":"住得離工作近，房租可能比較高。","startTimecode":"00:16:18,384","endTimecode":"00:16:21,367"},{"id":"S242","sequence":242,"startMs":981367,"endMs":986340,"startSeconds":981.367,"endSeconds":986.34,"text":"住得遠一點，租金也許比較低，但交通時間與費用增加。","displayText":"住得遠一點，租金也許比較低，但交通時間與費用增加。","startTimecode":"00:16:21,367","endTimecode":"00:16:26,340"},{"id":"S243","sequence":243,"startMs":986520,"endMs":989552,"startSeconds":986.52,"endSeconds":989.552,"text":"所以第3名不只是「車票多少錢」。","displayText":"所以第3名不只是「車票多少錢」。","startTimecode":"00:16:26,520","endTimecode":"00:16:29,552"},{"id":"S244","sequence":244,"startMs":989552,"endMs":991257,"startSeconds":989.552,"endSeconds":991.257,"text":"它其實是一個交換。","displayText":"它其實是一個交換。","startTimecode":"00:16:29,552","endTimecode":"00:16:31,257"},{"id":"S245","sequence":245,"startMs":991257,"endMs":992583,"startSeconds":991.257,"endSeconds":992.583,"text":"用租金換交通。","displayText":"用租金換交通。","startTimecode":"00:16:31,257","endTimecode":"00:16:32,583"},{"id":"S246","sequence":246,"startMs":992583,"endMs":993910,"startSeconds":992.583,"endSeconds":993.91,"text":"用交通換時間。","displayText":"用交通換時間。","startTimecode":"00:16:32,583","endTimecode":"00:16:33,910"},{"id":"S247","sequence":247,"startMs":993910,"endMs":995804,"startSeconds":993.91,"endSeconds":995.804,"text":"再用時間換生活品質。","displayText":"再用時間換生活品質。","startTimecode":"00:16:33,910","endTimecode":"00:16:35,804"},{"id":"S248","sequence":248,"startMs":995804,"endMs":1000920,"startSeconds":995.804,"endSeconds":1000.92,"text":"對收入還不高的年輕人來說，很少有一個選項是完全免費的。","displayText":"對收入還不高的年輕人來說，很少有一個選項是完全免費的。","startTimecode":"00:16:35,804","endTimecode":"00:16:40,920"},{"id":"S249","sequence":249,"startMs":1001100,"endMs":1005522,"startSeconds":1001.1,"endSeconds":1005.522,"text":"而前面這些支出，有些一天一次、有些一個月一次。","displayText":"而前面這些支出，有些一天一次、有些一個月一次。","startTimecode":"00:16:41,100","endTimecode":"00:16:45,522"},{"id":"S250","sequence":250,"startMs":1005522,"endMs":1006868,"startSeconds":1005.522,"endSeconds":1006.868,"text":"下一項更直接。","displayText":"下一項更直接。","startTimecode":"00:16:45,522","endTimecode":"00:16:46,868"},{"id":"S251","sequence":251,"startMs":1006868,"endMs":1008214,"startSeconds":1006.868,"endSeconds":1008.214,"text":"一天可能三次。","displayText":"一天可能三次。","startTimecode":"00:16:46,868","endTimecode":"00:16:48,214"},{"id":"S252","sequence":252,"startMs":1008214,"endMs":1013020,"startSeconds":1008.214,"endSeconds":1013.02,"text":"11｜第2名｜一天三次，最難假裝不存在｜飲食與外食","displayText":"11｜第2名｜一天三次，最難假裝不存在｜飲食與外食","startTimecode":"00:16:48,214","endTimecode":"00:16:53,020"},{"id":"S253","sequence":253,"startMs":1013200,"endMs":1015027,"startSeconds":1013.2,"endSeconds":1015.027,"text":"第2名，飲食與外食。","displayText":"第2名，飲食與外食。","startTimecode":"00:16:53,200","endTimecode":"00:16:55,027"},{"id":"S254","sequence":254,"startMs":1015027,"endMs":1017036,"startSeconds":1015.027,"endSeconds":1017.036,"text":"你可以一年不買新手機。","displayText":"你可以一年不買新手機。","startTimecode":"00:16:55,027","endTimecode":"00:16:57,036"},{"id":"S255","sequence":255,"startMs":1017036,"endMs":1018863,"startSeconds":1017.036,"endSeconds":1018.863,"text":"可以幾個月不買衣服。","displayText":"可以幾個月不買衣服。","startTimecode":"00:16:57,036","endTimecode":"00:16:58,863"},{"id":"S256","sequence":256,"startMs":1018863,"endMs":1020141,"startSeconds":1018.863,"endSeconds":1020.141,"text":"可以取消旅行。","displayText":"可以取消旅行。","startTimecode":"00:16:58,863","endTimecode":"00:17:00,141"},{"id":"S257","sequence":257,"startMs":1020141,"endMs":1021785,"startSeconds":1020.141,"endSeconds":1021.785,"text":"但你不能取消吃飯。","displayText":"但你不能取消吃飯。","startTimecode":"00:17:00,141","endTimecode":"00:17:01,785"},{"id":"S258","sequence":258,"startMs":1021785,"endMs":1024160,"startSeconds":1021.785,"endSeconds":1024.16,"text":"這就是飲食成本最強的地方。","displayText":"這就是飲食成本最強的地方。","startTimecode":"00:17:01,785","endTimecode":"00:17:04,160"},{"id":"S259","sequence":259,"startMs":1024340,"endMs":1025411,"startSeconds":1024.34,"endSeconds":1025.411,"text":"頻率太高。","displayText":"頻率太高。","startTimecode":"00:17:04,340","endTimecode":"00:17:05,411"},{"id":"S260","sequence":260,"startMs":1025411,"endMs":1034410,"startSeconds":1025.411,"endSeconds":1034.41,"text":"尤其剛進職場的年輕人，如果住處沒有廚房，或每天工作時間長，外食很容易從選擇變成日常。","displayText":"尤其剛進職場的年輕人，如果住處沒有廚房，或每天工作時間長，外食很容易從選擇變成日常。","startTimecode":"00:17:05,411","endTimecode":"00:17:14,410"},{"id":"S261","sequence":261,"startMs":1034410,"endMs":1036338,"startSeconds":1034.41,"endSeconds":1036.338,"text":"早餐、午餐、晚餐。","displayText":"早餐、午餐、晚餐。","startTimecode":"00:17:14,410","endTimecode":"00:17:16,338"},{"id":"S262","sequence":262,"startMs":1036338,"endMs":1039980,"startSeconds":1036.338,"endSeconds":1039.98,"text":"每一餐只多10元，一天就是30元。","displayText":"每一餐只多10元，一天就是30元。","startTimecode":"00:17:16,338","endTimecode":"00:17:19,980"},{"id":"S263","sequence":263,"startMs":1040160,"endMs":1043049,"startSeconds":1040.16,"endSeconds":1043.049,"text":"一個月累積起來，感受就完全不同。","displayText":"一個月累積起來，感受就完全不同。","startTimecode":"00:17:20,160","endTimecode":"00:17:23,049"},{"id":"S264","sequence":264,"startMs":1043049,"endMs":1045938,"startSeconds":1043.049,"endSeconds":1045.938,"text":"2025年全年CPI平均上漲1.","displayText":"2025年全年CPI平均上漲1.","startTimecode":"00:17:23,049","endTimecode":"00:17:25,938"},{"id":"S265","sequence":265,"startMs":1045938,"endMs":1046661,"startSeconds":1045.938,"endSeconds":1046.661,"text":"66%。","displayText":"66%。","startTimecode":"00:17:25,938","endTimecode":"00:17:26,661"},{"id":"S266","sequence":266,"startMs":1046661,"endMs":1050453,"startSeconds":1046.661,"endSeconds":1050.453,"text":"但一個人的生活感受，不會完全等於總CPI。","displayText":"但一個人的生活感受，不會完全等於總CPI。","startTimecode":"00:17:26,661","endTimecode":"00:17:30,453"},{"id":"S267","sequence":267,"startMs":1050453,"endMs":1052800,"startSeconds":1050.453,"endSeconds":1052.8,"text":"因為每個人的消費組合不同。","displayText":"因為每個人的消費組合不同。","startTimecode":"00:17:30,453","endTimecode":"00:17:32,800"},{"id":"S268","sequence":268,"startMs":1052980,"endMs":1059360,"startSeconds":1052.98,"endSeconds":1059.36,"text":"如果你天天外食，你最在意的可能不是總指數，而是便當、早餐、飲料與餐廳價格。","displayText":"如果你天天外食，你最在意的可能不是總指數，而是便當、早餐、飲料與餐廳價格。","startTimecode":"00:17:32,980","endTimecode":"00:17:39,360"},{"id":"S269","sequence":269,"startMs":1059360,"endMs":1065740,"startSeconds":1059.36,"endSeconds":1065.74,"text":"這也是為什麼我們不能只拿一個CPI數字，就說每個人的生活成本都增加一樣多。","displayText":"這也是為什麼我們不能只拿一個CPI數字，就說每個人的生活成本都增加一樣多。","startTimecode":"00:17:39,360","endTimecode":"00:17:45,740"},{"id":"S270","sequence":270,"startMs":1065920,"endMs":1069534,"startSeconds":1065.92,"endSeconds":1069.534,"text":"假設一位剛工作的青年，中午和同事一起吃飯。","displayText":"假設一位剛工作的青年，中午和同事一起吃飯。","startTimecode":"00:17:45,920","endTimecode":"00:17:49,534"},{"id":"S271","sequence":271,"startMs":1069534,"endMs":1071599,"startSeconds":1069.534,"endSeconds":1071.599,"text":"他不是每天都去高級餐廳。","displayText":"他不是每天都去高級餐廳。","startTimecode":"00:17:49,534","endTimecode":"00:17:51,599"},{"id":"S272","sequence":272,"startMs":1071599,"endMs":1074697,"startSeconds":1071.599,"endSeconds":1074.697,"text":"可能只是一個普通便當，再加一杯飲料。","displayText":"可能只是一個普通便當，再加一杯飲料。","startTimecode":"00:17:51,599","endTimecode":"00:17:54,697"},{"id":"S273","sequence":273,"startMs":1074697,"endMs":1079000,"startSeconds":1074.697,"endSeconds":1079.0,"text":"可是當每天都要做同一個選擇時，節省會慢慢變成習慣。","displayText":"可是當每天都要做同一個選擇時，節省會慢慢變成習慣。","startTimecode":"00:17:54,697","endTimecode":"00:17:59,000"},{"id":"S274","sequence":274,"startMs":1079180,"endMs":1080735,"startSeconds":1079.18,"endSeconds":1080.735,"text":"今天不要加小菜。","displayText":"今天不要加小菜。","startTimecode":"00:17:59,180","endTimecode":"00:18:00,735"},{"id":"S275","sequence":275,"startMs":1080735,"endMs":1081901,"startSeconds":1080.735,"endSeconds":1081.901,"text":"飲料改喝水。","displayText":"飲料改喝水。","startTimecode":"00:18:00,735","endTimecode":"00:18:01,901"},{"id":"S276","sequence":276,"startMs":1081901,"endMs":1083651,"startSeconds":1081.901,"endSeconds":1083.651,"text":"週末少吃一頓外面。","displayText":"週末少吃一頓外面。","startTimecode":"00:18:01,901","endTimecode":"00:18:03,651"},{"id":"S277","sequence":277,"startMs":1083651,"endMs":1085789,"startSeconds":1083.651,"endSeconds":1085.789,"text":"這些調整看起來都很小。","displayText":"這些調整看起來都很小。","startTimecode":"00:18:03,651","endTimecode":"00:18:05,789"},{"id":"S278","sequence":278,"startMs":1085789,"endMs":1087732,"startSeconds":1085.789,"endSeconds":1087.732,"text":"可是它們透露一件事。","displayText":"可是它們透露一件事。","startTimecode":"00:18:05,789","endTimecode":"00:18:07,732"},{"id":"S279","sequence":279,"startMs":1087732,"endMs":1091620,"startSeconds":1087.732,"endSeconds":1091.62,"text":"當收入有限，最基本的日常也會開始被計算。","displayText":"當收入有限，最基本的日常也會開始被計算。","startTimecode":"00:18:07,732","endTimecode":"00:18:11,620"},{"id":"S280","sequence":280,"startMs":1091800,"endMs":1096612,"startSeconds":1091.8,"endSeconds":1096.612,"text":"飲食排第2名，不是因為它一定占每個青年支出的第二高。","displayText":"飲食排第2名，不是因為它一定占每個青年支出的第二高。","startTimecode":"00:18:11,800","endTimecode":"00:18:16,612"},{"id":"S281","sequence":281,"startMs":1096612,"endMs":1102534,"startSeconds":1096.612,"endSeconds":1102.534,"text":"而是因為它同時具有高頻率、高必要性，而且非常容易感受到價格變化。","displayText":"而是因為它同時具有高頻率、高必要性，而且非常容易感受到價格變化。","startTimecode":"00:18:16,612","endTimecode":"00:18:22,534"},{"id":"S282","sequence":282,"startMs":1102534,"endMs":1107160,"startSeconds":1102.534,"endSeconds":1107.16,"text":"但即使一天吃三餐，至少每一餐還有便宜和昂貴的選擇。","displayText":"但即使一天吃三餐，至少每一餐還有便宜和昂貴的選擇。","startTimecode":"00:18:22,534","endTimecode":"00:18:27,160"},{"id":"S283","sequence":283,"startMs":1107340,"endMs":1114129,"startSeconds":1107.34,"endSeconds":1114.129,"text":"第1名真正麻煩的地方是，一旦簽下去，接下來幾個月，你很難每天重新選一次。","displayText":"第1名真正麻煩的地方是，一旦簽下去，接下來幾個月，你很難每天重新選一次。","startTimecode":"00:18:27,340","endTimecode":"00:18:34,129"},{"id":"S284","sequence":284,"startMs":1114129,"endMs":1119220,"startSeconds":1114.129,"endSeconds":1119.22,"text":"12｜第1名｜一開始獨立，最大的帳單就來了｜居住與租屋","displayText":"12｜第1名｜一開始獨立，最大的帳單就來了｜居住與租屋","startTimecode":"00:18:34,129","endTimecode":"00:18:39,220"},{"id":"S285","sequence":285,"startMs":1119400,"endMs":1121223,"startSeconds":1119.4,"endSeconds":1121.223,"text":"第1名，居住與租屋。","displayText":"第1名，居住與租屋。","startTimecode":"00:18:39,400","endTimecode":"00:18:41,223"},{"id":"S286","sequence":286,"startMs":1121223,"endMs":1122134,"startSeconds":1121.223,"endSeconds":1122.134,"text":"先說清楚。","displayText":"先說清楚。","startTimecode":"00:18:41,223","endTimecode":"00:18:42,134"},{"id":"S287","sequence":287,"startMs":1122134,"endMs":1125051,"startSeconds":1122.134,"endSeconds":1125.051,"text":"這不是主計總處公布的官方第一名。","displayText":"這不是主計總處公布的官方第一名。","startTimecode":"00:18:42,134","endTimecode":"00:18:45,051"},{"id":"S288","sequence":288,"startMs":1125051,"endMs":1132160,"startSeconds":1125.051,"endSeconds":1132.16,"text":"這是本片依支出規模、固定性、不可避免性，以及對剛離家青年的衝擊所做的分析排序。","displayText":"這是本片依支出規模、固定性、不可避免性，以及對剛離家青年的衝擊所做的分析排序。","startTimecode":"00:18:45,051","endTimecode":"00:18:52,160"},{"id":"S289","sequence":289,"startMs":1132340,"endMs":1137385,"startSeconds":1132.34,"endSeconds":1137.385,"text":"對仍和家人同住的九年級生來說，租金甚至可能是零。","displayText":"對仍和家人同住的九年級生來說，租金甚至可能是零。","startTimecode":"00:18:52,340","endTimecode":"00:18:57,385"},{"id":"S290","sequence":290,"startMs":1137385,"endMs":1142640,"startSeconds":1137.385,"endSeconds":1142.64,"text":"所以我們不能說「每個九年級生最大的支出都是房租」。","displayText":"所以我們不能說「每個九年級生最大的支出都是房租」。","startTimecode":"00:18:57,385","endTimecode":"00:19:02,640"},{"id":"S291","sequence":291,"startMs":1142640,"endMs":1152940,"startSeconds":1142.64,"endSeconds":1152.94,"text":"但只要一個年輕人因為讀書、工作或想獨立生活而搬出去，居住成本就很容易立刻成為一張非常大的固定帳單。","displayText":"但只要一個年輕人因為讀書、工作或想獨立生活而搬出去，居住成本就很容易立刻成為一張非常大的固定帳單。","startTimecode":"00:19:02,640","endTimecode":"00:19:12,940"},{"id":"S292","sequence":292,"startMs":1153120,"endMs":1156444,"startSeconds":1153.12,"endSeconds":1156.444,"text":"而且租屋的第一個月，通常不只有租金。","displayText":"而且租屋的第一個月，通常不只有租金。","startTimecode":"00:19:13,120","endTimecode":"00:19:16,444"},{"id":"S293","sequence":293,"startMs":1156444,"endMs":1157737,"startSeconds":1156.444,"endSeconds":1157.737,"text":"還可能有押金。","displayText":"還可能有押金。","startTimecode":"00:19:16,444","endTimecode":"00:19:17,737"},{"id":"S294","sequence":294,"startMs":1157737,"endMs":1158291,"startSeconds":1157.737,"endSeconds":1158.291,"text":"搬家。","displayText":"搬家。","startTimecode":"00:19:17,737","endTimecode":"00:19:18,291"},{"id":"S295","sequence":295,"startMs":1158291,"endMs":1158845,"startSeconds":1158.291,"endSeconds":1158.845,"text":"家具。","displayText":"家具。","startTimecode":"00:19:18,291","endTimecode":"00:19:18,845"},{"id":"S296","sequence":296,"startMs":1158845,"endMs":1159768,"startSeconds":1158.845,"endSeconds":1159.768,"text":"生活用品。","displayText":"生活用品。","startTimecode":"00:19:18,845","endTimecode":"00:19:19,768"},{"id":"S297","sequence":297,"startMs":1159768,"endMs":1160322,"startSeconds":1159.768,"endSeconds":1160.322,"text":"網路。","displayText":"網路。","startTimecode":"00:19:19,768","endTimecode":"00:19:20,322"},{"id":"S298","sequence":298,"startMs":1160322,"endMs":1160876,"startSeconds":1160.322,"endSeconds":1160.876,"text":"水電。","displayText":"水電。","startTimecode":"00:19:20,322","endTimecode":"00:19:20,876"},{"id":"S299","sequence":299,"startMs":1160876,"endMs":1164200,"startSeconds":1160.876,"endSeconds":1164.2,"text":"如果工作地點改變，又可能重新搬一次。","displayText":"如果工作地點改變，又可能重新搬一次。","startTimecode":"00:19:20,876","endTimecode":"00:19:24,200"},{"id":"S300","sequence":300,"startMs":1164380,"endMs":1169611,"startSeconds":1164.38,"endSeconds":1169.611,"text":"這也是為什麼居住成本和青年人生選擇的關係特別強。","displayText":"這也是為什麼居住成本和青年人生選擇的關係特別強。","startTimecode":"00:19:24,380","endTimecode":"00:19:29,611"},{"id":"S301","sequence":301,"startMs":1169611,"endMs":1172227,"startSeconds":1169.611,"endSeconds":1172.227,"text":"一個人可能不是不想離家。","displayText":"一個人可能不是不想離家。","startTimecode":"00:19:29,611","endTimecode":"00:19:32,227"},{"id":"S302","sequence":302,"startMs":1172227,"endMs":1179420,"startSeconds":1172.227,"endSeconds":1179.42,"text":"而是算完之後發現，搬出去代表每個月先固定少掉一大塊可以運用的收入。","displayText":"而是算完之後發現，搬出去代表每個月先固定少掉一大塊可以運用的收入。","startTimecode":"00:19:32,227","endTimecode":"00:19:39,420"},{"id":"S303","sequence":303,"startMs":1179600,"endMs":1182968,"startSeconds":1179.6,"endSeconds":1182.968,"text":"假設一位24歲青年在台北找到工作。","displayText":"假設一位24歲青年在台北找到工作。","startTimecode":"00:19:39,600","endTimecode":"00:19:42,968"},{"id":"S304","sequence":304,"startMs":1182968,"endMs":1186930,"startSeconds":1182.968,"endSeconds":1186.93,"text":"如果住家裡，通勤比較久，但可以少掉租金。","displayText":"如果住家裡，通勤比較久，但可以少掉租金。","startTimecode":"00:19:42,968","endTimecode":"00:19:46,930"},{"id":"S305","sequence":305,"startMs":1186930,"endMs":1192080,"startSeconds":1186.93,"endSeconds":1192.08,"text":"如果搬到公司附近，生活時間增加，卻多了一筆固定支出。","displayText":"如果搬到公司附近，生活時間增加，卻多了一筆固定支出。","startTimecode":"00:19:46,930","endTimecode":"00:19:52,080"},{"id":"S306","sequence":306,"startMs":1192260,"endMs":1194637,"startSeconds":1192.26,"endSeconds":1194.637,"text":"他做的其實不只是租屋選擇。","displayText":"他做的其實不只是租屋選擇。","startTimecode":"00:19:52,260","endTimecode":"00:19:54,637"},{"id":"S307","sequence":307,"startMs":1194637,"endMs":1198660,"startSeconds":1194.637,"endSeconds":1198.66,"text":"他在選擇時間、隱私、自由和儲蓄之間怎麼交換。","displayText":"他在選擇時間、隱私、自由和儲蓄之間怎麼交換。","startTimecode":"00:19:54,637","endTimecode":"00:19:58,660"},{"id":"S308","sequence":308,"startMs":1198660,"endMs":1201037,"startSeconds":1198.66,"endSeconds":1201.037,"text":"更重要的是，租金不像衣服。","displayText":"更重要的是，租金不像衣服。","startTimecode":"00:19:58,660","endTimecode":"00:20:01,037"},{"id":"S309","sequence":309,"startMs":1201037,"endMs":1202683,"startSeconds":1201.037,"endSeconds":1202.683,"text":"不能這個月先不買。","displayText":"不能這個月先不買。","startTimecode":"00:20:01,037","endTimecode":"00:20:02,683"},{"id":"S310","sequence":310,"startMs":1202683,"endMs":1203780,"startSeconds":1202.683,"endSeconds":1203.78,"text":"也不像聚餐。","displayText":"也不像聚餐。","startTimecode":"00:20:02,683","endTimecode":"00:20:03,780"},{"id":"S311","sequence":311,"startMs":1203960,"endMs":1205294,"startSeconds":1203.96,"endSeconds":1205.294,"text":"不能臨時取消。","displayText":"不能臨時取消。","startTimecode":"00:20:03,960","endTimecode":"00:20:05,294"},{"id":"S312","sequence":312,"startMs":1205294,"endMs":1209296,"startSeconds":1205.294,"endSeconds":1209.296,"text":"一旦簽下租約，接下來每個月它都會準時出現。","displayText":"一旦簽下租約，接下來每個月它都會準時出現。","startTimecode":"00:20:05,294","endTimecode":"00:20:09,296"},{"id":"S313","sequence":313,"startMs":1209296,"endMs":1217680,"startSeconds":1209.296,"endSeconds":1217.68,"text":"這種「固定、金額大、難延後」的特性，正是它在青年生活成本壓力指數中排到第1名的主要原因。","displayText":"這種「固定、金額大、難延後」的特性，正是它在青年生活成本壓力指數中排到第1名的主要原因。","startTimecode":"00:20:09,296","endTimecode":"00:20:17,680"},{"id":"S314","sequence":314,"startMs":1217860,"endMs":1220042,"startSeconds":1217.86,"endSeconds":1220.042,"text":"但居住成本還有另一層。","displayText":"但居住成本還有另一層。","startTimecode":"00:20:17,860","endTimecode":"00:20:20,042"},{"id":"S315","sequence":315,"startMs":1220042,"endMs":1226785,"startSeconds":1220.042,"endSeconds":1226.785,"text":"當一個年輕人因為租金而選擇繼續住家裡，統計上看起來，他沒有租金支出。","displayText":"當一個年輕人因為租金而選擇繼續住家裡，統計上看起來，他沒有租金支出。","startTimecode":"00:20:20,042","endTimecode":"00:20:26,785"},{"id":"S316","sequence":316,"startMs":1226785,"endMs":1229562,"startSeconds":1226.785,"endSeconds":1229.562,"text":"可是這不代表居住問題不存在。","displayText":"可是這不代表居住問題不存在。","startTimecode":"00:20:26,785","endTimecode":"00:20:29,562"},{"id":"S317","sequence":317,"startMs":1229562,"endMs":1232140,"startSeconds":1229.562,"endSeconds":1232.14,"text":"成本有時候不是付出去的錢。","displayText":"成本有時候不是付出去的錢。","startTimecode":"00:20:29,562","endTimecode":"00:20:32,140"},{"id":"S318","sequence":318,"startMs":1232320,"endMs":1235624,"startSeconds":1232.32,"endSeconds":1235.624,"text":"而是因為付不起，所以沒有做出的選擇。","displayText":"而是因為付不起，所以沒有做出的選擇。","startTimecode":"00:20:32,320","endTimecode":"00:20:35,624"},{"id":"S319","sequence":319,"startMs":1235624,"endMs":1236542,"startSeconds":1235.624,"endSeconds":1236.542,"text":"沒有搬家。","displayText":"沒有搬家。","startTimecode":"00:20:35,624","endTimecode":"00:20:36,542"},{"id":"S320","sequence":320,"startMs":1236542,"endMs":1238010,"startSeconds":1236.542,"endSeconds":1238.01,"text":"沒有離工作更近。","displayText":"沒有離工作更近。","startTimecode":"00:20:36,542","endTimecode":"00:20:38,010"},{"id":"S321","sequence":321,"startMs":1238010,"endMs":1240580,"startSeconds":1238.01,"endSeconds":1240.58,"text":"沒有得到自己想要的生活空間。","displayText":"沒有得到自己想要的生活空間。","startTimecode":"00:20:38,010","endTimecode":"00:20:40,580"},{"id":"S322","sequence":322,"startMs":1240580,"endMs":1245720,"startSeconds":1240.58,"endSeconds":1245.72,"text":"這也是本集從第10名一路排到第1名，最後真正想說的事情。","displayText":"這也是本集從第10名一路排到第1名，最後真正想說的事情。","startTimecode":"00:20:40,580","endTimecode":"00:20:45,720"},{"id":"S323","sequence":323,"startMs":1245900,"endMs":1249034,"startSeconds":1245.9,"endSeconds":1249.034,"text":"生活成本真正改變的，不只是帳戶。","displayText":"生活成本真正改變的，不只是帳戶。","startTimecode":"00:20:45,900","endTimecode":"00:20:49,034"},{"id":"S324","sequence":324,"startMs":1249034,"endMs":1251581,"startSeconds":1249.034,"endSeconds":1251.581,"text":"它也會改變一個人敢不敢選。","displayText":"它也會改變一個人敢不敢選。","startTimecode":"00:20:49,034","endTimecode":"00:20:51,581"},{"id":"S325","sequence":325,"startMs":1251581,"endMs":1257065,"startSeconds":1251.581,"endSeconds":1257.065,"text":"13｜結尾｜真正昂貴的，也許是選擇變少回頭看今天的十大。","displayText":"13｜結尾｜真正昂貴的，也許是選擇變少回頭看今天的十大。","startTimecode":"00:20:51,581","endTimecode":"00:20:57,065"},{"id":"S326","sequence":326,"startMs":1257065,"endMs":1259220,"startSeconds":1257.065,"endSeconds":1259.22,"text":"第10名，衣著與鞋類。","displayText":"第10名，衣著與鞋類。","startTimecode":"00:20:57,065","endTimecode":"00:20:59,220"},{"id":"S327","sequence":327,"startMs":1259400,"endMs":1261417,"startSeconds":1259.4,"endSeconds":1261.417,"text":"第9名，手機與通訊。","displayText":"第9名，手機與通訊。","startTimecode":"00:20:59,400","endTimecode":"00:21:01,417"},{"id":"S328","sequence":328,"startMs":1261417,"endMs":1263435,"startSeconds":1261.417,"endSeconds":1263.435,"text":"第8名，醫療與保健。","displayText":"第8名，醫療與保健。","startTimecode":"00:21:01,417","endTimecode":"00:21:03,435"},{"id":"S329","sequence":329,"startMs":1263435,"endMs":1265856,"startSeconds":1263.435,"endSeconds":1265.856,"text":"第7名，教育與技能進修。","displayText":"第7名，教育與技能進修。","startTimecode":"00:21:03,435","endTimecode":"00:21:05,856"},{"id":"S330","sequence":330,"startMs":1265856,"endMs":1267873,"startSeconds":1265.856,"endSeconds":1267.873,"text":"第6名，社交與休閒。","displayText":"第6名，社交與休閒。","startTimecode":"00:21:05,856","endTimecode":"00:21:07,873"},{"id":"S331","sequence":331,"startMs":1267873,"endMs":1270496,"startSeconds":1267.873,"endSeconds":1270.496,"text":"第5名，日用品與家務支出。","displayText":"第5名，日用品與家務支出。","startTimecode":"00:21:07,873","endTimecode":"00:21:10,496"},{"id":"S332","sequence":332,"startMs":1270496,"endMs":1273320,"startSeconds":1270.496,"endSeconds":1273.32,"text":"第4名，水電瓦斯與居住能源。","displayText":"第4名，水電瓦斯與居住能源。","startTimecode":"00:21:10,496","endTimecode":"00:21:13,320"},{"id":"S333","sequence":333,"startMs":1273500,"endMs":1275445,"startSeconds":1273.5,"endSeconds":1275.445,"text":"第3名，交通與通勤。","displayText":"第3名，交通與通勤。","startTimecode":"00:21:13,500","endTimecode":"00:21:15,445"},{"id":"S334","sequence":334,"startMs":1275445,"endMs":1277389,"startSeconds":1275.445,"endSeconds":1277.389,"text":"第2名，飲食與外食。","displayText":"第2名，飲食與外食。","startTimecode":"00:21:15,445","endTimecode":"00:21:17,389"},{"id":"S335","sequence":335,"startMs":1277389,"endMs":1279334,"startSeconds":1277.389,"endSeconds":1279.334,"text":"第1名，居住與租屋。","displayText":"第1名，居住與租屋。","startTimecode":"00:21:17,389","endTimecode":"00:21:19,334"},{"id":"S336","sequence":336,"startMs":1279334,"endMs":1282445,"startSeconds":1279.334,"endSeconds":1282.445,"text":"這個排名不是政府公布的標準答案。","displayText":"這個排名不是政府公布的標準答案。","startTimecode":"00:21:19,334","endTimecode":"00:21:22,445"},{"id":"S337","sequence":337,"startMs":1282445,"endMs":1286140,"startSeconds":1282.445,"endSeconds":1286.14,"text":"甚至對不同年輕人來說，順序一定會改變。","displayText":"甚至對不同年輕人來說，順序一定會改變。","startTimecode":"00:21:22,445","endTimecode":"00:21:26,140"},{"id":"S338","sequence":338,"startMs":1286320,"endMs":1289289,"startSeconds":1286.32,"endSeconds":1289.289,"text":"住家裡的人，租金可能不是第一名。","displayText":"住家裡的人，租金可能不是第一名。","startTimecode":"00:21:26,320","endTimecode":"00:21:29,289"},{"id":"S339","sequence":339,"startMs":1289289,"endMs":1293001,"startSeconds":1289.289,"endSeconds":1293.001,"text":"每天騎車長距離通勤的人，交通可能更有感。","displayText":"每天騎車長距離通勤的人，交通可能更有感。","startTimecode":"00:21:29,289","endTimecode":"00:21:33,001"},{"id":"S340","sequence":340,"startMs":1293001,"endMs":1297084,"startSeconds":1293.001,"endSeconds":1297.084,"text":"需要長期醫療的人，醫療支出也可能直接往前排。","displayText":"需要長期醫療的人，醫療支出也可能直接往前排。","startTimecode":"00:21:33,001","endTimecode":"00:21:37,084"},{"id":"S341","sequence":341,"startMs":1297084,"endMs":1302280,"startSeconds":1297.084,"endSeconds":1302.28,"text":"所以這支影片真正重要的，不是爭論第3名到底應該排第4名。","displayText":"所以這支影片真正重要的，不是爭論第3名到底應該排第4名。","startTimecode":"00:21:37,084","endTimecode":"00:21:42,280"},{"id":"S342","sequence":342,"startMs":1302460,"endMs":1304490,"startSeconds":1302.46,"endSeconds":1304.49,"text":"而是看見一件更大的事。","displayText":"而是看見一件更大的事。","startTimecode":"00:21:42,460","endTimecode":"00:21:44,490"},{"id":"S343","sequence":343,"startMs":1304490,"endMs":1307996,"startSeconds":1304.49,"endSeconds":1307.996,"text":"生活成本從來不是一張只有「價格」的表。","displayText":"生活成本從來不是一張只有「價格」的表。","startTimecode":"00:21:44,490","endTimecode":"00:21:47,996"},{"id":"S344","sequence":344,"startMs":1307996,"endMs":1316300,"startSeconds":1307.996,"endSeconds":1316.3,"text":"它會和收入、家庭支持、居住地點、工作地點、健康狀況，以及一個人目前在人生哪個階段綁在一起。","displayText":"它會和收入、家庭支持、居住地點、工作地點、健康狀況，以及一個人目前在人生哪個階段綁在一起。","startTimecode":"00:21:47,996","endTimecode":"00:21:56,300"},{"id":"S345","sequence":345,"startMs":1316480,"endMs":1320232,"startSeconds":1316.48,"endSeconds":1320.232,"text":"2025年，台灣全年CPI平均上漲1.","displayText":"2025年，台灣全年CPI平均上漲1.","startTimecode":"00:21:56,480","endTimecode":"00:22:00,232"},{"id":"S346","sequence":346,"startMs":1320232,"endMs":1321022,"startSeconds":1320.232,"endSeconds":1321.022,"text":"66%。","displayText":"66%。","startTimecode":"00:22:00,232","endTimecode":"00:22:01,022"},{"id":"S347","sequence":347,"startMs":1321022,"endMs":1325565,"startSeconds":1321.022,"endSeconds":1325.565,"text":"同一年，薪資統計也顯示整體經常性薪資持續成長。","displayText":"同一年，薪資統計也顯示整體經常性薪資持續成長。","startTimecode":"00:22:01,022","endTimecode":"00:22:05,565"},{"id":"S348","sequence":348,"startMs":1325565,"endMs":1327738,"startSeconds":1325.565,"endSeconds":1327.738,"text":"這兩件事可以同時成立。","displayText":"這兩件事可以同時成立。","startTimecode":"00:22:05,565","endTimecode":"00:22:07,738"},{"id":"S349","sequence":349,"startMs":1327738,"endMs":1329120,"startSeconds":1327.738,"endSeconds":1329.12,"text":"薪資可以增加。","displayText":"薪資可以增加。","startTimecode":"00:22:07,738","endTimecode":"00:22:09,120"},{"id":"S350","sequence":350,"startMs":1329300,"endMs":1330630,"startSeconds":1329.3,"endSeconds":1330.63,"text":"物價也可以增加。","displayText":"物價也可以增加。","startTimecode":"00:22:09,300","endTimecode":"00:22:10,630"},{"id":"S351","sequence":351,"startMs":1330630,"endMs":1333124,"startSeconds":1330.63,"endSeconds":1333.124,"text":"而一個人仍然可能覺得生活很緊。","displayText":"而一個人仍然可能覺得生活很緊。","startTimecode":"00:22:10,630","endTimecode":"00:22:13,124"},{"id":"S352","sequence":352,"startMs":1333124,"endMs":1335451,"startSeconds":1333.124,"endSeconds":1335.451,"text":"因為平均數不是每個人的人生。","displayText":"因為平均數不是每個人的人生。","startTimecode":"00:22:13,124","endTimecode":"00:22:15,451"},{"id":"S353","sequence":353,"startMs":1335451,"endMs":1339940,"startSeconds":1335.451,"endSeconds":1339.94,"text":"尤其對剛進社會的人來說，問題往往不只是「有沒有收入」。","displayText":"尤其對剛進社會的人來說，問題往往不只是「有沒有收入」。","startTimecode":"00:22:15,451","endTimecode":"00:22:19,940"},{"id":"S354","sequence":354,"startMs":1340120,"endMs":1345255,"startSeconds":1340.12,"endSeconds":1345.255,"text":"而是收入還不高的那幾年，很多生活成本已經和所有成年人一樣真實。","displayText":"而是收入還不高的那幾年，很多生活成本已經和所有成年人一樣真實。","startTimecode":"00:22:20,120","endTimecode":"00:22:25,255"},{"id":"S355","sequence":355,"startMs":1345255,"endMs":1348402,"startSeconds":1345.255,"endSeconds":1348.402,"text":"房東不會因為你剛畢業，就把租金打五折。","displayText":"房東不會因為你剛畢業，就把租金打五折。","startTimecode":"00:22:25,255","endTimecode":"00:22:28,402"},{"id":"S356","sequence":356,"startMs":1348402,"endMs":1351880,"startSeconds":1348.402,"endSeconds":1351.88,"text":"便當店不會因為你是第一份工作，就收學生價。","displayText":"便當店不會因為你是第一份工作，就收學生價。","startTimecode":"00:22:28,402","endTimecode":"00:22:31,880"},{"id":"S357","sequence":357,"startMs":1352060,"endMs":1356573,"startSeconds":1352.06,"endSeconds":1356.573,"text":"水電、交通、手機，也不會先等你加薪三年再開始計費。","displayText":"水電、交通、手機，也不會先等你加薪三年再開始計費。","startTimecode":"00:22:32,060","endTimecode":"00:22:36,573"},{"id":"S358","sequence":358,"startMs":1356573,"endMs":1361266,"startSeconds":1356.573,"endSeconds":1361.266,"text":"這就是九年級生進社會之後，第一次真正理解的生活成本。","displayText":"這就是九年級生進社會之後，第一次真正理解的生活成本。","startTimecode":"00:22:36,573","endTimecode":"00:22:41,266"},{"id":"S359","sequence":359,"startMs":1361266,"endMs":1366140,"startSeconds":1361.266,"endSeconds":1366.14,"text":"以前父母說「生活什麼都要錢」，可能只是一句很普通的話。","displayText":"以前父母說「生活什麼都要錢」，可能只是一句很普通的話。","startTimecode":"00:22:41,266","endTimecode":"00:22:46,140"},{"id":"S360","sequence":360,"startMs":1366320,"endMs":1370022,"startSeconds":1366.32,"endSeconds":1370.022,"text":"直到自己開始付，才知道那不是一句抱怨。","displayText":"直到自己開始付，才知道那不是一句抱怨。","startTimecode":"00:22:46,320","endTimecode":"00:22:50,022"},{"id":"S361","sequence":361,"startMs":1370022,"endMs":1371971,"startSeconds":1370.022,"endSeconds":1371.971,"text":"那是一張很長的清單。","displayText":"那是一張很長的清單。","startTimecode":"00:22:50,022","endTimecode":"00:22:51,971"},{"id":"S362","sequence":362,"startMs":1371971,"endMs":1376453,"startSeconds":1371.971,"endSeconds":1376.453,"text":"可是這一集也不是要說，年輕人的未來只剩下悲觀。","displayText":"可是這一集也不是要說，年輕人的未來只剩下悲觀。","startTimecode":"00:22:51,971","endTimecode":"00:22:56,453"},{"id":"S363","sequence":363,"startMs":1376453,"endMs":1379960,"startSeconds":1376.453,"endSeconds":1379.96,"text":"真正有用的理解，是知道壓力從哪裡來。","displayText":"真正有用的理解，是知道壓力從哪裡來。","startTimecode":"00:22:56,453","endTimecode":"00:22:59,960"},{"id":"S364","sequence":364,"startMs":1380140,"endMs":1381793,"startSeconds":1380.14,"endSeconds":1381.793,"text":"哪些成本能調整。","displayText":"哪些成本能調整。","startTimecode":"00:23:00,140","endTimecode":"00:23:01,793"},{"id":"S365","sequence":365,"startMs":1381793,"endMs":1383653,"startSeconds":1381.793,"endSeconds":1383.653,"text":"哪些成本只能接受。","displayText":"哪些成本只能接受。","startTimecode":"00:23:01,793","endTimecode":"00:23:03,653"},{"id":"S366","sequence":366,"startMs":1383653,"endMs":1385513,"startSeconds":1383.653,"endSeconds":1385.513,"text":"哪些選擇值得花錢。","displayText":"哪些選擇值得花錢。","startTimecode":"00:23:03,653","endTimecode":"00:23:05,513"},{"id":"S367","sequence":367,"startMs":1385513,"endMs":1388407,"startSeconds":1385.513,"endSeconds":1388.407,"text":"哪些支出其實可以換一種方式。","displayText":"哪些支出其實可以換一種方式。","startTimecode":"00:23:05,513","endTimecode":"00:23:08,407"},{"id":"S368","sequence":368,"startMs":1388407,"endMs":1396260,"startSeconds":1388.407,"endSeconds":1396.26,"text":"當一個人看懂自己的生活成本，他至少開始有能力決定，有限的收入要優先保住什麼。","displayText":"當一個人看懂自己的生活成本，他至少開始有能力決定，有限的收入要優先保住什麼。","startTimecode":"00:23:08,407","endTimecode":"00:23:16,260"},{"id":"S369","sequence":369,"startMs":1396440,"endMs":1398779,"startSeconds":1396.44,"endSeconds":1398.779,"text":"也許是住得離公司近一點。","displayText":"也許是住得離公司近一點。","startTimecode":"00:23:16,440","endTimecode":"00:23:18,779"},{"id":"S370","sequence":370,"startMs":1398779,"endMs":1402093,"startSeconds":1398.779,"endSeconds":1402.093,"text":"也許是繼續住家裡，把錢留下來進修。","displayText":"也許是繼續住家裡，把錢留下來進修。","startTimecode":"00:23:18,779","endTimecode":"00:23:22,093"},{"id":"S371","sequence":371,"startMs":1402093,"endMs":1405992,"startSeconds":1402.093,"endSeconds":1405.992,"text":"也許是不追新手機，但保留一年一次的旅行。","displayText":"也許是不追新手機，但保留一年一次的旅行。","startTimecode":"00:23:22,093","endTimecode":"00:23:25,992"},{"id":"S372","sequence":372,"startMs":1405992,"endMs":1410280,"startSeconds":1405.992,"endSeconds":1410.28,"text":"也許是少一點外食，換一筆真正屬於自己的儲蓄。","displayText":"也許是少一點外食，換一筆真正屬於自己的儲蓄。","startTimecode":"00:23:25,992","endTimecode":"00:23:30,280"},{"id":"S373","sequence":373,"startMs":1410460,"endMs":1416217,"startSeconds":1410.46,"endSeconds":1416.217,"text":"所以最後，我想把問題留給每一個正在開始自己生活的人。","displayText":"所以最後，我想把問題留給每一個正在開始自己生活的人。","startTimecode":"00:23:30,460","endTimecode":"00:23:36,217"},{"id":"S374","sequence":374,"startMs":1416217,"endMs":1418874,"startSeconds":1416.217,"endSeconds":1418.874,"text":"真正昂貴的，到底是什麼？","displayText":"真正昂貴的，到底是什麼？","startTimecode":"00:23:36,217","endTimecode":"00:23:38,874"},{"id":"S375","sequence":375,"startMs":1418874,"endMs":1419981,"startSeconds":1418.874,"endSeconds":1419.981,"text":"是一間房？","displayText":"是一間房？","startTimecode":"00:23:38,874","endTimecode":"00:23:39,981"},{"id":"S376","sequence":376,"startMs":1419981,"endMs":1421088,"startSeconds":1419.981,"endSeconds":1421.088,"text":"是一頓飯？","displayText":"是一頓飯？","startTimecode":"00:23:39,981","endTimecode":"00:23:41,088"},{"id":"S377","sequence":377,"startMs":1421088,"endMs":1422416,"startSeconds":1421.088,"endSeconds":1422.416,"text":"是一張車票？","displayText":"是一張車票？","startTimecode":"00:23:41,088","endTimecode":"00:23:42,416"},{"id":"S378","sequence":378,"startMs":1422416,"endMs":1432380,"startSeconds":1422.416,"endSeconds":1432.38,"text":"還是當每一項必要支出，都先從收入裡拿走一部分之後，你發現自己可以選擇的人生，正在慢慢變少？","displayText":"還是當每一項必要支出，都先從收入裡拿走一部分之後，你發現自己可以選擇的人生，正在慢慢變少？","startTimecode":"00:23:42,416","endTimecode":"00:23:52,380"},{"id":"S379","sequence":379,"startMs":1432560,"endMs":1436710,"startSeconds":1432.56,"endSeconds":1436.71,"text":"生活成本真正影響的，從來不只是你還剩多少錢。","displayText":"生活成本真正影響的，從來不只是你還剩多少錢。","startTimecode":"00:23:52,560","endTimecode":"00:23:56,710"},{"id":"S380","sequence":380,"startMs":1436710,"endMs":1441427,"startSeconds":1436.71,"endSeconds":1441.427,"text":"而是你還剩多少空間，可以決定自己想過什麼樣的生活。","displayText":"而是你還剩多少空間，可以決定自己想過什麼樣的生活。","startTimecode":"00:23:56,710","endTimecode":"00:24:01,427"},{"id":"S381","sequence":381,"startMs":1441427,"endMs":1445200,"startSeconds":1441.427,"endSeconds":1445.2,"text":"這就是台灣九年級生的高難度人生，第4集。","displayText":"這就是台灣九年級生的高難度人生，第4集。","startTimecode":"00:24:01,427","endTimecode":"00:24:05,200"},{"id":"S382","sequence":382,"startMs":1445380,"endMs":1450100,"startSeconds":1445.38,"endSeconds":1450.1,"text":"台灣十大，九年級生進社會後最有感的十種生活成本。","displayText":"台灣十大，九年級生進社會後最有感的十種生活成本。","startTimecode":"00:24:05,380","endTimecode":"00:24:10,100"}],"displaySegments":[{"id":"S001-01","cueId":"S001","sequence":1,"segmentIndex":1,"text":"台灣九年級生的高難度人生｜","startMs":1500,"endMs":3968,"startSeconds":1.5,"endSeconds":3.968},{"id":"S001-02","cueId":"S001","sequence":1,"segmentIndex":2,"text":"第4集台灣十大「九年級生進社會後最有感的十種生活成本」","startMs":3968,"endMs":9095,"startSeconds":3.968,"endSeconds":9.095},{"id":"S001-03","cueId":"S001","sequence":1,"segmentIndex":3,"text":"01｜開場｜薪水才進來，怎麼又不見了？","startMs":9095,"endMs":12703,"startSeconds":9.095,"endSeconds":12.703},{"id":"S002-01","cueId":"S002","sequence":2,"segmentIndex":1,"text":"上一集，我們談的是AI正在改變九年級生怎麼工作。","startMs":12703,"endMs":17260,"startSeconds":12.703,"endSeconds":17.26},{"id":"S003-01","cueId":"S003","sequence":3,"segmentIndex":1,"text":"但這一集，我們想接著問一個更直接的問題。","startMs":17440,"endMs":21688,"startSeconds":17.44,"endSeconds":21.688},{"id":"S004-01","cueId":"S004","sequence":4,"segmentIndex":1,"text":"好，就算工作找到了，薪水也真的進帳了，接下來呢？","startMs":21688,"endMs":26785,"startSeconds":21.688,"endSeconds":26.785},{"id":"S005-01","cueId":"S005","sequence":5,"segmentIndex":1,"text":"想像一個23歲的年輕人，","startMs":26785,"endMs":29334,"startSeconds":26.785,"endSeconds":29.334},{"id":"S005-02","cueId":"S005","sequence":5,"segmentIndex":2,"text":"第一次看到公司把薪水匯進戶頭。","startMs":29334,"endMs":32520,"startSeconds":29.334,"endSeconds":32.52},{"id":"S006-01","cueId":"S006","sequence":6,"segmentIndex":1,"text":"那一刻其實很有成就感。","startMs":32700,"endMs":34748,"startSeconds":32.7,"endSeconds":34.748},{"id":"S007-01","cueId":"S007","sequence":7,"segmentIndex":1,"text":"以前吃飯、搭車、買東西，很多時候還要靠家裡。","startMs":34748,"endMs":38845,"startSeconds":34.748,"endSeconds":38.845},{"id":"S008-01","cueId":"S008","sequence":8,"segmentIndex":1,"text":"現在終於可以告訴自己，我開始靠自己的收入生活了。","startMs":38845,"endMs":43315,"startSeconds":38.845,"endSeconds":43.315},{"id":"S009-01","cueId":"S009","sequence":9,"segmentIndex":1,"text":"可是手機畫面上的那個數字，往往還沒有看習慣，","startMs":43315,"endMs":47412,"startSeconds":43.315,"endSeconds":47.412},{"id":"S009-02","cueId":"S009","sequence":9,"segmentIndex":2,"text":"下一個畫面就開始扣錢。","startMs":47412,"endMs":49460,"startSeconds":47.412,"endSeconds":49.46},{"id":"S010-01","cueId":"S010","sequence":10,"segmentIndex":1,"text":"如果在外租屋，房租先來。","startMs":49640,"endMs":52083,"startSeconds":49.64,"endSeconds":52.083},{"id":"S011-01","cueId":"S011","sequence":11,"segmentIndex":1,"text":"接著是三餐。","startMs":52083,"endMs":53305,"startSeconds":52.083,"endSeconds":53.305},{"id":"S012-01","cueId":"S012","sequence":12,"segmentIndex":1,"text":"每天上下班要交通費。","startMs":53305,"endMs":55341,"startSeconds":53.305,"endSeconds":55.341},{"id":"S013-01","cueId":"S013","sequence":13,"segmentIndex":1,"text":"手機、網路不能沒有。","startMs":55341,"endMs":57377,"startSeconds":55.341,"endSeconds":57.377},{"id":"S014-01","cueId":"S014","sequence":14,"segmentIndex":1,"text":"夏天回到租屋處，冷氣不可能永遠不開。","startMs":57377,"endMs":61041,"startSeconds":57.377,"endSeconds":61.041},{"id":"S015-01","cueId":"S015","sequence":15,"segmentIndex":1,"text":"洗衣精、衛生紙、牙膏、垃圾袋，單看都不貴，","startMs":61041,"endMs":65317,"startSeconds":61.041,"endSeconds":65.317},{"id":"S015-02","cueId":"S015","sequence":15,"segmentIndex":2,"text":"可是沒有一樣能永遠不買。","startMs":65317,"endMs":67760,"startSeconds":65.317,"endSeconds":67.76},{"id":"S016-01","cueId":"S016","sequence":16,"segmentIndex":1,"text":"偶爾同事約聚餐，朋友約看電影。","startMs":67940,"endMs":70644,"startSeconds":67.94,"endSeconds":70.644},{"id":"S017-01","cueId":"S017","sequence":17,"segmentIndex":1,"text":"工作需要新的軟體、證照或課程，可能又是一筆。","startMs":70644,"endMs":74611,"startSeconds":70.644,"endSeconds":74.611},{"id":"S018-01","cueId":"S018","sequence":18,"segmentIndex":1,"text":"一個月還沒有走完，原本看起來完整的一份薪水，","startMs":74611,"endMs":78577,"startSeconds":74.611,"endSeconds":78.577},{"id":"S018-02","cueId":"S018","sequence":18,"segmentIndex":2,"text":"已經被切成很多小塊。","startMs":78577,"endMs":80380,"startSeconds":78.577,"endSeconds":80.38},{"id":"S019-01","cueId":"S019","sequence":19,"segmentIndex":1,"text":"所以，剛進社會之後，真正讓人有感的，","startMs":80560,"endMs":83996,"startSeconds":80.56,"endSeconds":83.996},{"id":"S019-02","cueId":"S019","sequence":19,"segmentIndex":2,"text":"也許不只是「薪水多少」。","startMs":83996,"endMs":86287,"startSeconds":83.996,"endSeconds":86.287},{"id":"S020-01","cueId":"S020","sequence":20,"segmentIndex":1,"text":"而是另一個問題。","startMs":86287,"endMs":87815,"startSeconds":86.287,"endSeconds":87.815},{"id":"S021-01","cueId":"S021","sequence":21,"segmentIndex":1,"text":"這些錢進來以後，到底還能留下多少？","startMs":87815,"endMs":91060,"startSeconds":87.815,"endSeconds":91.06},{"id":"S022-01","cueId":"S022","sequence":22,"segmentIndex":1,"text":"2026年，2001到2010年出生的九年級生，","startMs":91060,"endMs":95642,"startSeconds":91.06,"endSeconds":95.642},{"id":"S022-02","cueId":"S022","sequence":22,"segmentIndex":2,"text":"大約16到25歲。","startMs":95642,"endMs":97360,"startSeconds":95.642,"endSeconds":97.36},{"id":"S023-01","cueId":"S023","sequence":23,"segmentIndex":1,"text":"這十年出生的人，不是每一個都已經工作。","startMs":97540,"endMs":101434,"startSeconds":97.54,"endSeconds":101.434},{"id":"S024-01","cueId":"S024","sequence":24,"segmentIndex":1,"text":"有些還在高中，有些正在大學，","startMs":101434,"endMs":104303,"startSeconds":101.434,"endSeconds":104.303},{"id":"S024-02","cueId":"S024","sequence":24,"segmentIndex":2,"text":"有些才剛開始第一份全職工作。","startMs":104303,"endMs":107172,"startSeconds":104.303,"endSeconds":107.172},{"id":"S025-01","cueId":"S025","sequence":25,"segmentIndex":1,"text":"因此這一集不會假裝所有九年級生都有相同的收入與支出。","startMs":107172,"endMs":112500,"startSeconds":107.172,"endSeconds":112.5},{"id":"S026-01","cueId":"S026","sequence":26,"segmentIndex":1,"text":"我們主要把鏡頭放在20到25歲，正在大學後期、","startMs":112680,"endMs":116631,"startSeconds":112.68,"endSeconds":116.631},{"id":"S026-02","cueId":"S026","sequence":26,"segmentIndex":2,"text":"剛畢業、開始工作，或第一次嘗試經濟獨立的這群人。","startMs":116631,"endMs":120753,"startSeconds":116.631,"endSeconds":120.753},{"id":"S027-01","cueId":"S027","sequence":27,"segmentIndex":1,"text":"我們也不準備告訴你，哪一樣東西「最會漲」。","startMs":120753,"endMs":124360,"startSeconds":120.753,"endSeconds":124.36},{"id":"S028-01","cueId":"S028","sequence":28,"segmentIndex":1,"text":"我們真正想知道的是，一個收入還在起步的人，","startMs":124540,"endMs":128110,"startSeconds":124.54,"endSeconds":128.11},{"id":"S028-02","cueId":"S028","sequence":28,"segmentIndex":2,"text":"哪些支出最難避開、最常發生，","startMs":128110,"endMs":130490,"startSeconds":128.11,"endSeconds":130.49},{"id":"S028-03","cueId":"S028","sequence":28,"segmentIndex":3,"text":"也最容易壓縮他可以自由運用的錢。","startMs":130490,"endMs":133210,"startSeconds":130.49,"endSeconds":133.21},{"id":"S029-01","cueId":"S029","sequence":29,"segmentIndex":1,"text":"這就是今天的題目。","startMs":133210,"endMs":134740,"startSeconds":133.21,"endSeconds":134.74},{"id":"S030-01","cueId":"S030","sequence":30,"segmentIndex":1,"text":"台灣十大，九年級生進社會後最有感的十種生活成本。","startMs":134920,"endMs":139867,"startSeconds":134.92,"endSeconds":139.867},{"id":"S031-01","cueId":"S031","sequence":31,"segmentIndex":1,"text":"02｜十大怎麼排｜我們不是找最貴，","startMs":139867,"endMs":143371,"startSeconds":139.867,"endSeconds":143.371},{"id":"S031-02","cueId":"S031","sequence":31,"segmentIndex":2,"text":"而是找最有感先說清楚，接下來的十大，","startMs":143371,"endMs":147081,"startSeconds":143.371,"endSeconds":147.081},{"id":"S031-03","cueId":"S031","sequence":31,"segmentIndex":3,"text":"不是政府公布的官方排行榜。","startMs":147081,"endMs":149760,"startSeconds":147.081,"endSeconds":149.76},{"id":"S032-01","cueId":"S032","sequence":32,"segmentIndex":1,"text":"我們建立一個節目用的分析框架，","startMs":149940,"endMs":152589,"startSeconds":149.94,"endSeconds":152.589},{"id":"S032-02","cueId":"S032","sequence":32,"segmentIndex":2,"text":"叫做「青年生活成本壓力指數」。","startMs":152589,"endMs":155238,"startSeconds":152.589,"endSeconds":155.238},{"id":"S033-01","cueId":"S033","sequence":33,"segmentIndex":1,"text":"它不是正式統計指數，","startMs":155238,"endMs":157004,"startSeconds":155.238,"endSeconds":157.004},{"id":"S033-02","cueId":"S033","sequence":33,"segmentIndex":2,"text":"而是把官方資料翻譯成年輕人比較容易理解的生活問題。","startMs":157004,"endMs":161420,"startSeconds":157.004,"endSeconds":161.42},{"id":"S034-01","cueId":"S034","sequence":34,"segmentIndex":1,"text":"我們看五件事。","startMs":161600,"endMs":162851,"startSeconds":161.6,"endSeconds":162.851},{"id":"S035-01","cueId":"S035","sequence":35,"segmentIndex":1,"text":"第一，支出占比。","startMs":162851,"endMs":164281,"startSeconds":162.851,"endSeconds":164.281},{"id":"S036-01","cueId":"S036","sequence":36,"segmentIndex":1,"text":"這筆錢在家庭或生活支出裡，占的位置大不大。","startMs":164281,"endMs":168034,"startSeconds":164.281,"endSeconds":168.034},{"id":"S037-01","cueId":"S037","sequence":37,"segmentIndex":1,"text":"第二，物價變動。","startMs":168034,"endMs":169463,"startSeconds":168.034,"endSeconds":169.463},{"id":"S038-01","cueId":"S038","sequence":38,"segmentIndex":1,"text":"同樣的東西，近年價格是不是持續改變。","startMs":169463,"endMs":172680,"startSeconds":169.463,"endSeconds":172.68},{"id":"S039-01","cueId":"S039","sequence":39,"segmentIndex":1,"text":"第三，支出頻率。","startMs":172860,"endMs":174393,"startSeconds":172.86,"endSeconds":174.393},{"id":"S040-01","cueId":"S040","sequence":40,"segmentIndex":1,"text":"一年買一次，跟每天都要付，感受完全不同。","startMs":174393,"endMs":178226,"startSeconds":174.393,"endSeconds":178.226},{"id":"S041-01","cueId":"S041","sequence":41,"segmentIndex":1,"text":"第四，不可避免性。","startMs":178226,"endMs":179951,"startSeconds":178.226,"endSeconds":179.951},{"id":"S042-01","cueId":"S042","sequence":42,"segmentIndex":1,"text":"有些消費可以延後，有些卻幾乎每天都會碰到。","startMs":179951,"endMs":183975,"startSeconds":179.951,"endSeconds":183.975},{"id":"S043-01","cueId":"S043","sequence":43,"segmentIndex":1,"text":"第五，青年衝擊度。","startMs":183975,"endMs":185700,"startSeconds":183.975,"endSeconds":185.7},{"id":"S044-01","cueId":"S044","sequence":44,"segmentIndex":1,"text":"同樣一筆3000元，","startMs":185880,"endMs":187663,"startSeconds":185.88,"endSeconds":187.663},{"id":"S044-02","cueId":"S044","sequence":44,"segmentIndex":2,"text":"對高收入者和剛領第一份薪水的人，壓力不一樣。","startMs":187663,"endMs":191587,"startSeconds":187.663,"endSeconds":191.587},{"id":"S045-01","cueId":"S045","sequence":45,"segmentIndex":1,"text":"資料以行政院主計總處為核心。","startMs":191587,"endMs":194083,"startSeconds":191.587,"endSeconds":194.083},{"id":"S046-01","cueId":"S046","sequence":46,"segmentIndex":1,"text":"家庭收支調查告訴我們，","startMs":194083,"endMs":196045,"startSeconds":194.083,"endSeconds":196.045},{"id":"S046-02","cueId":"S046","sequence":46,"segmentIndex":2,"text":"台灣家庭的錢大致花到哪些地方。","startMs":196045,"endMs":198720,"startSeconds":196.045,"endSeconds":198.72},{"id":"S047-01","cueId":"S047","sequence":47,"segmentIndex":1,"text":"消費者物價指數，也就是CPI，","startMs":198900,"endMs":201565,"startSeconds":198.9,"endSeconds":201.565},{"id":"S047-02","cueId":"S047","sequence":47,"segmentIndex":2,"text":"讓我們觀察價格怎麼變。","startMs":201565,"endMs":203519,"startSeconds":201.565,"endSeconds":203.519},{"id":"S048-01","cueId":"S048","sequence":48,"segmentIndex":1,"text":"薪資統計則幫助我們理解，","startMs":203519,"endMs":205651,"startSeconds":203.519,"endSeconds":205.651},{"id":"S048-02","cueId":"S048","sequence":48,"segmentIndex":2,"text":"這些生活成本是在什麼收入背景下發生。","startMs":205651,"endMs":208848,"startSeconds":205.651,"endSeconds":208.848},{"id":"S049-01","cueId":"S049","sequence":49,"segmentIndex":1,"text":"這裡有一個很重要的限制。","startMs":208848,"endMs":210980,"startSeconds":208.848,"endSeconds":210.98},{"id":"S050-01","cueId":"S050","sequence":50,"segmentIndex":1,"text":"主計總處的家庭收支調查，","startMs":211160,"endMs":213230,"startSeconds":211.16,"endSeconds":213.23},{"id":"S050-02","cueId":"S050","sequence":50,"segmentIndex":2,"text":"很多資料的統計單位是「家庭」，不是「九年級生個人」","startMs":213230,"endMs":217542,"startSeconds":213.23,"endSeconds":217.542},{"id":"S050-03","cueId":"S050","sequence":50,"segmentIndex":3,"text":"。","startMs":217542,"endMs":217715,"startSeconds":217.542,"endSeconds":217.715},{"id":"S051-01","cueId":"S051","sequence":51,"segmentIndex":1,"text":"所以如果官方資料寫的是平均每戶，","startMs":217715,"endMs":220475,"startSeconds":217.715,"endSeconds":220.475},{"id":"S051-02","cueId":"S051","sequence":51,"segmentIndex":2,"text":"我們就會說平均每戶；","startMs":220475,"endMs":222200,"startSeconds":220.475,"endSeconds":222.2},{"id":"S052-01","cueId":"S052","sequence":52,"segmentIndex":1,"text":"如果是全體受僱員工，我們就說全體受僱員工。","startMs":222380,"endMs":226823,"startSeconds":222.38,"endSeconds":226.823},{"id":"S053-01","cueId":"S053","sequence":53,"segmentIndex":1,"text":"我們不會把家庭平均，偷換成「九年級生平均」。","startMs":226823,"endMs":231477,"startSeconds":226.823,"endSeconds":231.477},{"id":"S054-01","cueId":"S054","sequence":54,"segmentIndex":1,"text":"2025年，主計總處公布的家庭收支資料顯示，","startMs":231477,"endMs":236131,"startSeconds":231.477,"endSeconds":236.131},{"id":"S054-02","cueId":"S054","sequence":54,"segmentIndex":2,"text":"每戶可支配所得平均數是121萬元，中位數是101.","startMs":236131,"endMs":241420,"startSeconds":236.131,"endSeconds":241.42},{"id":"S055-01","cueId":"S055","sequence":55,"segmentIndex":1,"text":"8萬元；","startMs":241600,"endMs":242472,"startSeconds":241.6,"endSeconds":242.472},{"id":"S056-01","cueId":"S056","sequence":56,"segmentIndex":1,"text":"每人可支配所得平均數45萬元，中位數36.","startMs":242472,"endMs":247048,"startSeconds":242.472,"endSeconds":247.048},{"id":"S057-01","cueId":"S057","sequence":57,"segmentIndex":1,"text":"7萬元。","startMs":247048,"endMs":247920,"startSeconds":247.048,"endSeconds":247.92},{"id":"S058-01","cueId":"S058","sequence":58,"segmentIndex":1,"text":"這些數字是家庭所得背景，不是20歲青年的薪水。","startMs":247920,"endMs":252932,"startSeconds":247.92,"endSeconds":252.932},{"id":"S059-01","cueId":"S059","sequence":59,"segmentIndex":1,"text":"另一方面，","startMs":252932,"endMs":254022,"startSeconds":252.932,"endSeconds":254.022},{"id":"S059-02","cueId":"S059","sequence":59,"segmentIndex":2,"text":"2025年全體受僱員工每月經常性薪資平均數為47884元，","startMs":254022,"endMs":260341,"startSeconds":254.022,"endSeconds":260.341},{"id":"S059-03","cueId":"S059","sequence":59,"segmentIndex":3,"text":"中位數38406元；","startMs":260341,"endMs":262520,"startSeconds":260.341,"endSeconds":262.52},{"id":"S060-01","cueId":"S060","sequence":60,"segmentIndex":1,"text":"本國籍全時受僱員工的數字又不同。","startMs":262700,"endMs":265632,"startSeconds":262.7,"endSeconds":265.632},{"id":"S061-01","cueId":"S061","sequence":61,"segmentIndex":1,"text":"所以，平均薪資不是每個年輕人的起薪，","startMs":265632,"endMs":268930,"startSeconds":265.632,"endSeconds":268.93},{"id":"S061-02","cueId":"S061","sequence":61,"segmentIndex":2,"text":"中位數也不是每個人的實領。","startMs":268930,"endMs":271312,"startSeconds":268.93,"endSeconds":271.312},{"id":"S062-01","cueId":"S062","sequence":62,"segmentIndex":1,"text":"這正是本集最重要的原則。","startMs":271312,"endMs":273511,"startSeconds":271.312,"endSeconds":273.511},{"id":"S063-01","cueId":"S063","sequence":63,"segmentIndex":1,"text":"不把不同口徑的數字硬湊在一起。","startMs":273511,"endMs":276260,"startSeconds":273.511,"endSeconds":276.26},{"id":"S064-01","cueId":"S064","sequence":64,"segmentIndex":1,"text":"我們只用它們回答一件事。","startMs":276440,"endMs":278613,"startSeconds":276.44,"endSeconds":278.613},{"id":"S065-01","cueId":"S065","sequence":65,"segmentIndex":1,"text":"當收入還在起步，哪些生活成本最容易讓人覺得，","startMs":278613,"endMs":282596,"startSeconds":278.613,"endSeconds":282.596},{"id":"S065-02","cueId":"S065","sequence":65,"segmentIndex":2,"text":"錢真的不經花？","startMs":282596,"endMs":283863,"startSeconds":282.596,"endSeconds":283.863},{"id":"S066-01","cueId":"S066","sequence":66,"segmentIndex":1,"text":"從第10名開始。","startMs":283863,"endMs":285312,"startSeconds":283.863,"endSeconds":285.312},{"id":"S067-01","cueId":"S067","sequence":67,"segmentIndex":1,"text":"03｜第10名｜不是天天買，卻不能永遠不買｜","startMs":285312,"endMs":289295,"startSeconds":285.312,"endSeconds":289.295},{"id":"S067-02","cueId":"S067","sequence":67,"segmentIndex":2,"text":"衣著與鞋類","startMs":289295,"endMs":290200,"startSeconds":289.295,"endSeconds":290.2},{"id":"S068-01","cueId":"S068","sequence":68,"segmentIndex":1,"text":"第10名，衣著與鞋類。","startMs":290380,"endMs":292350,"startSeconds":290.38,"endSeconds":292.35},{"id":"S069-01","cueId":"S069","sequence":69,"segmentIndex":1,"text":"很多人第一個反應可能是，衣服不是可以少買嗎？","startMs":292350,"endMs":296289,"startSeconds":292.35,"endSeconds":296.289},{"id":"S070-01","cueId":"S070","sequence":70,"segmentIndex":1,"text":"沒錯。","startMs":296289,"endMs":296826,"startSeconds":296.289,"endSeconds":296.826},{"id":"S071-01","cueId":"S071","sequence":71,"segmentIndex":1,"text":"這也是它排在第10名，而不是前幾名的原因。","startMs":296826,"endMs":300586,"startSeconds":296.826,"endSeconds":300.586},{"id":"S072-01","cueId":"S072","sequence":72,"segmentIndex":1,"text":"衣著最大的特色，是它不像房租、","startMs":300586,"endMs":303272,"startSeconds":300.586,"endSeconds":303.272},{"id":"S072-02","cueId":"S072","sequence":72,"segmentIndex":2,"text":"三餐那樣每天逼著你付錢。","startMs":303272,"endMs":305420,"startSeconds":303.272,"endSeconds":305.42},{"id":"S073-01","cueId":"S073","sequence":73,"segmentIndex":1,"text":"一件衣服可以穿很久，一雙鞋也可以撐一段時間。","startMs":305600,"endMs":309204,"startSeconds":305.6,"endSeconds":309.204},{"id":"S074-01","cueId":"S074","sequence":74,"segmentIndex":1,"text":"如果收入吃緊，最簡單的方法就是延後購買。","startMs":309204,"endMs":312480,"startSeconds":309.204,"endSeconds":312.48},{"id":"S075-01","cueId":"S075","sequence":75,"segmentIndex":1,"text":"但進入社會之後，衣服又不只是「想不想買」。","startMs":312480,"endMs":315920,"startSeconds":312.48,"endSeconds":315.92},{"id":"S076-01","cueId":"S076","sequence":76,"segmentIndex":1,"text":"第一次面試，需要一套看起來合適的服裝。","startMs":316100,"endMs":319227,"startSeconds":316.1,"endSeconds":319.227},{"id":"S077-01","cueId":"S077","sequence":77,"segmentIndex":1,"text":"開始上班之後，學生時代的T恤、短褲，","startMs":319227,"endMs":322190,"startSeconds":319.227,"endSeconds":322.19},{"id":"S077-02","cueId":"S077","sequence":77,"segmentIndex":2,"text":"不一定適合每一種工作環境。","startMs":322190,"endMs":324330,"startSeconds":322.19,"endSeconds":324.33},{"id":"S078-01","cueId":"S078","sequence":78,"segmentIndex":1,"text":"鞋子磨壞了，還是得換。","startMs":324330,"endMs":326140,"startSeconds":324.33,"endSeconds":326.14},{"id":"S079-01","cueId":"S079","sequence":79,"segmentIndex":1,"text":"冬天需要外套，正式場合需要比較得體的穿著。","startMs":326320,"endMs":330048,"startSeconds":326.32,"endSeconds":330.048},{"id":"S080-01","cueId":"S080","sequence":80,"segmentIndex":1,"text":"假設一位剛進公司的23歲青年，","startMs":330048,"endMs":332711,"startSeconds":330.048,"endSeconds":332.711},{"id":"S080-02","cueId":"S080","sequence":80,"segmentIndex":2,"text":"第一個月沒有大買特買，只是添一件襯衫、","startMs":332711,"endMs":336084,"startSeconds":332.711,"endSeconds":336.084},{"id":"S080-03","cueId":"S080","sequence":80,"segmentIndex":3,"text":"一條工作用長褲，再換掉穿了很久的鞋。","startMs":336084,"endMs":339280,"startSeconds":336.084,"endSeconds":339.28},{"id":"S081-01","cueId":"S081","sequence":81,"segmentIndex":1,"text":"單月支出可能突然比平常高很多。","startMs":339460,"endMs":342230,"startSeconds":339.46,"endSeconds":342.23},{"id":"S082-01","cueId":"S082","sequence":82,"segmentIndex":1,"text":"可是下個月，他完全可以不買。","startMs":342230,"endMs":344815,"startSeconds":342.23,"endSeconds":344.815},{"id":"S083-01","cueId":"S083","sequence":83,"segmentIndex":1,"text":"所以衣著成本的壓力，通常是「偶發型」","startMs":344815,"endMs":348139,"startSeconds":344.815,"endSeconds":348.139},{"id":"S083-02","cueId":"S083","sequence":83,"segmentIndex":2,"text":"，不是「持續型」。","startMs":348139,"endMs":349801,"startSeconds":348.139,"endSeconds":349.801},{"id":"S084-01","cueId":"S084","sequence":84,"segmentIndex":1,"text":"從生活成本壓力來看，它有一個好處。","startMs":349801,"endMs":352940,"startSeconds":349.801,"endSeconds":352.94},{"id":"S085-01","cueId":"S085","sequence":85,"segmentIndex":1,"text":"可以延後。","startMs":353120,"endMs":354018,"startSeconds":353.12,"endSeconds":354.018},{"id":"S086-01","cueId":"S086","sequence":86,"segmentIndex":1,"text":"可以比較。","startMs":354018,"endMs":354917,"startSeconds":354.018,"endSeconds":354.917},{"id":"S087-01","cueId":"S087","sequence":87,"segmentIndex":1,"text":"可以等折扣。","startMs":354917,"endMs":355995,"startSeconds":354.917,"endSeconds":355.995},{"id":"S088-01","cueId":"S088","sequence":88,"segmentIndex":1,"text":"也可以用原來的衣服撐久一點。","startMs":355995,"endMs":358511,"startSeconds":355.995,"endSeconds":358.511},{"id":"S089-01","cueId":"S089","sequence":89,"segmentIndex":1,"text":"對收入起步的年輕人來說，這種可以控制時間點的支出，","startMs":358511,"endMs":363004,"startSeconds":358.511,"endSeconds":363.004},{"id":"S089-02","cueId":"S089","sequence":89,"segmentIndex":2,"text":"雖然有感，卻還留有選擇。","startMs":363004,"endMs":365160,"startSeconds":363.004,"endSeconds":365.16},{"id":"S090-01","cueId":"S090","sequence":90,"segmentIndex":1,"text":"而下一項，選擇就開始變少了。","startMs":365340,"endMs":368226,"startSeconds":365.34,"endSeconds":368.226},{"id":"S091-01","cueId":"S091","sequence":91,"segmentIndex":1,"text":"04｜第9名｜看起來不大，卻每個月準時出現｜","startMs":368226,"endMs":372760,"startSeconds":368.226,"endSeconds":372.76},{"id":"S091-02","cueId":"S091","sequence":91,"segmentIndex":2,"text":"手機與通訊第9名，手機與通訊。","startMs":372760,"endMs":375852,"startSeconds":372.76,"endSeconds":375.852},{"id":"S092-01","cueId":"S092","sequence":92,"segmentIndex":1,"text":"手機月租、網路費，看起來不像房租那麼驚人。","startMs":375852,"endMs":380180,"startSeconds":375.852,"endSeconds":380.18},{"id":"S093-01","cueId":"S093","sequence":93,"segmentIndex":1,"text":"但它有一個特色。","startMs":380360,"endMs":381920,"startSeconds":380.36,"endSeconds":381.92},{"id":"S094-01","cueId":"S094","sequence":94,"segmentIndex":1,"text":"每個月都來。","startMs":381920,"endMs":383091,"startSeconds":381.92,"endSeconds":383.091},{"id":"S095-01","cueId":"S095","sequence":95,"segmentIndex":1,"text":"而且現在的手機早就不只是娛樂工具。","startMs":383091,"endMs":386407,"startSeconds":383.091,"endSeconds":386.407},{"id":"S096-01","cueId":"S096","sequence":96,"segmentIndex":1,"text":"公司群組、電子郵件、視訊會議、銀行驗證、地圖導航、","startMs":386407,"endMs":391283,"startSeconds":386.407,"endSeconds":391.283},{"id":"S096-02","cueId":"S096","sequence":96,"segmentIndex":2,"text":"求職通知、雲端文件，甚至政府服務，都可能在手機裡。","startMs":391283,"endMs":396160,"startSeconds":391.283,"endSeconds":396.16},{"id":"S097-01","cueId":"S097","sequence":97,"segmentIndex":1,"text":"對剛進社會的九年級生來說，","startMs":396340,"endMs":398521,"startSeconds":396.34,"endSeconds":398.521},{"id":"S097-02","cueId":"S097","sequence":97,"segmentIndex":2,"text":"通訊已經很接近工作與生活的基礎設施。","startMs":398521,"endMs":401541,"startSeconds":398.521,"endSeconds":401.541},{"id":"S098-01","cueId":"S098","sequence":98,"segmentIndex":1,"text":"你當然可以選比較便宜的方案。","startMs":401541,"endMs":403889,"startSeconds":401.541,"endSeconds":403.889},{"id":"S099-01","cueId":"S099","sequence":99,"segmentIndex":1,"text":"可以不追最新手機。","startMs":403889,"endMs":405399,"startSeconds":403.889,"endSeconds":405.399},{"id":"S100-01","cueId":"S100","sequence":100,"segmentIndex":1,"text":"可以把一支手機用四、五年。","startMs":405399,"endMs":407580,"startSeconds":405.399,"endSeconds":407.58},{"id":"S101-01","cueId":"S101","sequence":101,"segmentIndex":1,"text":"但你很難說，我這個月想省錢，所以完全不用網路。","startMs":407760,"endMs":412301,"startSeconds":407.76,"endSeconds":412.301},{"id":"S102-01","cueId":"S102","sequence":102,"segmentIndex":1,"text":"這就是它和衣服最大的差別。","startMs":412301,"endMs":414867,"startSeconds":412.301,"endSeconds":414.867},{"id":"S103-01","cueId":"S103","sequence":103,"segmentIndex":1,"text":"衣服可以延後買，通訊通常只能降低規格，","startMs":414867,"endMs":418618,"startSeconds":414.867,"endSeconds":418.618},{"id":"S103-02","cueId":"S103","sequence":103,"segmentIndex":2,"text":"很難完全取消。","startMs":418618,"endMs":420000,"startSeconds":418.618,"endSeconds":420.0},{"id":"S104-01","cueId":"S104","sequence":104,"segmentIndex":1,"text":"假設一個年輕人每月固定有電信費，","startMs":420180,"endMs":422998,"startSeconds":420.18,"endSeconds":422.998},{"id":"S104-02","cueId":"S104","sequence":104,"segmentIndex":2,"text":"再加上家中或租屋處網路，單筆不一定讓人心痛。","startMs":422998,"endMs":426873,"startSeconds":422.998,"endSeconds":426.873},{"id":"S105-01","cueId":"S105","sequence":105,"segmentIndex":1,"text":"可是它的特色不是「一次很貴」。","startMs":426873,"endMs":429515,"startSeconds":426.873,"endSeconds":429.515},{"id":"S106-01","cueId":"S106","sequence":106,"segmentIndex":1,"text":"而是「一直存在」。","startMs":429515,"endMs":431100,"startSeconds":429.515,"endSeconds":431.1},{"id":"S107-01","cueId":"S107","sequence":107,"segmentIndex":1,"text":"生活成本最容易被低估的，往往就是這種固定扣款。","startMs":431280,"endMs":435827,"startSeconds":431.28,"endSeconds":435.827},{"id":"S108-01","cueId":"S108","sequence":108,"segmentIndex":1,"text":"每一筆都不致命，可是當房租、交通、","startMs":435827,"endMs":439187,"startSeconds":435.827,"endSeconds":439.187},{"id":"S108-02","cueId":"S108","sequence":108,"segmentIndex":2,"text":"飲食也同時存在時，","startMs":439187,"endMs":440966,"startSeconds":439.187,"endSeconds":440.966},{"id":"S108-03","cueId":"S108","sequence":108,"segmentIndex":3,"text":"它就成為那張每個月一定會出現的帳單之一。","startMs":440966,"endMs":444920,"startSeconds":440.966,"endSeconds":444.92},{"id":"S109-01","cueId":"S109","sequence":109,"segmentIndex":1,"text":"不過至少，通訊方案還能比較、降級、換約。","startMs":445100,"endMs":449110,"startSeconds":445.1,"endSeconds":449.11},{"id":"S110-01","cueId":"S110","sequence":110,"segmentIndex":1,"text":"下一項就更麻煩。","startMs":449110,"endMs":450714,"startSeconds":449.11,"endSeconds":450.714},{"id":"S111-01","cueId":"S111","sequence":111,"segmentIndex":1,"text":"因為當身體真的需要時，你不能跟它說，下個月再處理。","startMs":450714,"endMs":455726,"startSeconds":450.714,"endSeconds":455.726},{"id":"S112-01","cueId":"S112","sequence":112,"segmentIndex":1,"text":"05｜第8名｜平常感覺不到，一來就不能不付｜","startMs":455726,"endMs":460137,"startSeconds":455.726,"endSeconds":460.137},{"id":"S112-02","cueId":"S112","sequence":112,"segmentIndex":2,"text":"醫療與保健","startMs":460137,"endMs":461140,"startSeconds":460.137,"endSeconds":461.14},{"id":"S113-01","cueId":"S113","sequence":113,"segmentIndex":1,"text":"第8名，醫療與保健。","startMs":461320,"endMs":463183,"startSeconds":461.32,"endSeconds":463.183},{"id":"S114-01","cueId":"S114","sequence":114,"segmentIndex":1,"text":"台灣有全民健保，這讓許多醫療支出的壓力，","startMs":463183,"endMs":466908,"startSeconds":463.183,"endSeconds":466.908},{"id":"S114-02","cueId":"S114","sequence":114,"segmentIndex":2,"text":"和沒有全民醫療保障的地方很不一樣。","startMs":466908,"endMs":470075,"startSeconds":466.908,"endSeconds":470.075},{"id":"S115-01","cueId":"S115","sequence":115,"segmentIndex":1,"text":"但有健保，不等於生活裡完全沒有醫療成本。","startMs":470075,"endMs":473800,"startSeconds":470.075,"endSeconds":473.8},{"id":"S116-01","cueId":"S116","sequence":116,"segmentIndex":1,"text":"掛號、部分負擔、牙科自費、眼鏡、藥品、復健，","startMs":473980,"endMs":478199,"startSeconds":473.98,"endSeconds":478.199},{"id":"S116-02","cueId":"S116","sequence":116,"segmentIndex":2,"text":"以及某些健保沒有完全涵蓋的項目，都可能突然出現。","startMs":478199,"endMs":482801,"startSeconds":478.199,"endSeconds":482.801},{"id":"S117-01","cueId":"S117","sequence":117,"segmentIndex":1,"text":"醫療成本最特別的地方，是它不一定每個月發生。","startMs":482801,"endMs":487020,"startSeconds":482.801,"endSeconds":487.02},{"id":"S118-01","cueId":"S118","sequence":118,"segmentIndex":1,"text":"所以平常很容易被忽略。","startMs":487200,"endMs":489312,"startSeconds":487.2,"endSeconds":489.312},{"id":"S119-01","cueId":"S119","sequence":119,"segmentIndex":1,"text":"一個22歲的人可能連續幾個月沒有任何醫療支出。","startMs":489312,"endMs":493728,"startSeconds":489.312,"endSeconds":493.728},{"id":"S120-01","cueId":"S120","sequence":120,"segmentIndex":1,"text":"可是某一天牙齒突然痛、眼鏡壞了、運動受傷，","startMs":493728,"endMs":497760,"startSeconds":493.728,"endSeconds":497.76},{"id":"S120-02","cueId":"S120","sequence":120,"segmentIndex":2,"text":"支出就可能集中出現。","startMs":497760,"endMs":499680,"startSeconds":497.76,"endSeconds":499.68},{"id":"S121-01","cueId":"S121","sequence":121,"segmentIndex":1,"text":"對有穩定儲蓄的人來說，這叫臨時開銷。","startMs":499860,"endMs":503381,"startSeconds":499.86,"endSeconds":503.381},{"id":"S122-01","cueId":"S122","sequence":122,"segmentIndex":1,"text":"對帳戶本來就只剩幾千元的人來說，","startMs":503381,"endMs":506511,"startSeconds":503.381,"endSeconds":506.511},{"id":"S122-02","cueId":"S122","sequence":122,"segmentIndex":2,"text":"它可能直接改變這個月其他安排。","startMs":506511,"endMs":509445,"startSeconds":506.511,"endSeconds":509.445},{"id":"S123-01","cueId":"S123","sequence":123,"segmentIndex":1,"text":"假設一位剛工作的青年，本來計畫月底和朋友出去玩，","startMs":509445,"endMs":514140,"startSeconds":509.445,"endSeconds":514.14},{"id":"S123-02","cueId":"S123","sequence":123,"segmentIndex":2,"text":"結果突然需要看牙。","startMs":514140,"endMs":515900,"startSeconds":514.14,"endSeconds":515.9},{"id":"S124-01","cueId":"S124","sequence":124,"segmentIndex":1,"text":"真正被取消的，可能不是醫療。","startMs":516080,"endMs":518704,"startSeconds":516.08,"endSeconds":518.704},{"id":"S125-01","cueId":"S125","sequence":125,"segmentIndex":1,"text":"而是旅行。","startMs":518704,"endMs":519641,"startSeconds":518.704,"endSeconds":519.641},{"id":"S126-01","cueId":"S126","sequence":126,"segmentIndex":1,"text":"因為醫療比較難不付，休閒比較容易被犧牲。","startMs":519641,"endMs":523390,"startSeconds":519.641,"endSeconds":523.39},{"id":"S127-01","cueId":"S127","sequence":127,"segmentIndex":1,"text":"這就是生活成本的另一個現實。","startMs":523390,"endMs":526014,"startSeconds":523.39,"endSeconds":526.014},{"id":"S128-01","cueId":"S128","sequence":128,"segmentIndex":1,"text":"有些成本不是最大筆，卻因為不可預測，","startMs":526014,"endMs":529388,"startSeconds":526.014,"endSeconds":529.388},{"id":"S128-02","cueId":"S128","sequence":128,"segmentIndex":2,"text":"而讓收入低的人更需要預留緩衝。","startMs":529388,"endMs":532200,"startSeconds":529.388,"endSeconds":532.2},{"id":"S129-01","cueId":"S129","sequence":129,"segmentIndex":1,"text":"所以我們把醫療放在第8名。","startMs":532380,"endMs":534732,"startSeconds":532.38,"endSeconds":534.732},{"id":"S130-01","cueId":"S130","sequence":130,"segmentIndex":1,"text":"它不一定天天來。","startMs":534732,"endMs":536179,"startSeconds":534.732,"endSeconds":536.179},{"id":"S131-01","cueId":"S131","sequence":131,"segmentIndex":1,"text":"可是來的時候，你通常沒有太多討價還價的空間。","startMs":536179,"endMs":540160,"startSeconds":536.179,"endSeconds":540.16},{"id":"S132-01","cueId":"S132","sequence":132,"segmentIndex":1,"text":"而接下來這一項，很多九年級生甚至是主動付錢。","startMs":540160,"endMs":544140,"startSeconds":540.16,"endSeconds":544.14},{"id":"S133-01","cueId":"S133","sequence":133,"segmentIndex":1,"text":"因為他們害怕的不是今天生活不了，而是明天跟不上。","startMs":544320,"endMs":548895,"startSeconds":544.32,"endSeconds":548.895},{"id":"S134-01","cueId":"S134","sequence":134,"segmentIndex":1,"text":"06｜第7名｜畢業以後，學習反而開始收費｜","startMs":548895,"endMs":552898,"startSeconds":548.895,"endSeconds":552.898},{"id":"S134-02","cueId":"S134","sequence":134,"segmentIndex":2,"text":"教育與技能進修第7名，教育與技能進修。","startMs":552898,"endMs":556520,"startSeconds":552.898,"endSeconds":556.52},{"id":"S135-01","cueId":"S135","sequence":135,"segmentIndex":1,"text":"如果九年級生剛從學校畢業，最容易產生一種錯覺。","startMs":556700,"endMs":560637,"startSeconds":556.7,"endSeconds":560.637},{"id":"S136-01","cueId":"S136","sequence":136,"segmentIndex":1,"text":"學費繳完了，教育成本應該結束了。","startMs":560637,"endMs":563376,"startSeconds":560.637,"endSeconds":563.376},{"id":"S137-01","cueId":"S137","sequence":137,"segmentIndex":1,"text":"但真正進入職場後，很多人才發現，","startMs":563376,"endMs":566115,"startSeconds":563.376,"endSeconds":566.115},{"id":"S137-02","cueId":"S137","sequence":137,"segmentIndex":2,"text":"學習只是換了一種收費方式。","startMs":566115,"endMs":568340,"startSeconds":566.115,"endSeconds":568.34},{"id":"S138-01","cueId":"S138","sequence":138,"segmentIndex":1,"text":"英文檢定、專業證照、線上課程、軟體訂閱、AI工具、","startMs":568520,"endMs":574004,"startSeconds":568.52,"endSeconds":574.004},{"id":"S138-02","cueId":"S138","sequence":138,"segmentIndex":2,"text":"設計工具、程式課程、研究所補習，","startMs":574004,"endMs":577514,"startSeconds":574.004,"endSeconds":577.514},{"id":"S138-03","cueId":"S138","sequence":138,"segmentIndex":3,"text":"甚至只是為了讓履歷多一項技能，都可能要錢。","startMs":577514,"endMs":582120,"startSeconds":577.514,"endSeconds":582.12},{"id":"S139-01","cueId":"S139","sequence":139,"segmentIndex":1,"text":"上一集我們談AI改變職場規則。","startMs":582300,"endMs":584888,"startSeconds":582.3,"endSeconds":584.888},{"id":"S140-01","cueId":"S140","sequence":140,"segmentIndex":1,"text":"這一集再看一次，就會發現AI不只改變工作，","startMs":584888,"endMs":588510,"startSeconds":584.888,"endSeconds":588.51},{"id":"S140-02","cueId":"S140","sequence":140,"segmentIndex":2,"text":"也可能增加一種新的生活成本。","startMs":588510,"endMs":590925,"startSeconds":588.51,"endSeconds":590.925},{"id":"S141-01","cueId":"S141","sequence":141,"segmentIndex":1,"text":"「保持自己不要落後」的成本。","startMs":590925,"endMs":593340,"startSeconds":590.925,"endSeconds":593.34},{"id":"S142-01","cueId":"S142","sequence":142,"segmentIndex":1,"text":"假設一位24歲的上班族發現，","startMs":593520,"endMs":596477,"startSeconds":593.52,"endSeconds":596.477},{"id":"S142-02","cueId":"S142","sequence":142,"segmentIndex":2,"text":"公司開始要求使用AI工具。","startMs":596477,"endMs":599222,"startSeconds":596.477,"endSeconds":599.222},{"id":"S143-01","cueId":"S143","sequence":143,"segmentIndex":1,"text":"免費版本能用，但功能有限。","startMs":599222,"endMs":601967,"startSeconds":599.222,"endSeconds":601.967},{"id":"S144-01","cueId":"S144","sequence":144,"segmentIndex":1,"text":"他想學得更快，可能開始訂閱工具、買課程，","startMs":601967,"endMs":606191,"startSeconds":601.967,"endSeconds":606.191},{"id":"S144-02","cueId":"S144","sequence":144,"segmentIndex":2,"text":"或花週末去上課。","startMs":606191,"endMs":607880,"startSeconds":606.191,"endSeconds":607.88},{"id":"S145-01","cueId":"S145","sequence":145,"segmentIndex":1,"text":"這些支出和房租不一樣。","startMs":608060,"endMs":609920,"startSeconds":608.06,"endSeconds":609.92},{"id":"S146-01","cueId":"S146","sequence":146,"segmentIndex":1,"text":"沒有人拿帳單逼你繳。","startMs":609920,"endMs":611610,"startSeconds":609.92,"endSeconds":611.61},{"id":"S147-01","cueId":"S147","sequence":147,"segmentIndex":1,"text":"可是如果你認為不學就可能失去下一個機會，","startMs":611610,"endMs":614991,"startSeconds":611.61,"endSeconds":614.991},{"id":"S147-02","cueId":"S147","sequence":147,"segmentIndex":2,"text":"它就會從「想要」慢慢變成「需要」。","startMs":614991,"endMs":617865,"startSeconds":614.991,"endSeconds":617.865},{"id":"S148-01","cueId":"S148","sequence":148,"segmentIndex":1,"text":"教育支出的青年衝擊，","startMs":617865,"endMs":619555,"startSeconds":617.865,"endSeconds":619.555},{"id":"S148-02","cueId":"S148","sequence":148,"segmentIndex":2,"text":"也因此不能只看家庭教育支出占比。","startMs":619555,"endMs":622260,"startSeconds":619.555,"endSeconds":622.26},{"id":"S149-01","cueId":"S149","sequence":149,"segmentIndex":1,"text":"因為一個已經離開學校的年輕人，","startMs":622440,"endMs":625448,"startSeconds":622.44,"endSeconds":625.448},{"id":"S149-02","cueId":"S149","sequence":149,"segmentIndex":2,"text":"進修可能散落在各種平台、軟體與證照裡。","startMs":625448,"endMs":629259,"startSeconds":625.448,"endSeconds":629.259},{"id":"S150-01","cueId":"S150","sequence":150,"segmentIndex":1,"text":"第7名的真正壓力不是每個人都花很多。","startMs":629259,"endMs":632869,"startSeconds":629.259,"endSeconds":632.869},{"id":"S151-01","cueId":"S151","sequence":151,"segmentIndex":1,"text":"而是職涯變動越快，越多人會開始問自己：","startMs":632869,"endMs":636680,"startSeconds":632.869,"endSeconds":636.68},{"id":"S152-01","cueId":"S152","sequence":152,"segmentIndex":1,"text":"我是不是還得花錢，才能繼續有資格工作？","startMs":636860,"endMs":640726,"startSeconds":636.86,"endSeconds":640.726},{"id":"S153-01","cueId":"S153","sequence":153,"segmentIndex":1,"text":"不過進修至少還能選擇時間。","startMs":640726,"endMs":643372,"startSeconds":640.726,"endSeconds":643.372},{"id":"S154-01","cueId":"S154","sequence":154,"segmentIndex":1,"text":"下一項更有趣。","startMs":643372,"endMs":644796,"startSeconds":643.372,"endSeconds":644.796},{"id":"S155-01","cueId":"S155","sequence":155,"segmentIndex":1,"text":"它明明不是生存必需品，卻很難完全拿掉。","startMs":644796,"endMs":648663,"startSeconds":644.796,"endSeconds":648.663},{"id":"S156-01","cueId":"S156","sequence":156,"segmentIndex":1,"text":"因為人不是只需要活著，也需要和別人一起生活。","startMs":648663,"endMs":653140,"startSeconds":648.663,"endSeconds":653.14},{"id":"S157-01","cueId":"S157","sequence":157,"segmentIndex":1,"text":"07｜第6名｜最容易被刪掉，也最捨不得全部刪掉｜","startMs":653320,"endMs":658184,"startSeconds":653.32,"endSeconds":658.184},{"id":"S157-02","cueId":"S157","sequence":157,"segmentIndex":2,"text":"社交與休閒第6名，社交與休閒。","startMs":658184,"endMs":661224,"startSeconds":658.184,"endSeconds":661.224},{"id":"S158-01","cueId":"S158","sequence":158,"segmentIndex":1,"text":"如果只看生存，電影可以不看，咖啡可以不喝，","startMs":661224,"endMs":665480,"startSeconds":661.224,"endSeconds":665.48},{"id":"S158-02","cueId":"S158","sequence":158,"segmentIndex":2,"text":"旅行可以不去，聚餐也可以拒絕。","startMs":665480,"endMs":668520,"startSeconds":665.48,"endSeconds":668.52},{"id":"S159-01","cueId":"S159","sequence":159,"segmentIndex":1,"text":"所以當收入不夠時，休閒往往最先被砍。","startMs":668700,"endMs":672228,"startSeconds":668.7,"endSeconds":672.228},{"id":"S160-01","cueId":"S160","sequence":160,"segmentIndex":1,"text":"但問題是，","startMs":672228,"endMs":673208,"startSeconds":672.228,"endSeconds":673.208},{"id":"S160-02","cueId":"S160","sequence":160,"segmentIndex":2,"text":"人不是一張只需要維持最低成本的Excel表格。","startMs":673208,"endMs":677716,"startSeconds":673.208,"endSeconds":677.716},{"id":"S161-01","cueId":"S161","sequence":161,"segmentIndex":1,"text":"剛進職場的年輕人，需要朋友。","startMs":677716,"endMs":680460,"startSeconds":677.716,"endSeconds":680.46},{"id":"S162-01","cueId":"S162","sequence":162,"segmentIndex":1,"text":"需要和同事建立關係。","startMs":680640,"endMs":682511,"startSeconds":680.64,"endSeconds":682.511},{"id":"S163-01","cueId":"S163","sequence":163,"segmentIndex":1,"text":"需要約會。","startMs":682511,"endMs":683446,"startSeconds":682.511,"endSeconds":683.446},{"id":"S164-01","cueId":"S164","sequence":164,"segmentIndex":1,"text":"需要偶爾離開工作。","startMs":683446,"endMs":685130,"startSeconds":683.446,"endSeconds":685.13},{"id":"S165-01","cueId":"S165","sequence":165,"segmentIndex":1,"text":"需要一個不只是睡覺和上班的人生。","startMs":685130,"endMs":688123,"startSeconds":685.13,"endSeconds":688.123},{"id":"S166-01","cueId":"S166","sequence":166,"segmentIndex":1,"text":"假設一位23歲青年為了省錢，連續幾週拒絕朋友聚餐。","startMs":688123,"endMs":692800,"startSeconds":688.123,"endSeconds":692.8},{"id":"S167-01","cueId":"S167","sequence":167,"segmentIndex":1,"text":"帳戶確實多留下一點錢。","startMs":692980,"endMs":695061,"startSeconds":692.98,"endSeconds":695.061},{"id":"S168-01","cueId":"S168","sequence":168,"segmentIndex":1,"text":"可是當所有人的生活都在繼續，他也可能開始覺得，","startMs":695061,"endMs":699411,"startSeconds":695.061,"endSeconds":699.411},{"id":"S168-02","cueId":"S168","sequence":168,"segmentIndex":2,"text":"自己不是在省一頓飯，而是在慢慢退出某些關係。","startMs":699411,"endMs":703572,"startSeconds":699.411,"endSeconds":703.572},{"id":"S169-01","cueId":"S169","sequence":169,"segmentIndex":1,"text":"這也是為什麼休閒成本很特殊。","startMs":703572,"endMs":706220,"startSeconds":703.572,"endSeconds":706.22},{"id":"S170-01","cueId":"S170","sequence":170,"segmentIndex":1,"text":"它的不可避免性不高，但心理與社會層面的價值很高。","startMs":706400,"endMs":710654,"startSeconds":706.4,"endSeconds":710.654},{"id":"S171-01","cueId":"S171","sequence":171,"segmentIndex":1,"text":"所以收入吃緊時，最容易出現的不是「完全沒有休閒」。","startMs":710654,"endMs":715084,"startSeconds":710.654,"endSeconds":715.084},{"id":"S172-01","cueId":"S172","sequence":172,"segmentIndex":1,"text":"而是每一次休閒之前，都先算一次。","startMs":715084,"endMs":717920,"startSeconds":715.084,"endSeconds":717.92},{"id":"S173-01","cueId":"S173","sequence":173,"segmentIndex":1,"text":"這杯咖啡值不值得？","startMs":718100,"endMs":719736,"startSeconds":718.1,"endSeconds":719.736},{"id":"S174-01","cueId":"S174","sequence":174,"segmentIndex":1,"text":"這場電影要不要去？","startMs":719736,"endMs":721372,"startSeconds":719.736,"endSeconds":721.372},{"id":"S175-01","cueId":"S175","sequence":175,"segmentIndex":1,"text":"這次聚餐是不是又要1000元？","startMs":721372,"endMs":724098,"startSeconds":721.372,"endSeconds":724.098},{"id":"S176-01","cueId":"S176","sequence":176,"segmentIndex":1,"text":"這趟旅行是不是乾脆算了？","startMs":724098,"endMs":726280,"startSeconds":724.098,"endSeconds":726.28},{"id":"S177-01","cueId":"S177","sequence":177,"segmentIndex":1,"text":"當生活裡所有非必要支出都必須先經過計算，","startMs":726280,"endMs":729915,"startSeconds":726.28,"endSeconds":729.915},{"id":"S177-02","cueId":"S177","sequence":177,"segmentIndex":2,"text":"真正被壓縮的其實就是自由感。","startMs":729915,"endMs":732460,"startSeconds":729.915,"endSeconds":732.46},{"id":"S178-01","cueId":"S178","sequence":178,"segmentIndex":1,"text":"所以第6名不是因為休閒最貴。","startMs":732640,"endMs":735390,"startSeconds":732.64,"endSeconds":735.39},{"id":"S179-01","cueId":"S179","sequence":179,"segmentIndex":1,"text":"而是因為它最容易成為其他必要成本上升之後，","startMs":735390,"endMs":739514,"startSeconds":735.39,"endSeconds":739.514},{"id":"S179-02","cueId":"S179","sequence":179,"segmentIndex":2,"text":"被犧牲的那一塊。","startMs":739514,"endMs":741085,"startSeconds":739.514,"endSeconds":741.085},{"id":"S180-01","cueId":"S180","sequence":180,"segmentIndex":1,"text":"接下來進入前5名。","startMs":741085,"endMs":742853,"startSeconds":741.085,"endSeconds":742.853},{"id":"S181-01","cueId":"S181","sequence":181,"segmentIndex":1,"text":"從這裡開始，越來越多支出不是「想不想花」","startMs":742853,"endMs":746781,"startSeconds":742.853,"endSeconds":746.781},{"id":"S181-02","cueId":"S181","sequence":181,"segmentIndex":2,"text":"，而是生活本身會一直把帳單送過來。","startMs":746781,"endMs":750120,"startSeconds":746.781,"endSeconds":750.12},{"id":"S182-01","cueId":"S182","sequence":182,"segmentIndex":1,"text":"08｜第5名｜每一樣都不貴，加起來卻一直補貨｜","startMs":750300,"endMs":754210,"startSeconds":750.3,"endSeconds":754.21},{"id":"S182-02","cueId":"S182","sequence":182,"segmentIndex":2,"text":"日用品與家務支出第5名，日用品與家務支出。","startMs":754210,"endMs":757780,"startSeconds":754.21,"endSeconds":757.78},{"id":"S183-01","cueId":"S183","sequence":183,"segmentIndex":1,"text":"衛生紙、洗髮精、洗衣精、牙膏、垃圾袋、清潔用品。","startMs":757780,"endMs":761860,"startSeconds":757.78,"endSeconds":761.86},{"id":"S184-01","cueId":"S184","sequence":184,"segmentIndex":1,"text":"第一次離開家自己住的人，","startMs":762040,"endMs":764247,"startSeconds":762.04,"endSeconds":764.247},{"id":"S184-02","cueId":"S184","sequence":184,"segmentIndex":2,"text":"很容易在搬進租屋處的第一週才發現：","startMs":764247,"endMs":767373,"startSeconds":764.247,"endSeconds":767.373},{"id":"S184-03","cueId":"S184","sequence":184,"segmentIndex":3,"text":"原來家裡那些「本來就有」的東西，全部都要有人買。","startMs":767373,"endMs":771786,"startSeconds":767.373,"endSeconds":771.786},{"id":"S185-01","cueId":"S185","sequence":185,"segmentIndex":1,"text":"學生住家裡時，很少有人計算一卷衛生紙到底多少錢。","startMs":771786,"endMs":776200,"startSeconds":771.786,"endSeconds":776.2},{"id":"S186-01","cueId":"S186","sequence":186,"segmentIndex":1,"text":"因為它用完了，下一包常常已經在櫃子裡。","startMs":776380,"endMs":779960,"startSeconds":776.38,"endSeconds":779.96},{"id":"S187-01","cueId":"S187","sequence":187,"segmentIndex":1,"text":"但開始獨立生活後，每一樣原本透明的家庭成本，","startMs":779960,"endMs":784105,"startSeconds":779.96,"endSeconds":784.105},{"id":"S187-02","cueId":"S187","sequence":187,"segmentIndex":2,"text":"都會慢慢變成自己的購物清單。","startMs":784105,"endMs":786742,"startSeconds":784.105,"endSeconds":786.742},{"id":"S188-01","cueId":"S188","sequence":188,"segmentIndex":1,"text":"日用品的特點是單價通常不高。","startMs":786742,"endMs":789380,"startSeconds":786.742,"endSeconds":789.38},{"id":"S189-01","cueId":"S189","sequence":189,"segmentIndex":1,"text":"也正因如此，很容易低估。","startMs":789560,"endMs":791898,"startSeconds":789.56,"endSeconds":791.898},{"id":"S190-01","cueId":"S190","sequence":190,"segmentIndex":1,"text":"今天100元，明天200元，下週又補一樣。","startMs":791898,"endMs":795991,"startSeconds":791.898,"endSeconds":795.991},{"id":"S191-01","cueId":"S191","sequence":191,"segmentIndex":1,"text":"你不會因為買了一瓶洗衣精而覺得生活成本爆炸。","startMs":795991,"endMs":800278,"startSeconds":795.991,"endSeconds":800.278},{"id":"S192-01","cueId":"S192","sequence":192,"segmentIndex":1,"text":"可是月底回頭看，會發現生活不是只有幾張大帳單。","startMs":800278,"endMs":804760,"startSeconds":800.278,"endSeconds":804.76},{"id":"S193-01","cueId":"S193","sequence":193,"segmentIndex":1,"text":"還有很多小洞。","startMs":804940,"endMs":806266,"startSeconds":804.94,"endSeconds":806.266},{"id":"S194-01","cueId":"S194","sequence":194,"segmentIndex":1,"text":"而且這些東西大多不能永久取消。","startMs":806266,"endMs":809106,"startSeconds":806.266,"endSeconds":809.106},{"id":"S195-01","cueId":"S195","sequence":195,"segmentIndex":1,"text":"你可以選便宜品牌，可以趁特價囤貨，","startMs":809106,"endMs":812325,"startSeconds":809.106,"endSeconds":812.325},{"id":"S195-02","cueId":"S195","sequence":195,"segmentIndex":2,"text":"可以減少不必要用品。","startMs":812325,"endMs":814219,"startSeconds":812.325,"endSeconds":814.219},{"id":"S196-01","cueId":"S196","sequence":196,"segmentIndex":1,"text":"但基本清潔與日常消耗仍然存在。","startMs":814219,"endMs":817060,"startSeconds":814.219,"endSeconds":817.06},{"id":"S197-01","cueId":"S197","sequence":197,"segmentIndex":1,"text":"這就是第5名的理由。","startMs":817240,"endMs":819014,"startSeconds":817.24,"endSeconds":819.014},{"id":"S198-01","cueId":"S198","sequence":198,"segmentIndex":1,"text":"它不是最痛的一刀，而是一連串很小、很規律的切口。","startMs":819014,"endMs":823270,"startSeconds":819.014,"endSeconds":823.27},{"id":"S199-01","cueId":"S199","sequence":199,"segmentIndex":1,"text":"而如果你開始自己住，除了買這些東西，","startMs":823270,"endMs":826463,"startSeconds":823.27,"endSeconds":826.463},{"id":"S199-02","cueId":"S199","sequence":199,"segmentIndex":2,"text":"還會第一次真正看到另一張以前可能不太注意的帳單。","startMs":826463,"endMs":830720,"startSeconds":826.463,"endSeconds":830.72},{"id":"S200-01","cueId":"S200","sequence":200,"segmentIndex":1,"text":"水、電、瓦斯。","startMs":830900,"endMs":832230,"startSeconds":830.9,"endSeconds":832.23},{"id":"S201-01","cueId":"S201","sequence":201,"segmentIndex":1,"text":"09｜第4名｜冷氣一開，就開始計算｜","startMs":832230,"endMs":835650,"startSeconds":832.23,"endSeconds":835.65},{"id":"S201-02","cueId":"S201","sequence":201,"segmentIndex":2,"text":"水電瓦斯與居住能源第4名，水電瓦斯與居住能源。","startMs":835650,"endMs":840020,"startSeconds":835.65,"endSeconds":840.02},{"id":"S202-01","cueId":"S202","sequence":202,"segmentIndex":1,"text":"對住在家裡的年輕人來說，水電費可能只是一句提醒。","startMs":840020,"endMs":844580,"startSeconds":840.02,"endSeconds":844.58},{"id":"S203-01","cueId":"S203","sequence":203,"segmentIndex":1,"text":"冷氣不要開太久。","startMs":844760,"endMs":846333,"startSeconds":844.76,"endSeconds":846.333},{"id":"S204-01","cueId":"S204","sequence":204,"segmentIndex":1,"text":"燈記得關。","startMs":846333,"endMs":847316,"startSeconds":846.333,"endSeconds":847.316},{"id":"S205-01","cueId":"S205","sequence":205,"segmentIndex":1,"text":"可是當帳單第一次直接寄到自己手上，感受就不一樣。","startMs":847316,"endMs":852035,"startSeconds":847.316,"endSeconds":852.035},{"id":"S206-01","cueId":"S206","sequence":206,"segmentIndex":1,"text":"台灣夏季炎熱，冷氣對很多人已經不是純粹享受。","startMs":852035,"endMs":856361,"startSeconds":852.035,"endSeconds":856.361},{"id":"S207-01","cueId":"S207","sequence":207,"segmentIndex":1,"text":"租屋空間如果西曬、通風差，能源支出更難完全避免。","startMs":856361,"endMs":861080,"startSeconds":856.361,"endSeconds":861.08},{"id":"S208-01","cueId":"S208","sequence":208,"segmentIndex":1,"text":"洗澡需要熱水。","startMs":861260,"endMs":862804,"startSeconds":861.26,"endSeconds":862.804},{"id":"S209-01","cueId":"S209","sequence":209,"segmentIndex":1,"text":"冰箱要一直運轉。","startMs":862804,"endMs":864568,"startSeconds":862.804,"endSeconds":864.568},{"id":"S210-01","cueId":"S210","sequence":210,"segmentIndex":1,"text":"電腦、螢幕、路由器、手機，每天都在用電。","startMs":864568,"endMs":868979,"startSeconds":864.568,"endSeconds":868.979},{"id":"S211-01","cueId":"S211","sequence":211,"segmentIndex":1,"text":"如果工作還有居家辦公，住處同時變成工作場所。","startMs":868979,"endMs":873832,"startSeconds":868.979,"endSeconds":873.832},{"id":"S212-01","cueId":"S212","sequence":212,"segmentIndex":1,"text":"這些成本會和生活時間一起增加。","startMs":873832,"endMs":877140,"startSeconds":873.832,"endSeconds":877.14},{"id":"S213-01","cueId":"S213","sequence":213,"segmentIndex":1,"text":"水電瓦斯的壓力不一定比房租高。","startMs":877320,"endMs":880111,"startSeconds":877.32,"endSeconds":880.111},{"id":"S214-01","cueId":"S214","sequence":214,"segmentIndex":1,"text":"但它有一個特性。","startMs":880111,"endMs":881600,"startSeconds":880.111,"endSeconds":881.6},{"id":"S215-01","cueId":"S215","sequence":215,"segmentIndex":1,"text":"你住進去之後才真正知道。","startMs":881600,"endMs":883833,"startSeconds":881.6,"endSeconds":883.833},{"id":"S216-01","cueId":"S216","sequence":216,"segmentIndex":1,"text":"同樣是一間套房，隔熱、設備效率、採光與通風不同，","startMs":883833,"endMs":888299,"startSeconds":883.833,"endSeconds":888.299},{"id":"S216-02","cueId":"S216","sequence":216,"segmentIndex":2,"text":"最後帳單可能就不同。","startMs":888299,"endMs":890160,"startSeconds":888.299,"endSeconds":890.16},{"id":"S217-01","cueId":"S217","sequence":217,"segmentIndex":1,"text":"所以居住成本不能只看租金。","startMs":890340,"endMs":892684,"startSeconds":890.34,"endSeconds":892.684},{"id":"S218-01","cueId":"S218","sequence":218,"segmentIndex":1,"text":"租下一個空間之後，還有維持那個空間可以生活的成本。","startMs":892684,"endMs":897192,"startSeconds":892.684,"endSeconds":897.192},{"id":"S219-01","cueId":"S219","sequence":219,"segmentIndex":1,"text":"假設一位青年夏天為了省電，回家後一直撐著不開冷氣。","startMs":897192,"endMs":901700,"startSeconds":897.192,"endSeconds":901.7},{"id":"S220-01","cueId":"S220","sequence":220,"segmentIndex":1,"text":"最後他省下的可能是幾百元，換來的是睡不好。","startMs":901880,"endMs":905867,"startSeconds":901.88,"endSeconds":905.867},{"id":"S221-01","cueId":"S221","sequence":221,"segmentIndex":1,"text":"第二天照樣要上班。","startMs":905867,"endMs":907576,"startSeconds":905.867,"endSeconds":907.576},{"id":"S222-01","cueId":"S222","sequence":222,"segmentIndex":1,"text":"這就是生活成本開始影響生活品質的地方。","startMs":907576,"endMs":911184,"startSeconds":907.576,"endSeconds":911.184},{"id":"S223-01","cueId":"S223","sequence":223,"segmentIndex":1,"text":"進入前3名之前，","startMs":911184,"endMs":912703,"startSeconds":911.184,"endSeconds":912.703},{"id":"S223-02","cueId":"S223","sequence":223,"segmentIndex":2,"text":"還有一項每天把我們從住處送到工作地點的成本。","startMs":912703,"endMs":916880,"startSeconds":912.703,"endSeconds":916.88},{"id":"S224-01","cueId":"S224","sequence":224,"segmentIndex":1,"text":"10｜第3名｜工作還沒開始，先付一筆到公司的錢｜","startMs":917060,"endMs":921766,"startSeconds":917.06,"endSeconds":921.766},{"id":"S224-02","cueId":"S224","sequence":224,"segmentIndex":2,"text":"交通與通勤第3名，交通與通勤。","startMs":921766,"endMs":924708,"startSeconds":921.766,"endSeconds":924.708},{"id":"S225-01","cueId":"S225","sequence":225,"segmentIndex":1,"text":"找到一份工作，第一個問題是薪水多少。","startMs":924708,"endMs":928238,"startSeconds":924.708,"endSeconds":928.238},{"id":"S226-01","cueId":"S226","sequence":226,"segmentIndex":1,"text":"第二個問題常常是，公司在哪裡？","startMs":928238,"endMs":931180,"startSeconds":928.238,"endSeconds":931.18},{"id":"S227-01","cueId":"S227","sequence":227,"segmentIndex":1,"text":"因為距離會變成成本。","startMs":931360,"endMs":933539,"startSeconds":931.36,"endSeconds":933.539},{"id":"S228-01","cueId":"S228","sequence":228,"segmentIndex":1,"text":"捷運、公車、台鐵、機車油錢、停車費、保養，","startMs":933539,"endMs":938115,"startSeconds":933.539,"endSeconds":938.115},{"id":"S228-02","cueId":"S228","sequence":228,"segmentIndex":2,"text":"甚至偶爾叫車。","startMs":938115,"endMs":939640,"startSeconds":938.115,"endSeconds":939.64},{"id":"S229-01","cueId":"S229","sequence":229,"segmentIndex":1,"text":"交通費不是每個人都一樣。","startMs":939640,"endMs":942255,"startSeconds":939.64,"endSeconds":942.255},{"id":"S230-01","cueId":"S230","sequence":230,"segmentIndex":1,"text":"住在都市、住在郊區，搭大眾運輸或騎機車，","startMs":942255,"endMs":946613,"startSeconds":942.255,"endSeconds":946.613},{"id":"S230-02","cueId":"S230","sequence":230,"segmentIndex":2,"text":"差異都很大。","startMs":946613,"endMs":947920,"startSeconds":946.613,"endSeconds":947.92},{"id":"S231-01","cueId":"S231","sequence":231,"segmentIndex":1,"text":"但對剛進社會的人來說，交通有兩種成本。","startMs":948100,"endMs":951544,"startSeconds":948.1,"endSeconds":951.544},{"id":"S232-01","cueId":"S232","sequence":232,"segmentIndex":1,"text":"一種是錢。","startMs":951544,"endMs":952451,"startSeconds":951.544,"endSeconds":952.451},{"id":"S233-01","cueId":"S233","sequence":233,"segmentIndex":1,"text":"另一種是時間。","startMs":952451,"endMs":953720,"startSeconds":952.451,"endSeconds":953.72},{"id":"S234-01","cueId":"S234","sequence":234,"segmentIndex":1,"text":"假設有兩份工作。","startMs":953720,"endMs":955170,"startSeconds":953.72,"endSeconds":955.17},{"id":"S235-01","cueId":"S235","sequence":235,"segmentIndex":1,"text":"一份薪水多2000元，但每天來回多花一個小時。","startMs":955170,"endMs":959340,"startSeconds":955.17,"endSeconds":959.34},{"id":"S236-01","cueId":"S236","sequence":236,"segmentIndex":1,"text":"如果還要轉車、付更多交通費，","startMs":959520,"endMs":962348,"startSeconds":959.52,"endSeconds":962.348},{"id":"S236-02","cueId":"S236","sequence":236,"segmentIndex":2,"text":"那2000元到底算不算真的多？","startMs":962348,"endMs":965378,"startSeconds":962.348,"endSeconds":965.378},{"id":"S237-01","cueId":"S237","sequence":237,"segmentIndex":1,"text":"這就是青年生活成本很容易被薪資數字遮住的地方。","startMs":965378,"endMs":970024,"startSeconds":965.378,"endSeconds":970.024},{"id":"S238-01","cueId":"S238","sequence":238,"segmentIndex":1,"text":"薪水寫在職缺上。","startMs":970024,"endMs":971640,"startSeconds":970.024,"endSeconds":971.64},{"id":"S239-01","cueId":"S239","sequence":239,"segmentIndex":1,"text":"通勤成本卻要開始工作以後才慢慢感受到。","startMs":971820,"endMs":975599,"startSeconds":971.82,"endSeconds":975.599},{"id":"S240-01","cueId":"S240","sequence":240,"segmentIndex":1,"text":"而且交通通常和居住綁在一起。","startMs":975599,"endMs":978384,"startSeconds":975.599,"endSeconds":978.384},{"id":"S241-01","cueId":"S241","sequence":241,"segmentIndex":1,"text":"住得離工作近，房租可能比較高。","startMs":978384,"endMs":981367,"startSeconds":978.384,"endSeconds":981.367},{"id":"S242-01","cueId":"S242","sequence":242,"segmentIndex":1,"text":"住得遠一點，租金也許比較低，但交通時間與費用增加。","startMs":981367,"endMs":986340,"startSeconds":981.367,"endSeconds":986.34},{"id":"S243-01","cueId":"S243","sequence":243,"segmentIndex":1,"text":"所以第3名不只是「車票多少錢」。","startMs":986520,"endMs":989552,"startSeconds":986.52,"endSeconds":989.552},{"id":"S244-01","cueId":"S244","sequence":244,"segmentIndex":1,"text":"它其實是一個交換。","startMs":989552,"endMs":991257,"startSeconds":989.552,"endSeconds":991.257},{"id":"S245-01","cueId":"S245","sequence":245,"segmentIndex":1,"text":"用租金換交通。","startMs":991257,"endMs":992583,"startSeconds":991.257,"endSeconds":992.583},{"id":"S246-01","cueId":"S246","sequence":246,"segmentIndex":1,"text":"用交通換時間。","startMs":992583,"endMs":993910,"startSeconds":992.583,"endSeconds":993.91},{"id":"S247-01","cueId":"S247","sequence":247,"segmentIndex":1,"text":"再用時間換生活品質。","startMs":993910,"endMs":995804,"startSeconds":993.91,"endSeconds":995.804},{"id":"S248-01","cueId":"S248","sequence":248,"segmentIndex":1,"text":"對收入還不高的年輕人來說，","startMs":995804,"endMs":998267,"startSeconds":995.804,"endSeconds":998.267},{"id":"S248-02","cueId":"S248","sequence":248,"segmentIndex":2,"text":"很少有一個選項是完全免費的。","startMs":998267,"endMs":1000920,"startSeconds":998.267,"endSeconds":1000.92},{"id":"S249-01","cueId":"S249","sequence":249,"segmentIndex":1,"text":"而前面這些支出，有些一天一次、有些一個月一次。","startMs":1001100,"endMs":1005522,"startSeconds":1001.1,"endSeconds":1005.522},{"id":"S250-01","cueId":"S250","sequence":250,"segmentIndex":1,"text":"下一項更直接。","startMs":1005522,"endMs":1006868,"startSeconds":1005.522,"endSeconds":1006.868},{"id":"S251-01","cueId":"S251","sequence":251,"segmentIndex":1,"text":"一天可能三次。","startMs":1006868,"endMs":1008214,"startSeconds":1006.868,"endSeconds":1008.214},{"id":"S252-01","cueId":"S252","sequence":252,"segmentIndex":1,"text":"11｜第2名｜一天三次，最難假裝不存在｜飲食與外食","startMs":1008214,"endMs":1013020,"startSeconds":1008.214,"endSeconds":1013.02},{"id":"S253-01","cueId":"S253","sequence":253,"segmentIndex":1,"text":"第2名，飲食與外食。","startMs":1013200,"endMs":1015027,"startSeconds":1013.2,"endSeconds":1015.027},{"id":"S254-01","cueId":"S254","sequence":254,"segmentIndex":1,"text":"你可以一年不買新手機。","startMs":1015027,"endMs":1017036,"startSeconds":1015.027,"endSeconds":1017.036},{"id":"S255-01","cueId":"S255","sequence":255,"segmentIndex":1,"text":"可以幾個月不買衣服。","startMs":1017036,"endMs":1018863,"startSeconds":1017.036,"endSeconds":1018.863},{"id":"S256-01","cueId":"S256","sequence":256,"segmentIndex":1,"text":"可以取消旅行。","startMs":1018863,"endMs":1020141,"startSeconds":1018.863,"endSeconds":1020.141},{"id":"S257-01","cueId":"S257","sequence":257,"segmentIndex":1,"text":"但你不能取消吃飯。","startMs":1020141,"endMs":1021785,"startSeconds":1020.141,"endSeconds":1021.785},{"id":"S258-01","cueId":"S258","sequence":258,"segmentIndex":1,"text":"這就是飲食成本最強的地方。","startMs":1021785,"endMs":1024160,"startSeconds":1021.785,"endSeconds":1024.16},{"id":"S259-01","cueId":"S259","sequence":259,"segmentIndex":1,"text":"頻率太高。","startMs":1024340,"endMs":1025411,"startSeconds":1024.34,"endSeconds":1025.411},{"id":"S260-01","cueId":"S260","sequence":260,"segmentIndex":1,"text":"尤其剛進職場的年輕人，如果住處沒有廚房，","startMs":1025411,"endMs":1029696,"startSeconds":1025.411,"endSeconds":1029.696},{"id":"S260-02","cueId":"S260","sequence":260,"segmentIndex":2,"text":"或每天工作時間長，外食很容易從選擇變成日常。","startMs":1029696,"endMs":1034410,"startSeconds":1029.696,"endSeconds":1034.41},{"id":"S261-01","cueId":"S261","sequence":261,"segmentIndex":1,"text":"早餐、午餐、晚餐。","startMs":1034410,"endMs":1036338,"startSeconds":1034.41,"endSeconds":1036.338},{"id":"S262-01","cueId":"S262","sequence":262,"segmentIndex":1,"text":"每一餐只多10元，一天就是30元。","startMs":1036338,"endMs":1039980,"startSeconds":1036.338,"endSeconds":1039.98},{"id":"S263-01","cueId":"S263","sequence":263,"segmentIndex":1,"text":"一個月累積起來，感受就完全不同。","startMs":1040160,"endMs":1043049,"startSeconds":1040.16,"endSeconds":1043.049},{"id":"S264-01","cueId":"S264","sequence":264,"segmentIndex":1,"text":"2025年全年CPI平均上漲1.","startMs":1043049,"endMs":1045938,"startSeconds":1043.049,"endSeconds":1045.938},{"id":"S265-01","cueId":"S265","sequence":265,"segmentIndex":1,"text":"66%。","startMs":1045938,"endMs":1046661,"startSeconds":1045.938,"endSeconds":1046.661},{"id":"S266-01","cueId":"S266","sequence":266,"segmentIndex":1,"text":"但一個人的生活感受，不會完全等於總CPI。","startMs":1046661,"endMs":1050453,"startSeconds":1046.661,"endSeconds":1050.453},{"id":"S267-01","cueId":"S267","sequence":267,"segmentIndex":1,"text":"因為每個人的消費組合不同。","startMs":1050453,"endMs":1052800,"startSeconds":1050.453,"endSeconds":1052.8},{"id":"S268-01","cueId":"S268","sequence":268,"segmentIndex":1,"text":"如果你天天外食，你最在意的可能不是總指數，","startMs":1052980,"endMs":1056601,"startSeconds":1052.98,"endSeconds":1056.601},{"id":"S268-02","cueId":"S268","sequence":268,"segmentIndex":2,"text":"而是便當、早餐、飲料與餐廳價格。","startMs":1056601,"endMs":1059360,"startSeconds":1056.601,"endSeconds":1059.36},{"id":"S269-01","cueId":"S269","sequence":269,"segmentIndex":1,"text":"這也是為什麼我們不能只拿一個CPI數字，","startMs":1059360,"endMs":1062809,"startSeconds":1059.36,"endSeconds":1062.809},{"id":"S269-02","cueId":"S269","sequence":269,"segmentIndex":2,"text":"就說每個人的生活成本都增加一樣多。","startMs":1062809,"endMs":1065740,"startSeconds":1062.809,"endSeconds":1065.74},{"id":"S270-01","cueId":"S270","sequence":270,"segmentIndex":1,"text":"假設一位剛工作的青年，中午和同事一起吃飯。","startMs":1065920,"endMs":1069534,"startSeconds":1065.92,"endSeconds":1069.534},{"id":"S271-01","cueId":"S271","sequence":271,"segmentIndex":1,"text":"他不是每天都去高級餐廳。","startMs":1069534,"endMs":1071599,"startSeconds":1069.534,"endSeconds":1071.599},{"id":"S272-01","cueId":"S272","sequence":272,"segmentIndex":1,"text":"可能只是一個普通便當，再加一杯飲料。","startMs":1071599,"endMs":1074697,"startSeconds":1071.599,"endSeconds":1074.697},{"id":"S273-01","cueId":"S273","sequence":273,"segmentIndex":1,"text":"可是當每天都要做同一個選擇時，節省會慢慢變成習慣。","startMs":1074697,"endMs":1079000,"startSeconds":1074.697,"endSeconds":1079.0},{"id":"S274-01","cueId":"S274","sequence":274,"segmentIndex":1,"text":"今天不要加小菜。","startMs":1079180,"endMs":1080735,"startSeconds":1079.18,"endSeconds":1080.735},{"id":"S275-01","cueId":"S275","sequence":275,"segmentIndex":1,"text":"飲料改喝水。","startMs":1080735,"endMs":1081901,"startSeconds":1080.735,"endSeconds":1081.901},{"id":"S276-01","cueId":"S276","sequence":276,"segmentIndex":1,"text":"週末少吃一頓外面。","startMs":1081901,"endMs":1083651,"startSeconds":1081.901,"endSeconds":1083.651},{"id":"S277-01","cueId":"S277","sequence":277,"segmentIndex":1,"text":"這些調整看起來都很小。","startMs":1083651,"endMs":1085789,"startSeconds":1083.651,"endSeconds":1085.789},{"id":"S278-01","cueId":"S278","sequence":278,"segmentIndex":1,"text":"可是它們透露一件事。","startMs":1085789,"endMs":1087732,"startSeconds":1085.789,"endSeconds":1087.732},{"id":"S279-01","cueId":"S279","sequence":279,"segmentIndex":1,"text":"當收入有限，最基本的日常也會開始被計算。","startMs":1087732,"endMs":1091620,"startSeconds":1087.732,"endSeconds":1091.62},{"id":"S280-01","cueId":"S280","sequence":280,"segmentIndex":1,"text":"飲食排第2名，","startMs":1091800,"endMs":1093096,"startSeconds":1091.8,"endSeconds":1093.096},{"id":"S280-02","cueId":"S280","sequence":280,"segmentIndex":2,"text":"不是因為它一定占每個青年支出的第二高。","startMs":1093096,"endMs":1096612,"startSeconds":1093.096,"endSeconds":1096.612},{"id":"S281-01","cueId":"S281","sequence":281,"segmentIndex":1,"text":"而是因為它同時具有高頻率、高必要性，","startMs":1096612,"endMs":1099943,"startSeconds":1096.612,"endSeconds":1099.943},{"id":"S281-02","cueId":"S281","sequence":281,"segmentIndex":2,"text":"而且非常容易感受到價格變化。","startMs":1099943,"endMs":1102534,"startSeconds":1099.943,"endSeconds":1102.534},{"id":"S282-01","cueId":"S282","sequence":282,"segmentIndex":1,"text":"但即使一天吃三餐，至少每一餐還有便宜和昂貴的選擇。","startMs":1102534,"endMs":1107160,"startSeconds":1102.534,"endSeconds":1107.16},{"id":"S283-01","cueId":"S283","sequence":283,"segmentIndex":1,"text":"第1名真正麻煩的地方是，一旦簽下去，接下來幾個月，","startMs":1107340,"endMs":1112055,"startSeconds":1107.34,"endSeconds":1112.055},{"id":"S283-02","cueId":"S283","sequence":283,"segmentIndex":2,"text":"你很難每天重新選一次。","startMs":1112055,"endMs":1114129,"startSeconds":1112.055,"endSeconds":1114.129},{"id":"S284-01","cueId":"S284","sequence":284,"segmentIndex":1,"text":"12｜第1名｜一開始獨立，最大的帳單就來了｜","startMs":1114129,"endMs":1118277,"startSeconds":1114.129,"endSeconds":1118.277},{"id":"S284-02","cueId":"S284","sequence":284,"segmentIndex":2,"text":"居住與租屋","startMs":1118277,"endMs":1119220,"startSeconds":1118.277,"endSeconds":1119.22},{"id":"S285-01","cueId":"S285","sequence":285,"segmentIndex":1,"text":"第1名，居住與租屋。","startMs":1119400,"endMs":1121223,"startSeconds":1119.4,"endSeconds":1121.223},{"id":"S286-01","cueId":"S286","sequence":286,"segmentIndex":1,"text":"先說清楚。","startMs":1121223,"endMs":1122134,"startSeconds":1121.223,"endSeconds":1122.134},{"id":"S287-01","cueId":"S287","sequence":287,"segmentIndex":1,"text":"這不是主計總處公布的官方第一名。","startMs":1122134,"endMs":1125051,"startSeconds":1122.134,"endSeconds":1125.051},{"id":"S288-01","cueId":"S288","sequence":288,"segmentIndex":1,"text":"這是本片依支出規模、固定性、不可避免性，","startMs":1125051,"endMs":1128697,"startSeconds":1125.051,"endSeconds":1128.697},{"id":"S288-02","cueId":"S288","sequence":288,"segmentIndex":2,"text":"以及對剛離家青年的衝擊所做的分析排序。","startMs":1128697,"endMs":1132160,"startSeconds":1128.697,"endSeconds":1132.16},{"id":"S289-01","cueId":"S289","sequence":289,"segmentIndex":1,"text":"對仍和家人同住的九年級生來說，租金甚至可能是零。","startMs":1132340,"endMs":1137385,"startSeconds":1132.34,"endSeconds":1137.385},{"id":"S290-01","cueId":"S290","sequence":290,"segmentIndex":1,"text":"所以我們不能說「每個九年級生最大的支出都是房租」。","startMs":1137385,"endMs":1142640,"startSeconds":1137.385,"endSeconds":1142.64},{"id":"S291-01","cueId":"S291","sequence":291,"segmentIndex":1,"text":"但只要一個年輕人因為讀書、","startMs":1142640,"endMs":1145373,"startSeconds":1142.64,"endSeconds":1145.373},{"id":"S291-02","cueId":"S291","sequence":291,"segmentIndex":2,"text":"工作或想獨立生活而搬出去，","startMs":1145373,"endMs":1148106,"startSeconds":1145.373,"endSeconds":1148.106},{"id":"S291-03","cueId":"S291","sequence":291,"segmentIndex":3,"text":"居住成本就很容易立刻成為一張非常大的固定帳單。","startMs":1148106,"endMs":1152940,"startSeconds":1148.106,"endSeconds":1152.94},{"id":"S292-01","cueId":"S292","sequence":292,"segmentIndex":1,"text":"而且租屋的第一個月，通常不只有租金。","startMs":1153120,"endMs":1156444,"startSeconds":1153.12,"endSeconds":1156.444},{"id":"S293-01","cueId":"S293","sequence":293,"segmentIndex":1,"text":"還可能有押金。","startMs":1156444,"endMs":1157737,"startSeconds":1156.444,"endSeconds":1157.737},{"id":"S294-01","cueId":"S294","sequence":294,"segmentIndex":1,"text":"搬家。","startMs":1157737,"endMs":1158291,"startSeconds":1157.737,"endSeconds":1158.291},{"id":"S295-01","cueId":"S295","sequence":295,"segmentIndex":1,"text":"家具。","startMs":1158291,"endMs":1158845,"startSeconds":1158.291,"endSeconds":1158.845},{"id":"S296-01","cueId":"S296","sequence":296,"segmentIndex":1,"text":"生活用品。","startMs":1158845,"endMs":1159768,"startSeconds":1158.845,"endSeconds":1159.768},{"id":"S297-01","cueId":"S297","sequence":297,"segmentIndex":1,"text":"網路。","startMs":1159768,"endMs":1160322,"startSeconds":1159.768,"endSeconds":1160.322},{"id":"S298-01","cueId":"S298","sequence":298,"segmentIndex":1,"text":"水電。","startMs":1160322,"endMs":1160876,"startSeconds":1160.322,"endSeconds":1160.876},{"id":"S299-01","cueId":"S299","sequence":299,"segmentIndex":1,"text":"如果工作地點改變，又可能重新搬一次。","startMs":1160876,"endMs":1164200,"startSeconds":1160.876,"endSeconds":1164.2},{"id":"S300-01","cueId":"S300","sequence":300,"segmentIndex":1,"text":"這也是為什麼居住成本和青年人生選擇的關係特別強。","startMs":1164380,"endMs":1169611,"startSeconds":1164.38,"endSeconds":1169.611},{"id":"S301-01","cueId":"S301","sequence":301,"segmentIndex":1,"text":"一個人可能不是不想離家。","startMs":1169611,"endMs":1172227,"startSeconds":1169.611,"endSeconds":1172.227},{"id":"S302-01","cueId":"S302","sequence":302,"segmentIndex":1,"text":"而是算完之後發現，","startMs":1172227,"endMs":1174189,"startSeconds":1172.227,"endSeconds":1174.189},{"id":"S302-02","cueId":"S302","sequence":302,"segmentIndex":2,"text":"搬出去代表每個月先固定少掉一大塊可以運用的收入。","startMs":1174189,"endMs":1179420,"startSeconds":1174.189,"endSeconds":1179.42},{"id":"S303-01","cueId":"S303","sequence":303,"segmentIndex":1,"text":"假設一位24歲青年在台北找到工作。","startMs":1179600,"endMs":1182968,"startSeconds":1179.6,"endSeconds":1182.968},{"id":"S304-01","cueId":"S304","sequence":304,"segmentIndex":1,"text":"如果住家裡，通勤比較久，但可以少掉租金。","startMs":1182968,"endMs":1186930,"startSeconds":1182.968,"endSeconds":1186.93},{"id":"S305-01","cueId":"S305","sequence":305,"segmentIndex":1,"text":"如果搬到公司附近，生活時間增加，","startMs":1186930,"endMs":1190099,"startSeconds":1186.93,"endSeconds":1190.099},{"id":"S305-02","cueId":"S305","sequence":305,"segmentIndex":2,"text":"卻多了一筆固定支出。","startMs":1190099,"endMs":1192080,"startSeconds":1190.099,"endSeconds":1192.08},{"id":"S306-01","cueId":"S306","sequence":306,"segmentIndex":1,"text":"他做的其實不只是租屋選擇。","startMs":1192260,"endMs":1194637,"startSeconds":1192.26,"endSeconds":1194.637},{"id":"S307-01","cueId":"S307","sequence":307,"segmentIndex":1,"text":"他在選擇時間、隱私、自由和儲蓄之間怎麼交換。","startMs":1194637,"endMs":1198660,"startSeconds":1194.637,"endSeconds":1198.66},{"id":"S308-01","cueId":"S308","sequence":308,"segmentIndex":1,"text":"更重要的是，租金不像衣服。","startMs":1198660,"endMs":1201037,"startSeconds":1198.66,"endSeconds":1201.037},{"id":"S309-01","cueId":"S309","sequence":309,"segmentIndex":1,"text":"不能這個月先不買。","startMs":1201037,"endMs":1202683,"startSeconds":1201.037,"endSeconds":1202.683},{"id":"S310-01","cueId":"S310","sequence":310,"segmentIndex":1,"text":"也不像聚餐。","startMs":1202683,"endMs":1203780,"startSeconds":1202.683,"endSeconds":1203.78},{"id":"S311-01","cueId":"S311","sequence":311,"segmentIndex":1,"text":"不能臨時取消。","startMs":1203960,"endMs":1205294,"startSeconds":1203.96,"endSeconds":1205.294},{"id":"S312-01","cueId":"S312","sequence":312,"segmentIndex":1,"text":"一旦簽下租約，接下來每個月它都會準時出現。","startMs":1205294,"endMs":1209296,"startSeconds":1205.294,"endSeconds":1209.296},{"id":"S313-01","cueId":"S313","sequence":313,"segmentIndex":1,"text":"這種「固定、金額大、難延後」的特性，","startMs":1209296,"endMs":1212726,"startSeconds":1209.296,"endSeconds":1212.726},{"id":"S313-02","cueId":"S313","sequence":313,"segmentIndex":2,"text":"正是它在青年生活成本壓力指數中排到第1名的主要原因。","startMs":1212726,"endMs":1217680,"startSeconds":1212.726,"endSeconds":1217.68},{"id":"S314-01","cueId":"S314","sequence":314,"segmentIndex":1,"text":"但居住成本還有另一層。","startMs":1217860,"endMs":1220042,"startSeconds":1217.86,"endSeconds":1220.042},{"id":"S315-01","cueId":"S315","sequence":315,"segmentIndex":1,"text":"當一個年輕人因為租金而選擇繼續住家裡，","startMs":1220042,"endMs":1223810,"startSeconds":1220.042,"endSeconds":1223.81},{"id":"S315-02","cueId":"S315","sequence":315,"segmentIndex":2,"text":"統計上看起來，他沒有租金支出。","startMs":1223810,"endMs":1226785,"startSeconds":1223.81,"endSeconds":1226.785},{"id":"S316-01","cueId":"S316","sequence":316,"segmentIndex":1,"text":"可是這不代表居住問題不存在。","startMs":1226785,"endMs":1229562,"startSeconds":1226.785,"endSeconds":1229.562},{"id":"S317-01","cueId":"S317","sequence":317,"segmentIndex":1,"text":"成本有時候不是付出去的錢。","startMs":1229562,"endMs":1232140,"startSeconds":1229.562,"endSeconds":1232.14},{"id":"S318-01","cueId":"S318","sequence":318,"segmentIndex":1,"text":"而是因為付不起，所以沒有做出的選擇。","startMs":1232320,"endMs":1235624,"startSeconds":1232.32,"endSeconds":1235.624},{"id":"S319-01","cueId":"S319","sequence":319,"segmentIndex":1,"text":"沒有搬家。","startMs":1235624,"endMs":1236542,"startSeconds":1235.624,"endSeconds":1236.542},{"id":"S320-01","cueId":"S320","sequence":320,"segmentIndex":1,"text":"沒有離工作更近。","startMs":1236542,"endMs":1238010,"startSeconds":1236.542,"endSeconds":1238.01},{"id":"S321-01","cueId":"S321","sequence":321,"segmentIndex":1,"text":"沒有得到自己想要的生活空間。","startMs":1238010,"endMs":1240580,"startSeconds":1238.01,"endSeconds":1240.58},{"id":"S322-01","cueId":"S322","sequence":322,"segmentIndex":1,"text":"這也是本集從第10名一路排到第1名，","startMs":1240580,"endMs":1243884,"startSeconds":1240.58,"endSeconds":1243.884},{"id":"S322-02","cueId":"S322","sequence":322,"segmentIndex":2,"text":"最後真正想說的事情。","startMs":1243884,"endMs":1245720,"startSeconds":1243.884,"endSeconds":1245.72},{"id":"S323-01","cueId":"S323","sequence":323,"segmentIndex":1,"text":"生活成本真正改變的，不只是帳戶。","startMs":1245900,"endMs":1249034,"startSeconds":1245.9,"endSeconds":1249.034},{"id":"S324-01","cueId":"S324","sequence":324,"segmentIndex":1,"text":"它也會改變一個人敢不敢選。","startMs":1249034,"endMs":1251581,"startSeconds":1249.034,"endSeconds":1251.581},{"id":"S325-01","cueId":"S325","sequence":325,"segmentIndex":1,"text":"13｜結尾｜真正昂貴的，","startMs":1251581,"endMs":1253931,"startSeconds":1251.581,"endSeconds":1253.931},{"id":"S325-02","cueId":"S325","sequence":325,"segmentIndex":2,"text":"也許是選擇變少回頭看今天的十大。","startMs":1253931,"endMs":1257065,"startSeconds":1253.931,"endSeconds":1257.065},{"id":"S326-01","cueId":"S326","sequence":326,"segmentIndex":1,"text":"第10名，衣著與鞋類。","startMs":1257065,"endMs":1259220,"startSeconds":1257.065,"endSeconds":1259.22},{"id":"S327-01","cueId":"S327","sequence":327,"segmentIndex":1,"text":"第9名，手機與通訊。","startMs":1259400,"endMs":1261417,"startSeconds":1259.4,"endSeconds":1261.417},{"id":"S328-01","cueId":"S328","sequence":328,"segmentIndex":1,"text":"第8名，醫療與保健。","startMs":1261417,"endMs":1263435,"startSeconds":1261.417,"endSeconds":1263.435},{"id":"S329-01","cueId":"S329","sequence":329,"segmentIndex":1,"text":"第7名，教育與技能進修。","startMs":1263435,"endMs":1265856,"startSeconds":1263.435,"endSeconds":1265.856},{"id":"S330-01","cueId":"S330","sequence":330,"segmentIndex":1,"text":"第6名，社交與休閒。","startMs":1265856,"endMs":1267873,"startSeconds":1265.856,"endSeconds":1267.873},{"id":"S331-01","cueId":"S331","sequence":331,"segmentIndex":1,"text":"第5名，日用品與家務支出。","startMs":1267873,"endMs":1270496,"startSeconds":1267.873,"endSeconds":1270.496},{"id":"S332-01","cueId":"S332","sequence":332,"segmentIndex":1,"text":"第4名，水電瓦斯與居住能源。","startMs":1270496,"endMs":1273320,"startSeconds":1270.496,"endSeconds":1273.32},{"id":"S333-01","cueId":"S333","sequence":333,"segmentIndex":1,"text":"第3名，交通與通勤。","startMs":1273500,"endMs":1275445,"startSeconds":1273.5,"endSeconds":1275.445},{"id":"S334-01","cueId":"S334","sequence":334,"segmentIndex":1,"text":"第2名，飲食與外食。","startMs":1275445,"endMs":1277389,"startSeconds":1275.445,"endSeconds":1277.389},{"id":"S335-01","cueId":"S335","sequence":335,"segmentIndex":1,"text":"第1名，居住與租屋。","startMs":1277389,"endMs":1279334,"startSeconds":1277.389,"endSeconds":1279.334},{"id":"S336-01","cueId":"S336","sequence":336,"segmentIndex":1,"text":"這個排名不是政府公布的標準答案。","startMs":1279334,"endMs":1282445,"startSeconds":1279.334,"endSeconds":1282.445},{"id":"S337-01","cueId":"S337","sequence":337,"segmentIndex":1,"text":"甚至對不同年輕人來說，順序一定會改變。","startMs":1282445,"endMs":1286140,"startSeconds":1282.445,"endSeconds":1286.14},{"id":"S338-01","cueId":"S338","sequence":338,"segmentIndex":1,"text":"住家裡的人，租金可能不是第一名。","startMs":1286320,"endMs":1289289,"startSeconds":1286.32,"endSeconds":1289.289},{"id":"S339-01","cueId":"S339","sequence":339,"segmentIndex":1,"text":"每天騎車長距離通勤的人，交通可能更有感。","startMs":1289289,"endMs":1293001,"startSeconds":1289.289,"endSeconds":1293.001},{"id":"S340-01","cueId":"S340","sequence":340,"segmentIndex":1,"text":"需要長期醫療的人，醫療支出也可能直接往前排。","startMs":1293001,"endMs":1297084,"startSeconds":1293.001,"endSeconds":1297.084},{"id":"S341-01","cueId":"S341","sequence":341,"segmentIndex":1,"text":"所以這支影片真正重要的，","startMs":1297084,"endMs":1299311,"startSeconds":1297.084,"endSeconds":1299.311},{"id":"S341-02","cueId":"S341","sequence":341,"segmentIndex":2,"text":"不是爭論第3名到底應該排第4名。","startMs":1299311,"endMs":1302280,"startSeconds":1299.311,"endSeconds":1302.28},{"id":"S342-01","cueId":"S342","sequence":342,"segmentIndex":1,"text":"而是看見一件更大的事。","startMs":1302460,"endMs":1304490,"startSeconds":1302.46,"endSeconds":1304.49},{"id":"S343-01","cueId":"S343","sequence":343,"segmentIndex":1,"text":"生活成本從來不是一張只有「價格」的表。","startMs":1304490,"endMs":1307996,"startSeconds":1304.49,"endSeconds":1307.996},{"id":"S344-01","cueId":"S344","sequence":344,"segmentIndex":1,"text":"它會和收入、家庭支持、居住地點、工作地點、","startMs":1307996,"endMs":1311871,"startSeconds":1307.996,"endSeconds":1311.871},{"id":"S344-02","cueId":"S344","sequence":344,"segmentIndex":2,"text":"健康狀況，以及一個人目前在人生哪個階段綁在一起。","startMs":1311871,"endMs":1316300,"startSeconds":1311.871,"endSeconds":1316.3},{"id":"S345-01","cueId":"S345","sequence":345,"segmentIndex":1,"text":"2025年，台灣全年CPI平均上漲1.","startMs":1316480,"endMs":1320232,"startSeconds":1316.48,"endSeconds":1320.232},{"id":"S346-01","cueId":"S346","sequence":346,"segmentIndex":1,"text":"66%。","startMs":1320232,"endMs":1321022,"startSeconds":1320.232,"endSeconds":1321.022},{"id":"S347-01","cueId":"S347","sequence":347,"segmentIndex":1,"text":"同一年，薪資統計也顯示整體經常性薪資持續成長。","startMs":1321022,"endMs":1325565,"startSeconds":1321.022,"endSeconds":1325.565},{"id":"S348-01","cueId":"S348","sequence":348,"segmentIndex":1,"text":"這兩件事可以同時成立。","startMs":1325565,"endMs":1327738,"startSeconds":1325.565,"endSeconds":1327.738},{"id":"S349-01","cueId":"S349","sequence":349,"segmentIndex":1,"text":"薪資可以增加。","startMs":1327738,"endMs":1329120,"startSeconds":1327.738,"endSeconds":1329.12},{"id":"S350-01","cueId":"S350","sequence":350,"segmentIndex":1,"text":"物價也可以增加。","startMs":1329300,"endMs":1330630,"startSeconds":1329.3,"endSeconds":1330.63},{"id":"S351-01","cueId":"S351","sequence":351,"segmentIndex":1,"text":"而一個人仍然可能覺得生活很緊。","startMs":1330630,"endMs":1333124,"startSeconds":1330.63,"endSeconds":1333.124},{"id":"S352-01","cueId":"S352","sequence":352,"segmentIndex":1,"text":"因為平均數不是每個人的人生。","startMs":1333124,"endMs":1335451,"startSeconds":1333.124,"endSeconds":1335.451},{"id":"S353-01","cueId":"S353","sequence":353,"segmentIndex":1,"text":"尤其對剛進社會的人來說，","startMs":1335451,"endMs":1337446,"startSeconds":1335.451,"endSeconds":1337.446},{"id":"S353-02","cueId":"S353","sequence":353,"segmentIndex":2,"text":"問題往往不只是「有沒有收入」。","startMs":1337446,"endMs":1339940,"startSeconds":1337.446,"endSeconds":1339.94},{"id":"S354-01","cueId":"S354","sequence":354,"segmentIndex":1,"text":"而是收入還不高的那幾年，","startMs":1340120,"endMs":1342108,"startSeconds":1340.12,"endSeconds":1342.108},{"id":"S354-02","cueId":"S354","sequence":354,"segmentIndex":2,"text":"很多生活成本已經和所有成年人一樣真實。","startMs":1342108,"endMs":1345255,"startSeconds":1342.108,"endSeconds":1345.255},{"id":"S355-01","cueId":"S355","sequence":355,"segmentIndex":1,"text":"房東不會因為你剛畢業，就把租金打五折。","startMs":1345255,"endMs":1348402,"startSeconds":1345.255,"endSeconds":1348.402},{"id":"S356-01","cueId":"S356","sequence":356,"segmentIndex":1,"text":"便當店不會因為你是第一份工作，就收學生價。","startMs":1348402,"endMs":1351880,"startSeconds":1348.402,"endSeconds":1351.88},{"id":"S357-01","cueId":"S357","sequence":357,"segmentIndex":1,"text":"水電、交通、手機，也不會先等你加薪三年再開始計費。","startMs":1352060,"endMs":1356573,"startSeconds":1352.06,"endSeconds":1356.573},{"id":"S358-01","cueId":"S358","sequence":358,"segmentIndex":1,"text":"這就是九年級生進社會之後，","startMs":1356573,"endMs":1358919,"startSeconds":1356.573,"endSeconds":1358.919},{"id":"S358-02","cueId":"S358","sequence":358,"segmentIndex":2,"text":"第一次真正理解的生活成本。","startMs":1358919,"endMs":1361266,"startSeconds":1358.919,"endSeconds":1361.266},{"id":"S359-01","cueId":"S359","sequence":359,"segmentIndex":1,"text":"以前父母說「生活什麼都要錢」","startMs":1361266,"endMs":1363793,"startSeconds":1361.266,"endSeconds":1363.793},{"id":"S359-02","cueId":"S359","sequence":359,"segmentIndex":2,"text":"，可能只是一句很普通的話。","startMs":1363793,"endMs":1366140,"startSeconds":1363.793,"endSeconds":1366.14},{"id":"S360-01","cueId":"S360","sequence":360,"segmentIndex":1,"text":"直到自己開始付，才知道那不是一句抱怨。","startMs":1366320,"endMs":1370022,"startSeconds":1366.32,"endSeconds":1370.022},{"id":"S361-01","cueId":"S361","sequence":361,"segmentIndex":1,"text":"那是一張很長的清單。","startMs":1370022,"endMs":1371971,"startSeconds":1370.022,"endSeconds":1371.971},{"id":"S362-01","cueId":"S362","sequence":362,"segmentIndex":1,"text":"可是這一集也不是要說，年輕人的未來只剩下悲觀。","startMs":1371971,"endMs":1376453,"startSeconds":1371.971,"endSeconds":1376.453},{"id":"S363-01","cueId":"S363","sequence":363,"segmentIndex":1,"text":"真正有用的理解，是知道壓力從哪裡來。","startMs":1376453,"endMs":1379960,"startSeconds":1376.453,"endSeconds":1379.96},{"id":"S364-01","cueId":"S364","sequence":364,"segmentIndex":1,"text":"哪些成本能調整。","startMs":1380140,"endMs":1381793,"startSeconds":1380.14,"endSeconds":1381.793},{"id":"S365-01","cueId":"S365","sequence":365,"segmentIndex":1,"text":"哪些成本只能接受。","startMs":1381793,"endMs":1383653,"startSeconds":1381.793,"endSeconds":1383.653},{"id":"S366-01","cueId":"S366","sequence":366,"segmentIndex":1,"text":"哪些選擇值得花錢。","startMs":1383653,"endMs":1385513,"startSeconds":1383.653,"endSeconds":1385.513},{"id":"S367-01","cueId":"S367","sequence":367,"segmentIndex":1,"text":"哪些支出其實可以換一種方式。","startMs":1385513,"endMs":1388407,"startSeconds":1385.513,"endSeconds":1388.407},{"id":"S368-01","cueId":"S368","sequence":368,"segmentIndex":1,"text":"當一個人看懂自己的生活成本，他至少開始有能力決定，","startMs":1388407,"endMs":1393573,"startSeconds":1388.407,"endSeconds":1393.573},{"id":"S368-02","cueId":"S368","sequence":368,"segmentIndex":2,"text":"有限的收入要優先保住什麼。","startMs":1393573,"endMs":1396260,"startSeconds":1393.573,"endSeconds":1396.26},{"id":"S369-01","cueId":"S369","sequence":369,"segmentIndex":1,"text":"也許是住得離公司近一點。","startMs":1396440,"endMs":1398779,"startSeconds":1396.44,"endSeconds":1398.779},{"id":"S370-01","cueId":"S370","sequence":370,"segmentIndex":1,"text":"也許是繼續住家裡，把錢留下來進修。","startMs":1398779,"endMs":1402093,"startSeconds":1398.779,"endSeconds":1402.093},{"id":"S371-01","cueId":"S371","sequence":371,"segmentIndex":1,"text":"也許是不追新手機，但保留一年一次的旅行。","startMs":1402093,"endMs":1405992,"startSeconds":1402.093,"endSeconds":1405.992},{"id":"S372-01","cueId":"S372","sequence":372,"segmentIndex":1,"text":"也許是少一點外食，換一筆真正屬於自己的儲蓄。","startMs":1405992,"endMs":1410280,"startSeconds":1405.992,"endSeconds":1410.28},{"id":"S373-01","cueId":"S373","sequence":373,"segmentIndex":1,"text":"所以最後，","startMs":1410460,"endMs":1411567,"startSeconds":1410.46,"endSeconds":1411.567},{"id":"S373-02","cueId":"S373","sequence":373,"segmentIndex":2,"text":"我想把問題留給每一個正在開始自己生活的人。","startMs":1411567,"endMs":1416217,"startSeconds":1411.567,"endSeconds":1416.217},{"id":"S374-01","cueId":"S374","sequence":374,"segmentIndex":1,"text":"真正昂貴的，到底是什麼？","startMs":1416217,"endMs":1418874,"startSeconds":1416.217,"endSeconds":1418.874},{"id":"S375-01","cueId":"S375","sequence":375,"segmentIndex":1,"text":"是一間房？","startMs":1418874,"endMs":1419981,"startSeconds":1418.874,"endSeconds":1419.981},{"id":"S376-01","cueId":"S376","sequence":376,"segmentIndex":1,"text":"是一頓飯？","startMs":1419981,"endMs":1421088,"startSeconds":1419.981,"endSeconds":1421.088},{"id":"S377-01","cueId":"S377","sequence":377,"segmentIndex":1,"text":"是一張車票？","startMs":1421088,"endMs":1422416,"startSeconds":1421.088,"endSeconds":1422.416},{"id":"S378-01","cueId":"S378","sequence":378,"segmentIndex":1,"text":"還是當每一項必要支出，都先從收入裡拿走一部分之後，","startMs":1422416,"endMs":1427952,"startSeconds":1422.416,"endSeconds":1427.952},{"id":"S378-02","cueId":"S378","sequence":378,"segmentIndex":2,"text":"你發現自己可以選擇的人生，正在慢慢變少？","startMs":1427952,"endMs":1432380,"startSeconds":1427.952,"endSeconds":1432.38},{"id":"S379-01","cueId":"S379","sequence":379,"segmentIndex":1,"text":"生活成本真正影響的，從來不只是你還剩多少錢。","startMs":1432560,"endMs":1436710,"startSeconds":1432.56,"endSeconds":1436.71},{"id":"S380-01","cueId":"S380","sequence":380,"segmentIndex":1,"text":"而是你還剩多少空間，可以決定自己想過什麼樣的生活。","startMs":1436710,"endMs":1441427,"startSeconds":1436.71,"endSeconds":1441.427},{"id":"S381-01","cueId":"S381","sequence":381,"segmentIndex":1,"text":"這就是台灣九年級生的高難度人生，第4集。","startMs":1441427,"endMs":1445200,"startSeconds":1441.427,"endSeconds":1445.2},{"id":"S382-01","cueId":"S382","sequence":382,"segmentIndex":1,"text":"台灣十大，九年級生進社會後最有感的十種生活成本。","startMs":1445380,"endMs":1450100,"startSeconds":1445.38,"endSeconds":1450.1}]});
